local config = {
  ui_story_5070_50700101_1_dialog_content = "¡Ahh! Esto es realmente malo...",
  ui_story_5070_50700101_2_dialog_content = "Casi hemos agotado nuestros fondos de reserva.",
  ui_story_5070_50700101_3_dialog_content = "He estado demasiado ocupado para aceptar trabajos últimamente, y Soroz acaba de recibir mantenimiento...",
  ui_story_5070_50700101_4_dialog_content = "De alguna manera, gastamos casi todo nuestro dinero.",
  ui_story_5070_50700101_5_dialog_content = "Si Vice se entera, me va a poner a comer galletas de ración y café instantáneo a punto de caducar en cada comida otra vez—",
  ui_story_5070_50700101_6_dialog_content = "¿Oh? ¿Qué tenemos aquí?",
  ui_story_5070_50700101_7_dialog_content = "Vice! No es nada, sólo...",
  ui_story_5070_50700101_8_dialog_content = "Es solo que estamos al borde de la bancarrota, así que tenemos que reactivar nuestros protocolos de racionamiento en tiempos de guerra. ¿Es eso?",
  ui_story_5070_50700101_9_dialog_content = "... Entonces ya lo sabías.",
  ui_story_5070_50700101_10_dialog_content = "Sería aún más raro si no lo hiciera...",
  ui_story_5070_50700101_11_dialog_content = "La verdad, necesitas hacer un mejor trabajo llevando un registro de los gastos del Colossus. No puedo estar aquí para ayudar todo el tiempo, ya sabes.",
  ui_story_5070_50700101_12_dialog_content = "Aun así, parece que el destino está de nuestro lado. ¡Mira esto!",
  ui_story_5070_50700101_13_dialog_content = "Un mensajero acaba de traernos un mensaje urgente del Gremio Lin—",
  ui_story_5070_50700101_14_dialog_content = "\"Querido PlayerName, el siguiente asunto concierne al futuro mismo de nuestro gremio. Como tal, es nuestro más sincero deseo...\"",
  ui_story_5070_50700101_15_dialog_content = "\"...que como Navegador del Colossus y maestro de las artes psíquicas, por favor, préstanos tu ayuda.\"",
  ui_story_5070_50700101_16_dialog_content = "El Gremio Lin nos ha ayudado muchas veces antes, ¡pero ahora necesitan nuestra ayuda! ¡También ofrecen una gran recompensa!",
  ui_story_5070_50700101_17_dialog_content = "¿Una oportunidad para mejorar nuestra relación con la familia Lin Y ganar mucho dinero?",
  ui_story_5070_50700101_18_dialog_content = "¡Suena genial! ¡Trazaré un rumbo hacia Umbraton de inmediato!",
  ui_story_5070_50700101_19_dialog_content = "Espera, el trabajo no está en Umbraton esta vez.",
  ui_story_5070_50700101_20_dialog_content = "Está en Twin Pavilions Bay.",
  ui_story_5070_50700101_21_dialog_content = "Pero si el trabajo concierne al futuro completo del gremio Lin, ¿por qué no iríamos primero a su sede?",
  ui_story_5070_50700101_22_dialog_content = "Porque según ellos, Twin Pavilions Bay es igual de importante que Umbraton... si no es que más.",
  ui_story_5070_50700101_23_dialog_content = "¡¿Carleen?! ¡Pensé que todavía estabas leyendo en tu habitación!",
  ui_story_5070_50700101_24_dialog_content = "Todavía tengo suficiente tiempo libre para acompañarte esta vez... Además, soy el único aquí que conoce Twin Pavilions Bay.",
  ui_story_5070_50700101_25_dialog_content = "Para Lumopolis, el comercio entre Twin Pavilions Bay y Umbraton es vital para la economía.",
  ui_story_5070_50700101_26_dialog_content = "La lejana tierra de Longzhou trae todo tipo de productos a nuestras costas...",
  ui_story_5070_50700101_27_dialog_content = "Incluyendo muchos productos valiosos y habilidades que no tenemos forma de reproducir aquí en Astra.",
  ui_story_5070_50700101_28_dialog_content = "El gremio Lin también es de Longzhou.",
  ui_story_5070_50700101_29_dialog_content = "Después de enfrentarse al vasto océano para llegar aquí, el lugar donde pisaron tierra por primera vez fue nada menos que Twin Pavilions Bay.",
  ui_story_5070_50700101_30_dialog_content = "Hasta el día de hoy, sirve como el único puerto accesible de Astra para los barcos mercantes de Longzhou. De alguna manera, es la base de las operaciones comerciales de la familia Lin.",
  ui_story_5070_50700101_31_dialog_content = "Teniendo en cuenta lo urgente que suena esta invitación, no creo que exageren cuando dicen que <color=#FFB400>el futuro del gremio Lin</color> está en juego.",
  ui_story_5070_50700101_32_dialog_content = "Entonces deberíamos ir allí lo antes posible.",
  ui_story_5070_50700101_33_dialog_content = "Pero, ¿dónde exactamente está Twin Pavilions Bay?",
  ui_story_5070_50700101_34_dialog_content = "Permíteme mostrarte el camino.",
  ui_story_5070_50700101_35_dialog_content = "Podemos llegar allí rápidamente siguiendo el Río de Oro hasta su fuente.",
  ui_story_5070_50700101_36_dialog_content = "¡Increíble! Twin Pavilions Bay no se parece a ningún otro lugar en Astra.",
  ui_story_5070_50700101_37_dialog_content = "Es como si alguien tomara un lugar de un mundo totalmente diferente y lo dejara caer justo aquí.",
  ui_story_5070_50700101_38_dialog_content = "También solo he leído sobre ello en libros.",
  ui_story_5070_50700101_39_dialog_content = "La familia Lin lideró el desarrollo de esta área junto con las personas que primero viajaron por la ruta oceánica que establecieron.",
  ui_story_5070_50700101_40_dialog_content = "Como resultado, cada vez más visitantes de Longzhou comenzaron a llegar aquí.",
  ui_story_5070_50700101_41_dialog_content = "Esto, a su vez, llevó a la creación de una ciudad al estilo de Longzhou en las costas de Astra.",
  ui_story_5070_50700101_42_dialog_content = "... Es aún más maravilloso en persona que las descripciones en nuestros libros.",
  ui_story_5070_50700101_43_dialog_content = "Bollos al vapor, ¡recién salidos de la estufa! ¡Humientes y llenos de deliciosa carne! ¿Les gustaría probar algunos bollos al vapor, amigos?",
  ui_story_5070_50700101_44_dialog_content = "Recién llegados viajeros, ¿verdad? ¡Entonces deben probar nuestro té!",
  ui_story_5070_50700101_45_dialog_content = "Pre-Lluvia Longjing, Yunmeng Brotes de Plata, Infinitas Hojas Grandes e incluso Danshan Oolong: ¡tenemos todo tipo de té famoso, directamente de los campos de Longzhou!",
  ui_story_5070_50700101_46_dialog_content = "¡Huele increíble aquí!",
  ui_story_5070_50700101_47_dialog_content = "¡Hay tantas cosas que nunca he visto antes! Cuando terminemos nuestro trabajo, definitivamente tenemos que volver para hacer algunas compras.",
  ui_story_5070_50700101_48_dialog_content = "Hablando del trabajo, ¿decía la carta algo sobre dónde encontrar el gremio?",
  ui_story_5070_50700101_49_dialog_content = "<color=#e8d9bb>De repente, una ráfaga de viento pasa.</color>",
  ui_story_5070_50700101_50_dialog_content = "¡Mi carta—!!!",
  ui_story_5070_50700101_51_dialog_content = "¿E-Eh? ¿Esa libélula dorada agarró mi carta?",
  ui_story_5070_50700101_52_dialog_content = "Espera, esto no es una libélula normal... ¿esta cosa está hecha de metal?",
  ui_story_5070_50700101_53_dialog_content = "Si fuera tú, sujetaría las cosas con más cuidado.",
  ui_story_5070_50700101_54_dialog_content = "Oh, uh... Gracias.",
  ui_story_5070_50700101_55_dialog_content = "¡No lo menciones!",
  ui_story_5070_50700101_56_dialog_content = "... ¿Era eso otra especialidad de Longzhou?",
  ui_story_5070_50700101_57_dialog_content = "¡Ahí estás! Perdona, pero ¿eres PlayerName?",
  ui_story_5070_50700101_58_dialog_content = "Sí, soy yo. ¡Vine a ayudar a los Lins!",
  ui_story_5070_50700101_59_dialog_content = "Soy un representante del Lin Guild. Estamos muy agradecidos por tu ayuda. Ahora, si no te importa, continuaré y discutiré los detalles contigo.",
  ui_story_5070_50700101_60_dialog_content = "Estoy seguro de que todos están un poco familiarizados con el gremio Lin, ¿verdad?",
  ui_story_5070_50700101_61_dialog_content = "Nos especializamos en el transporte y distribución de productos y tecnología de Longzhou que normalmente no se encuentran en Astra.",
  ui_story_5070_50700101_62_dialog_content = "Sin embargo, el vasto océano que divide nuestros dos continentes está lleno de peligros.",
  ui_story_5070_50700101_63_dialog_content = "Tal como está, solo los barcos de la familia Lin pueden realizar viajes estacionales a lo largo de las rutas establecidas por los antepasados.",
  ui_story_5070_50700101_64_dialog_content = "Pero el Shadowind, uno de nuestros barcos mercantes más importantes, no ha sido visto en más de medio año por razones aún desconocidas.",
  ui_story_5070_50700101_65_dialog_content = "¿Sin contacto durante más de medio año? ¿Podría haber pasado algo en Longzhou?",
  ui_story_5070_50700101_66_dialog_content = "Nosotros... tampoco tenemos forma de saber eso.",
  ui_story_5070_50700101_67_dialog_content = "Actualmente, la única forma de que la información viaje entre nuestras dos tierras es a través de los barcos mercantes de la familia Lin.",
  ui_story_5070_50700101_68_dialog_content = "Incluso el propio Lin Guild no tiene otra forma de comunicarse con su gente en Longzhou.",
  ui_story_5070_50700101_69_dialog_content = "Lamentablemente, la señorita Carleen tiene razón.",
  ui_story_5070_50700101_70_dialog_content = "Ni Astra ni Longzhou han desarrollado un dispositivo de comunicación capaz de abarcar el vasto océano entre ellos.",
  ui_story_5070_50700101_71_dialog_content = "Sin embargo, hace dos días, recibimos una señal desde el agua, una que se utiliza internamente por la familia Lin.",
  ui_story_5070_50700101_72_dialog_content = "¡Creemos que vino de uno de los barcos comerciantes que llegaron esta temporada!",
  ui_story_5070_50700101_73_dialog_content = "Pero la señal desapareció repentinamente antes de que pudiéramos responder, y no hemos recibido nada parecido desde entonces.",
  ui_story_5070_50700101_74_dialog_content = "Ya veo. Quieres que usemos el Coloso para buscar el barco desaparecido, ¿verdad?",
  ui_story_5070_50700101_75_dialog_content = "¡Precisamente! Dadas las circunstancias, ¡eres nuestra mejor esperanza para encontrarlo!",
  ui_story_5070_50700101_76_dialog_content = "Entendido. Haremos todo lo que podamos.",
  ui_story_5070_50700101_77_dialog_content = "(Durante los siguientes días, exploramos el océano desde lo alto del Coloso en busca de alguna señal del barco mercante.)",
  ui_story_5070_50700101_78_dialog_content = "Hemos buscado en cada rincón del mar alrededor del puerto, pero no hemos visto ni siquiera un pedazo de madera flotante por aquí.",
  ui_story_5070_50700101_79_dialog_content = "Al menos, podemos descartar que el barco desaparezca en las aguas cercanas. Eso es una buena noticia, ¿verdad?",
  ui_story_5070_50700101_80_dialog_content = "Sí, pero ahora parece que nuestra única opción es buscar aún más lejos.",
  ui_story_5070_50700101_81_dialog_content = "¿Está bien eso, PlayerName?",
  ui_story_5070_50700101_82_dialog_content = "Para ser honesto, no tengo mucha confianza en esto...",
  ui_story_5070_50700101_83_dialog_content = "Tal como está, Soroz no está preparado para enfrentar tormentas inesperadas en alta mar.",
  ui_story_5070_50700101_84_dialog_content = "Tampoco tengo mucha experiencia allí. Lo más lejos que he estado del continente es Cloud Island.",
  ui_story_5070_50700101_85_dialog_content = "Si el barco desapareciera aún más lejos, rescatarlos sería aún más difícil.",
  ui_story_5070_50700101_86_dialog_content = "...",
  ui_story_5070_50700101_87_dialog_content = "¿Eh? ¿Por qué ustedes dos me miran en silencio así?",
  ui_story_5070_50700101_88_dialog_content = "Porque eres tú quien habla, y usualmente...",
  ui_story_5070_50700101_89_dialog_content = "incluso cuando no hay esperanza, tú logras idear algo, ¿verdad?",
  ui_story_5070_50700101_90_dialog_content = "Creo que ustedes están sobreestimando mi resiliencia... Pero, tienen razón.",
  ui_story_5070_50700101_91_dialog_content = "Aceptamos el trabajo, después de todo. Lo menos que podemos hacer es intentar dar lo mejor de nosotros.",
  ui_story_5070_50700101_92_dialog_content = "Usaré todo mi poder para escanear la mayor parte del mar que nos rodea. Ojalá logre encontrar algo.",
  ui_story_5070_50700101_93_option_content = "¡Potencia de fuerza!",
  ui_story_5070_50700101_94_dialog_content = "En la dirección del viento... ¡Sí! Hay un gran número de Aurorianos en esa dirección allí.",
  ui_story_5070_50700101_95_dialog_content = "¡El océano abundante provee! Parece que finalmente tenemos una pista ahora.",
  ui_story_5070_50700101_96_dialog_content = "Esperen, ustedes dos, miren allá. Los cielos se oscurecen, pero el mar detrás de nosotros está tan tranquilo y quieto como un espejo.",
  ui_story_5070_50700101_97_dialog_content = "¡Hay una tormenta acercándose desde adelante!",
  ui_story_5070_50700101_98_dialog_content = "¡Veo el barco! ¡Es enorme!",
  ui_story_5070_50700101_99_dialog_content = "Es un barco mercante de la familia Lin.",
  ui_story_5070_50700101_100_dialog_content = "¡Tenemos que salvarlos! Pero no sé si el Coloso puede–",
  ui_story_5070_50700101_101_dialog_content = "Espera, PlayerName.",
  ui_story_5070_50700101_102_dialog_content = "Echa un vistazo más de cerca.",
  ui_story_5070_50700101_103_dialog_content = "La gente en el barco... puedo sentir que están un poco nerviosos, pero no están entrando en pánico en absoluto.",
  ui_story_5070_50700101_104_dialog_content = "Los pasajeros en la cubierta también se mueven con un propósito claro. Es como si alguien dirigiera sus acciones con mano firme.",
  ui_story_5070_50700101_105_dialog_content = "¡C-Capitán! Parece que hay algo volando por encima de nuestras cabezas...",
  ui_story_5070_50700101_106_dialog_content = "No te preocupes por eso ahora. Continúa ajustando los obenques del barco y mantén el timón estable.",
  ui_story_5070_50700101_107_dialog_content = "Mantén tus ojos en la superficie del agua.",
  ui_story_5070_50700101_108_dialog_content = "¡Nos estamos abriendo paso!",
  ui_story_5070_50700101_109_dialog_content = "¡Ey ey, capitán!",
  ui_story_5070_50700101_110_dialog_content = "<color=#e8d9bb>Las mareas aumentan mientras olas colosales se levantan y chocan con un estruendo ensordecedor.</color>",
  ui_story_5070_50700101_111_dialog_content = "<color=#e8d9bb>Pero justo cuando las olas embravecidas convergen en un mortal remolino, ¡el barco logra romper y llegar a la seguridad!</color>",
  ui_story_5070_50700101_112_dialog_content = "¡Gracias a Dios que lograron salir!",
  ui_story_5070_50700101_113_dialog_content = "Uf...",
  ui_story_5070_50700101_114_dialog_content = "¡Eso estuvo demasiado cerca! ¡Pensé que mi corazón iba a dejar de latir!",
  ui_story_5070_50700101_115_dialog_content = "El capitán de ese barco debe ser una persona increíble.",
  ui_story_5070_50700101_116_dialog_content = "El casco del barco está cubierto de daños. Debe haber soportado muchas tormentas en su camino hasta aquí.",
  ui_story_5070_50700101_117_dialog_content = "Me sorprende que pueda navegar tan suavemente.",
  ui_story_5070_50700101_118_dialog_content = "El resto del viaje debería ser lo suficientemente tranquilo. No creo que se encuentren con más peligros.",
  ui_story_5070_50700101_119_dialog_content = "Acompañémoslo el resto del camino de regreso antes de encontrar un lugar para aterrizar.",
  ui_story_5070_50700101_120_dialog_content = "¡Es el Shadowind! ¡Finalmente ha vuelto!",
  ui_story_5070_50700101_121_dialog_content = "¡Se ve diferente que antes!",
  ui_story_5070_50700101_122_dialog_content = "¿Qué te parece? Eso es porque es un barco completamente diferente al Shadowind anterior.",
  ui_story_5070_50700101_123_dialog_content = "Hace años, había rumores de que Ye estaba desarrollando un núcleo mecánico completamente nuevo para los barcos más grandes de Ji...",
  ui_story_5070_50700101_124_dialog_content = "¡Esto debe ser uno de esos barcos nuevos y mejorados!",
  ui_story_5070_50700101_125_dialog_content = "¡Más fuerte, rápido y resistente que nunca! ¡La última versión de Shadowind es única en su clase!",
  ui_story_5070_50700101_126_dialog_content = "T-Tanta gente.",
  ui_story_5070_50700101_127_dialog_content = "Siempre que un barco llega al puerto, la gente de esta ciudad sale a darles la bienvenida. Es algo así como una pequeña ceremonia para ellos.",
  ui_story_5070_50700101_128_dialog_content = "Jaja... Pero con lo emocionada que está esta multitud, apenas podemos ver el barco en sí.",
  ui_story_5070_50700101_129_dialog_content = "PlayerName! ¡Gracias a Dios que te encontré!",
  ui_story_5070_50700101_130_dialog_content = "¿Eh? Es del Gremio Lin...",
  ui_story_5070_50700101_131_dialog_content = "Sí, y como puedes ver, ¡el Shadowind finalmente ha llegado a salvo a nuestro puerto!",
  ui_story_5070_50700101_132_dialog_content = "El capitán también quiere hablar contigo. Por aquí, por favor.",
  ui_story_5070_50700101_133_dialog_content = "¿El capitán? Pero no hicimos nada en absoluto...",
  ui_story_5070_50700101_134_dialog_content = "Eso apenas es cierto.",
  ui_story_5070_50700101_135_dialog_content = "Permíteme presentarme. Soy Mu Yuebai, el capitán de Shadowind.",
  ui_story_5070_50700101_136_dialog_content = "Tal vez no fue nada para el legendario Caelestite, pero ayudaste a Shadowind más de lo que crees.",
  ui_story_5070_50700101_137_dialog_content = "La verdad es que nuestro barco tuvo un problema grave hace medio año y perdimos contacto con la familia Lin.",
  ui_story_5070_50700101_138_dialog_content = "Nuestra esfera armilar, una herramienta utilizada por la familia Lin para navegar por el mar según las posiciones de las estrellas, también se perdió en las secuelas.",
  ui_story_5070_50700101_139_dialog_content = "Como resultado, tuvimos que confiar únicamente en la experiencia y las cartas náuticas para trazar un nuevo rumbo, medio a ciegas, a través del océano.",
  ui_story_5070_50700101_140_dialog_content = "En el camino, fuimos acosados por tormentas salvajes y viciosos Eclipsites, y ese remolino que encontramos antes era igual de peligroso.",
  ui_story_5070_50700101_141_dialog_content = "Si no fuera por tu orientación, PlayerName...",
  ui_story_5070_50700101_142_dialog_content = "Incluso si hubiéramos escapado del remolino, nos habríamos perdido en el mar durante días antes de encontrar nuestro camino aquí.",
  ui_story_5070_50700101_143_dialog_content = "Así que incluso si crees que no hiciste nada por nosotros, debo expresar adecuadamente mi gratitud por tu guía y protección.",
  ui_story_5070_50700101_144_dialog_content = "Según la tradición del gremio, aquellos que ayuden a la Familia Lin de manera significativa deben ser recompensados el doble al ser aceptados en el gremio como invitados de honor.",
  ui_story_5070_50700101_145_dialog_content = "Si la sucursal de Twin Pavilions Bay no puede compensarte, entonces, con mi autoridad como capitán, te pagaré yo mismo.",
  ui_story_5070_50700101_146_dialog_content = "A-Ejem! No te adelantes ahora, Capitán Yuebai.",
  ui_story_5070_50700101_147_dialog_content = "Ya hemos llegado a un acuerdo al estilo de Astra. Además, nuestro estimado amigo no se alinea completamente con ninguna entidad en particular...",
  ui_story_5070_50700101_148_dialog_content = "Necesito tu respuesta, PlayerName. ¿Te unirás a las fuerzas de la familia Lin?",
  ui_story_5070_50700101_149_dialog_content = "(¿Eh? ¿Me lo estoy imaginando o el capitán está intentando que me una a ellos oficialmente?!)",
  ui_story_5070_50700101_150_dialog_content = "C-Capitán! Aunque es cierto que vine aquí buscando una gran recompensa...",
  ui_story_5070_50700101_151_dialog_content = "Solo ayudé en la menor medida, esa es la verdad. Y simplemente estaba cumpliendo con mi deber según el acuerdo.",
  ui_story_5070_50700101_152_dialog_content = "Hablando de devolver favores, la familia Lin también ha sido amable conmigo. Es mutuo.",
  ui_story_5070_50700101_153_dialog_content = "Por eso no puedo aceptar ese tipo de recompensa ni unirme a la familia Lin.",
  ui_story_5070_50700101_154_dialog_content = "...",
  ui_story_5070_50700101_155_dialog_content = "Jeje, hace mucho tiempo que conozco la forma contundente en que la Capitana Yuebai trata a los demás. Su benevolencia solo es igualada por su imponente fuerza...",
  ui_story_5070_50700101_156_dialog_content = "Imagina que te rechazan, qué divertido sería.",
  ui_story_5070_50700101_157_dialog_content = "Permítame intervenir en nombre de este joven...",
  ui_story_5070_50700101_158_dialog_content = "para que pueda hablar contigo en términos más locales, ¿eso sería aceptable?",
  ui_story_5070_50700101_159_dialog_content = "¡Claro! No busco una alianza ni un trato especial. ¡Ser amigos de la familia Lin es suficiente para mí!",
  ui_story_5070_50700101_160_dialog_content = "¡No me importaría dar un paseo en el Shadowind algún día! También eres bienvenido a bordo de mi Colossus, ¡Capitán Yuebai!",
  ui_story_5070_50700101_161_dialog_content = "... El Shadowind está demasiado dañado como para entretener adecuadamente a los invitados en este momento.",
  ui_story_5070_50700101_162_dialog_content = "Ya que Lady Dantang ha dejado claros sus deseos, naturalmente los cumpliré.",
  ui_story_5070_50700101_163_dialog_content = "Perdóname si estuve fuera de lugar hace un momento.",
  ui_story_5070_50700101_164_dialog_content = "¡No te preocupes! También puedes llamarme por mi nombre.",
  ui_story_5070_50700101_165_dialog_content = "El Shadowind estará atracado aquí durante las próximas dos semanas aproximadamente. Con todas las reparaciones que requiere, es posible que necesitemos tus servicios de nuevo pronto.",
  ui_story_5070_50700101_166_dialog_content = "Por supuesto, serás compensado generosamente.",
  ui_story_5070_50700101_167_dialog_content = "¡Me parece bien! Algunos de mis amigos todavía me están esperando, ¡pero espero verte de nuevo!",
  ui_story_5070_50700101_168_dialog_content = "Un momento, Capitán. No me informaron que el Shadowind se quedaría en el puerto tanto tiempo.",
  ui_story_5070_50700101_169_dialog_content = "¿Hay alguna otra solicitud que—",
  ui_story_5070_50700101_170_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5070_50700101_171_dialog_content = "<color=#e8d9bb>Un sonido de división resuena desde el barco en lo alto, mientras un gran trozo de madera se desprende repentinamente y cae al mar.</color>",
  ui_story_5070_50700101_172_dialog_content = "¿Eso responde a tu pregunta?",
  ui_story_5070_50700101_173_dialog_content = "E-Entendido... El Shadowind ciertamente necesita reparaciones urgentes. Contactaré a Li y Sun de inmediato.",
  ui_story_5070_50700101_174_dialog_content = "Descuida, son expertos. Supervisan las reparaciones realizadas en cada barco que atraca en Twin Pavilions Bay.",
  ui_story_5070_50700101_175_dialog_content = "Me temo que no será un trabajo fácil para ellos.",
  ui_story_5070_50700101_176_dialog_content = "¿Por qué no ha vuelto PlayerName todavía? ¡No me digas que lo han detenido?!",
  ui_story_5070_50700101_177_dialog_content = "Ugh, no puedo quedarme aquí esperando. ¡Tengo que ir a buscarlo!",
  ui_story_5070_50700101_178_dialog_content = "¿Así que esto es Twin Pavilions Bay?",
  ui_story_5070_50700101_179_dialog_content = "El estilo arquitectónico ciertamente recuerda a Longzhou, pero algunos detalles han sido exotizados en cierta medida. Interesante, por decir lo menos.",
  ui_story_5070_50700101_180_dialog_content = "Vamos a hacer un recorrido por el pueblo, Jiu.",
  ui_story_5070_50700101_181_dialog_content = "Resulta que conozco a cierta persona de Ye que ha estado aquí desde hace un tiempo...",
  ui_story_5070_50700101_182_dialog_content = "Estoy seguro de que ella puede mostrarnos muchos lugares interesantes aquí.",
  ui_story_5070_50700101_183_dialog_content = "El viaje fue largo y agotador, Su Alteza. ¿No deberíamos encontrar un lugar para que descanse primero?",
  ui_story_5070_50700101_184_dialog_content = "Vaya, vaya, parece que no entiende el punto, señorita Jiu.",
  ui_story_5070_50700101_185_dialog_content = "La mejor parte de cualquier viaje es disfrutar de las vistas y recorrer las calles a tu gusto.",
  ui_story_5070_50700101_186_dialog_content = "Permítanme acompañarlos a los dos. Tal vez pueda encontrar un terreno aún más auspicioso para que la princesa Dantang pise.",
  ui_story_5070_50700101_187_dialog_content = "Hmph. Estoy cansado.",
  ui_story_5070_50700101_188_dialog_content = "Jiu tiene razón, deberíamos regresar a Yuebai y descansar por el día.",
  ui_story_5070_50700101_189_dialog_content = "Oye... ¡Espérame, Su Alteza!",
  ui_story_5070_50700101_190_dialog_content = "Puedo tener muchos tipos de personas conmigo. Amigos, guerreros e incluso enemigos...",
  ui_story_5070_50700101_191_dialog_content = "Pero los estafadores no tienen lugar a mi lado.",
  ui_story_5070_50700101_192_dialog_content = "No seas tan cruel, Su Alteza. Y después de todo lo que hemos pasado juntos también...",
  ui_story_5070_50700101_193_dialog_content = "(Ella es realmente hermosa... Espera, ¿ese chico la llamó \"Alteza\"?!)",
  ui_story_5070_50700101_194_dialog_content = "¿Vice? ¡Vice! ¿Qué estás mirando?",
  ui_story_5070_50700101_195_dialog_content = "¡Aaah! ¡Finalmente has vuelto!",
  ui_story_5070_50700101_196_dialog_content = "Solo estaba pensando que además de traer muchos productos...",
  ui_story_5070_50700101_197_dialog_content = "El Shadowind también trajo a muchas personas interesantes. ¡Algunos de ellos incluso podrían convertirse en nuestros amigos!",
  ui_story_5070_50700101_198_dialog_content = "Ay, esto no funcionará. Si tan solo siguiera siendo el viejo Shadowind.",
  ui_story_5070_50700101_199_dialog_content = "Apenas puedo reconocer alguna de las técnicas utilizadas en este nuevo modelo, ya sea el horno, los disipadores de calor o la impermeabilización.",
  ui_story_5070_50700101_200_dialog_content = "Y ni siquiera comencemos con todos estos componentes Ye que metieron en la mezcla.",
  ui_story_5070_50700101_201_dialog_content = "¿Ves?",
  ui_story_5070_50700101_202_dialog_content = "...",
  ui_story_5070_50700101_203_dialog_content = "Perdón... ¿Cuál parece ser el problema, todos?",
  ui_story_5070_50700101_204_dialog_content = "¡Princesa Dantang!",
  ui_story_5070_50700101_205_dialog_content = "Preferiría no molestarla con los detalles, Su Alteza. Después de todo, tiene su misión que llevar a cabo.",
  ui_story_5070_50700101_206_dialog_content = "¿Todavía estás molesto conmigo por opacarte antes, Yuebai?",
  ui_story_5070_50700101_207_dialog_content = "Estás muy familiarizado con los tratos y disputas entre los ocho reinos vasallos de Longzhou.",
  ui_story_5070_50700101_208_dialog_content = "Aunque estoy aquí como representante de Ji, para ellos, siempre seré un rehén de Ye.",
  ui_story_5070_50700101_209_dialog_content = "Ganar la plena confianza del reino de Ji es extremadamente difícil, dada mi identidad.",
  ui_story_5070_50700101_210_dialog_content = "Precisamente por eso me ofrecí voluntariamente para navegar por el mar y venir a Astra.",
  ui_story_5070_50700101_211_dialog_content = "Solo puedo esperar que mis acciones demuestren mi sinceridad.",
  ui_story_5070_50700101_212_dialog_content = "Todo lo que hago, lo hago por la paz y prosperidad mutua de los dos reinos.",
  ui_story_5070_50700101_213_dialog_content = "Y como el Shadowind está inextricablemente vinculado al comercio, ¿no debería preocuparme también por su bienestar?",
  ui_story_5070_50700101_214_dialog_content = "Si es así, entonces naturalmente debo hacer todo lo que pueda por su bien.",
  ui_story_5070_50700101_215_dialog_content = "... Son las reparaciones del Shadowind.",
  ui_story_5070_50700101_216_dialog_content = "Este nuevo barco está equipado con la tecnología más avanzada, desarrollada cuidadosamente por los mejores técnicos de Ye. No tiene nada que ver con su predecesor.",
  ui_story_5070_50700101_217_dialog_content = "Sin artesanos capaces de dominar esta nueva tecnología, me temo que reparar el Shadowind será un proyecto largo y difícil.",
  ui_story_5070_50700101_218_dialog_content = "Twin Pavilions Bay tiene muchos materiales en bruto y constructores de barcos para trabajar con ellos, pero ninguno de ellos está preparado para manejar el Shadowind...",
  ui_story_5070_50700101_219_dialog_content = "¡Uf!",
  ui_story_5070_50700101_220_dialog_content = "¿Princesa Dantang?",
  ui_story_5070_50700101_221_dialog_content = "Si hubiera sido cualquier otra cosa, realmente no habría podido ayudar en absoluto.",
  ui_story_5070_50700101_222_dialog_content = "Pero si necesitas un talentoso artesano Ye, creo que conozco a la persona adecuada para el trabajo.",
  ui_story_5070_50700101_223_dialog_content = "¿Cuánto tiempo planeabas dedicar a las reparaciones del Shadowind, Yuebai?",
  ui_story_5070_50700101_224_dialog_content = "Medio mes.",
  ui_story_5070_50700101_225_dialog_content = "Entonces debería haber suficiente tiempo.",
  ui_story_5070_50700101_226_dialog_content = "Quédense tranquilos. El mejor artesano de Ye se encuentra justo aquí en Twin Pavilions Bay.",
  ui_story_5070_50700101_227_dialog_content = "Usando este pájaro transmisor que ella inventó, ¡debería poder encontrarla pronto!",
  ui_story_5070_50700101_228_dialog_content = "Ahora que el Shadowind está atracado de manera segura en el puerto, nuestro trabajo aquí debería estar terminado... Suspiro...",
  ui_story_5070_50700101_229_dialog_content = "¿Algo te preocupa?",
  ui_story_5070_50700101_230_dialog_content = "Sé lo que es. PlayerName hizo un gran y justo escándalo al rechazar la oferta del Capitán Yuebai...",
  ui_story_5070_50700101_231_dialog_content = "Apostaría a que se está lamentando por haber rechazado un trato tan bueno.",
  ui_story_5070_50700101_232_dialog_content = "Si sabías que te molestaría tanto, deberías haber aceptado en ese momento.",
  ui_story_5070_50700101_233_dialog_content = "De ninguna manera...",
  ui_story_5070_50700101_234_dialog_content = "Aunque las reparaciones de Soroz y nuestros gastos diarios han apretado las cosas últimamente...",
  ui_story_5070_50700101_235_dialog_content = "Aunque no tengo idea de dónde encontraré otro trabajo...",
  ui_story_5070_50700101_236_dialog_content = "No aceptaré pago por algo que no hice.",
  ui_story_5070_50700101_237_dialog_content = "Además, todavía soy bastante joven. No quiero pasar los mejores años de mi vida trabajando como empleado para la Guilda Lin o algo así...",
  ui_story_5070_50700101_238_dialog_content = "No creo que unirse al gremio Lin signifique necesariamente que debas convertirte en un empleado.",
  ui_story_5070_50700101_239_dialog_content = "Creo que podrías estar perdiendo el punto aquí, Carleen.",
  ui_story_5070_50700101_240_dialog_content = "¡Mis queridos compañeros de Twin Pavilions Bay!",
  ui_story_5070_50700101_241_dialog_content = "¡Vaya, eso está muy fuerte! ¿De dónde viene eso?",
  ui_story_5070_50700101_242_dialog_content = "¿Instalaron uno de los sistemas de altavoces militares de Illumina en los techos o algo así?",
  ui_story_5070_50700101_243_dialog_content = "Después de un largo y arduo viaje desde Longzhou, el Shadowind estará en el puerto durante aproximadamente dos semanas.",
  ui_story_5070_50700101_244_dialog_content = "¡y se realizarán los trabajos de reparación muy necesarios!",
  ui_story_5070_50700101_245_dialog_content = "¡Con este fin, estamos reclutando a todos los porteadores y artesanos capaces en la zona!",
  ui_story_5070_50700101_246_dialog_content = "¡Todos están invitados a inscribirse! Aquellos que presten sus conocimientos y trabajo a nuestros esfuerzos de reparación",
  ui_story_5070_50700101_247_dialog_content = "¡disfrutarán de los beneficios que Shadowind trae del otro lado del mar!",
  ui_story_5070_50700101_248_dialog_content = "(Jadeando) B-Jefe... ¡Apresúrate y reúne a los trabajadores!",
  ui_story_5070_50700101_249_dialog_content = "Tengo que contratar más personal temporal de inmediato. Voy a trabajar en un anuncio enseguida.",
  ui_story_5070_50700101_250_dialog_content = "¡No creo que necesites hacerlo! Estoy bastante seguro de que todo el pueblo escuchó la noticia.",
  ui_story_5070_50700101_251_dialog_content = "Pero, ¿cómo? No sabía que Twin Pavilions Bay tenía un sistema así en funcionamiento...",
  ui_story_5070_50700101_252_dialog_content = "¿Podría esto tener algo que ver con lo que dijo el Capitán Yuebai antes...?",
  ui_story_5070_50700101_253_dialog_content = "¡Qué momento perfecto! ¡Vamos a ver si hay buenos trabajos disponibles!",
  ui_story_5070_50700101_254_dialog_content = "¡Podríamos ser capaces de ganar una buena cantidad de dinero mientras estemos aquí!",
  ui_story_5070_50700201_1_dialog_content = "Y así pasamos dos semanas muy productivas en Twin Pavilions Bay.",
  ui_story_5070_50700201_2_dialog_content = "Además de hacer todo tipo de trabajos extraños para Shadowind, también hice muchas otras cosas...",
  ui_story_5070_50700201_3_dialog_content = "Por ejemplo, hubo un día en que Carleen y yo estábamos observando las reparaciones que se hacían en el Shadowind.",
  ui_story_5070_50700201_4_dialog_content = "Un extraño adivino sosteniendo un montón de palos raros apareció y nos engañó para que sacáramos un montón de palos de la fortuna extraños.",
  ui_story_5070_50700201_5_dialog_content = "También ayudé a Vice a preparar un baile especial que se supone que trae bendiciones y aleja desastres en el mar.",
  ui_story_5070_50700201_6_dialog_content = "Ese también fue el día en que conocimos formalmente a la princesa Dantang, quien previamente me había salvado de esa situación incómoda.",
  ui_story_5070_50700201_7_dialog_content = "Al principio, me preocupaba que una noble de un país extranjero fuera difícil de tratar, pero resultó ser muy accesible e inteligente.",
  ui_story_5070_50700201_8_dialog_content = "Después, ella y su sirviente vestido de negro nos enseñaron todo sobre la cultura única de Longzhou.",
  ui_story_5070_50700201_9_dialog_content = "Desafortunadamente, Carleen y Vice tuvieron que regresar a Lumopolis e Illumina después de recibir nuevas órdenes.",
  ui_story_5070_50700201_10_dialog_content = "¡Pero eso no me impedirá ganar aún más dinero para nosotros! ¡Después de todo, esta es una oportunidad única!",
  ui_story_5070_50700201_11_dialog_content = "... PlayerName?",
  ui_story_5070_50700201_12_dialog_content = "¿Eh? ¡Oh! Lo siento, Princesa Dantang, me quedé en blanco por un minuto allí.",
  ui_story_5070_50700201_13_dialog_content = "Está bien, estaba a punto de llegar a la parte importante.",
  ui_story_5070_50700201_14_dialog_content = "Además, ¿no te dije que simplemente me llames Dantang?",
  ui_story_5070_50700201_15_dialog_content = "Sí, lo siento Prin—quiero decir Dantang.",
  ui_story_5070_50700201_16_dialog_content = "(Suspiros) No vine aquí para escuchar disculpas, ¿sabes?",
  ui_story_5070_50700201_17_dialog_content = "Prometí a Yuebai que encontraría al artesano perfecto para arreglar su barco, ¿no es cierto?",
  ui_story_5070_50700201_18_dialog_content = "Bajo su supervisión, las reparaciones del Shadowind han ido muy bien y el barco ya está en su última fase de mantenimiento.",
  ui_story_5070_50700201_19_dialog_content = "Por esa razón, hemos comenzado los preparativos para una fiesta celebratoria en conmemoración de la finalización de las reparaciones del Shadowind.",
  ui_story_5070_50700201_20_dialog_content = "En cuanto a mi propia misión, mis esfuerzos también han resultado fructíferos.",
  ui_story_5070_50700201_21_dialog_content = "El enviado de Lumopolis finalmente regresó con una respuesta gracias a la dama Carleen.",
  ui_story_5070_50700201_22_dialog_content = "Han aceptado recibirnos como visitantes de Longzhou y discutir tanto las negociaciones comerciales como las contramedidas contra los Eclipsites.",
  ui_story_5070_50700201_23_dialog_content = "El enviado también asistirá a la fiesta y viajará a Longzhou a bordo del Shadowind para visitar a Ji.",
  ui_story_5070_50700201_24_dialog_content = "Suena como una misión exitosa para mí, Dantang! ¡Felicidades!",
  ui_story_5070_50700201_25_dialog_content = "Jejeje, gracias, PlayerName.",
  ui_story_5070_50700201_26_dialog_content = "Ahora bien, la razón por la que he venido aquí hoy es para invitarte también al banquete.",
  ui_story_5070_50700201_27_dialog_content = "¿Quieres decir que yo también puedo ir? ¡Sería un honor!",
  ui_story_5070_50700201_28_dialog_content = "Y nos sentiríamos honrados de tenerte allí.",
  ui_story_5070_50700201_29_dialog_content = "Es una lástima que la señorita Vice y Lady Carleen no vengan. Realmente quería expresar mi gratitud por su ayuda personalmente.",
  ui_story_5070_50700201_30_dialog_content = "Me aseguraré de tratarte especialmente bien en su ausencia.",
  ui_story_5070_50700201_31_dialog_content = "Eso me parece bien. Mientras tanto, terminaré el resto de mi trabajo. ¡Nos vemos en el banquete!",
  ui_story_5070_50700201_32_dialog_content = "Vamos a ver...",
  ui_story_5070_50700201_33_dialog_content = "Entregar una factura a la tienda en la parte este de la ciudad, hecho. Recoger y devolver las herramientas de los trabajadores, hecho.",
  ui_story_5070_50700201_34_dialog_content = "Entregar un envío de mercancías a este almacén al final de la calle Chunxi, revisar... pero no realmente.",
  ui_story_5070_50700201_35_dialog_content = "*Suspira*",
  ui_story_5070_50700201_36_dialog_content = "Me levanté temprano para entregar este envío, pero aún nadie ha venido a recogerlo.",
  ui_story_5070_50700201_37_dialog_content = "Incluso tuve tiempo de hacer otras cosas mientras tanto. ¿Me pregunto por qué no hay nadie aquí?",
  ui_story_5070_50700201_38_dialog_content = "Hoy es el día del banquete de Shadowind. Voy a llegar tarde si el cliente no aparece.",
  ui_story_5070_50700201_39_dialog_content = "¿Qué pasa con estas cajas de forma extraña de todos modos?",
  ui_story_5070_50700201_40_dialog_content = "¿Realmente necesitan estas cosas para arreglar un barco?",
  ui_story_5070_50700201_41_dialog_content = "... ¿Ah?",
  ui_story_5070_50700201_42_dialog_content = "¿Por qué siento que algo está mal con estas cajas?",
  ui_story_5070_50700201_43_dialog_content = "<color=#e8d9bb>Crujido—Crujido—</color>",
  ui_story_5070_50700201_44_dialog_content = "¡¿Qué fue eso?!",
  ui_story_5070_50700201_45_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5070_50700201_46_dialog_content = "¿Es eso algún tipo de... monstruo cangrejo? ¡E-Espera, quédate atrás!",
  ui_story_5070_50700201_47_dialog_content = "Esas pinzas se ven desagradables, pero menos mal que fui lo suficientemente rápido para evitarlas...",
  ui_story_5070_50700201_48_dialog_content = "Silbido-!",
  ui_story_5070_50700201_49_dialog_content = "¡Guau—! ¿Puede escupir fuego?!",
  ui_story_5070_50700201_50_dialog_content = "<color=#e8d9bb>Un chorro de fuego abrasador brota de la boca del monstruo.</color>",
  ui_story_5070_50700201_51_dialog_content = "<color=#e8d9bb>De repente, aparece una gran sombrilla.</color>",
  ui_story_5070_50700201_52_dialog_content = "<color=#e8d9bb>Brillando intensamente mientras gira rápidamente, el parasol metálico dispersa rápidamente las llamas entrantes.</color>",
  ui_story_5070_50700201_53_dialog_content = "El clima seco hace que las cosas se prendan fuego fácilmente, ¡así que ten cuidado!",
  ui_story_5070_50700201_54_dialog_content = "<color=#e8d9bb>Las llamas de los monstruos parecen no tener fin, pero el paraguas las mantiene a raya. Solo un tenue calor del fuego logra atravesar.</color>",
  ui_story_5070_50700201_55_dialog_content = "Esa voz suena familiar... ¡Hey, ya recuerdo! Usaste esa libélula para ayudarme a atrapar mi carta antes!",
  ui_story_5070_50700201_56_dialog_content = "Pero, ¿qué pasa con esta sombrilla...?",
  ui_story_5070_50700201_57_dialog_content = "Oh, yo no tocaría eso ahora si fuera tú. ¡No me hago responsable de las lesiones que puedas sufrir!",
  ui_story_5070_50700201_58_dialog_content = "Además, todavía tengo que lidiar con estos sinvergüenzas.",
  ui_story_5070_50700202_1_dialog_content = "¡A-Asombroso!",
  ui_story_5070_50700202_2_dialog_content = "(Parece un paraguas normal, ¡pero es más afilado que incluso la espada más legendaria!)",
  ui_story_5070_50700202_3_dialog_content = "(Cuando está abierto, ninguna cantidad de agua o fuego puede pasar.)",
  ui_story_5070_50700202_4_dialog_content = "(Cuando está cerrada, se convierte en una hoja imparable.)",
  ui_story_5070_50700202_5_dialog_content = "(¡Mis ojos ni siquiera pueden seguir sus movimientos!)",
  ui_story_5070_50700202_6_dialog_content = "(Con un movimiento de muñeca y un giro de su paraguas, convirtió a esos monstruos en un montón de chatarra.)",
  ui_story_5070_50700202_7_dialog_content = "Hiss-",
  ui_story_5070_50700202_8_dialog_content = "(Espera, ¿están hechas de metal? ¿Eso significa que alguien construyó estas cosas?)",
  ui_story_5070_50700202_9_dialog_content = "¿Por qué en el mundo alguien querría hacer cangrejos gigantes y mecánicos tan aterradores como este...?",
  ui_story_5070_50700202_10_dialog_content = "Estos cangrejos de fuego son solo una de las muchas Bestias Mecánicas que se utilizan regularmente en los talleres del reino de Ye.",
  ui_story_5070_50700202_11_dialog_content = "Están diseñados para ayudar con la soldadura y construcción de uniones, nada más.",
  ui_story_5070_50700202_12_dialog_content = "Sus pinzas y su habilidad para liberar pequeñas llamas controladas los convierten en una adición útil para cualquier taller.",
  ui_story_5070_50700202_13_dialog_content = "¿Soldadura? ¿Construcción de juntas? Espera, ¿eso significa que pensaron que yo era materia prima o algo así?",
  ui_story_5070_50700202_14_dialog_content = "Bueno... juzgando por tu fuerza y resistencia, claramente no cumples con el perfil.",
  ui_story_5070_50700202_15_dialog_content = "Lógicamente hablando, los cangrejos de fuego no deberían cometer un error tan simple...",
  ui_story_5070_50700202_16_dialog_content = "No sé cómo se supone que debo sentirme al respecto.",
  ui_story_5070_50700202_17_dialog_content = "Además, Ye tiene regulaciones muy estrictas con respecto a la difusión y uso de las Bestias Mecánicas.",
  ui_story_5070_50700202_18_dialog_content = "Para que no solo aparezcan en este lugar e incluso ataquen a la gente...",
  ui_story_5070_50700202_19_dialog_content = "Definitivamente significa que alguien está tramando algo malo.",
  ui_story_5070_50700202_20_dialog_content = "Entonces, ¿vas a salir por tu cuenta o tengo que dar el primer paso?",
  ui_story_5070_50700202_21_dialog_content = "(¿¡Hay alguien más aquí?!)",
  ui_story_5070_50700202_22_dialog_content = "<color=#e8d9bb>Una figura sombría salta repentinamente de las sombras y corre hacia la puerta.</color>",
  ui_story_5070_50700202_23_dialog_content = "¡Espera!",
  ui_story_5070_50700202_24_dialog_content = "(¡Esquivó el ataque... tengo que cortarle el paso de alguna manera!)",
  ui_story_5070_50700202_25_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700202_26_dialog_content = "Relájate, conozco las reglas. Después de todo, llevo años haciendo este tipo de cosas en Umbraton.",
  ui_story_5070_50700202_27_dialog_content = "Después de aceptar el pago de un cliente, es natural hacer las cosas según sus deseos.",
  ui_story_5070_50700202_28_dialog_content = "Además, solo me piden que aprenda a manejar estos, eh... ¿Cómo llaman a estos cangrejos gigantes de nuevo?",
  ui_story_5070_50700202_29_dialog_content = "\"Cangrejos Forjados en Horno\" o algo así, ¿verdad?",
  ui_story_5070_50700202_30_dialog_content = "Será un dolor, eso es seguro.",
  ui_story_5070_50700202_31_dialog_content = "Pero este dolor no es nada si significa que puedo hacer sufrir a la familia Lin y al Shadowind.",
  ui_story_5070_50700202_32_dialog_content = "(¿Está apuntando al Shadowind? Pero por qué...?)",
  ui_story_5070_50700202_33_dialog_content = "¡Fuera de mi camino!",
  ui_story_5070_50700202_34_dialog_content = "Ah—",
  ui_story_5070_50700202_35_dialog_content = "Cuidado.",
  ui_story_5070_50700202_36_dialog_content = "Gr-Gracias por atraparme. Me habría lastimado mucho si no lo hubieras hecho. ¿Quién era—",
  ui_story_5070_50700202_37_dialog_content = "No le hagas caso. No sirve de nada perseguir a una presa acorralada, a menos que quieras ser mordido.",
  ui_story_5070_50700202_38_dialog_content = "Ese tipo no es más que una marioneta insignificante.",
  ui_story_5070_50700202_39_dialog_content = "En cuanto al que mueve sus hilos, ya tengo mis sospechas.",
  ui_story_5070_50700202_40_dialog_content = "Tendré que confiar en la gente aquí en Twin Pavilions Bay para que me ayuden a encontrar esto–",
  ui_story_5070_50700202_41_dialog_content = "¡E-Espera, esa voz!",
  ui_story_5070_50700202_42_dialog_content = "¡No es de extrañar que suenes tan familiar! ¡Eres el que puso todos esos altavoces en las torres de la puerta de la ciudad!",
  ui_story_5070_50700202_43_dialog_content = "¿Quién eres exactamente?",
  ui_story_5070_50700202_44_dialog_content = "¿Eh? ¿No sabes quién soy?",
  ui_story_5070_50700202_45_dialog_content = "¿P-Perdón?",
  ui_story_5070_50700202_46_dialog_content = "Jaja, solo te estoy tomando el pelo. ¡No soy tan engreído como para culpar a alguien al otro lado del mar por no saber quién soy!",
  ui_story_5070_50700202_47_dialog_content = "Aun así, me sorprende que Dantang no me haya presentado, considerando cuánto me ha hablado de ti.",
  ui_story_5070_50700202_48_dialog_content = "¡Eso no es justo en absoluto!",
  ui_story_5070_50700202_49_dialog_content = "De todos modos, permítame presentarme.",
  ui_story_5070_50700202_50_dialog_content = "Mi nombre es Xuan Ji. Soy un artesano.",
  ui_story_5070_50700202_51_dialog_content = "Y al igual que la princesa Dantang, también provengo de la capital artesanal de Longzhou: el reino vasallo de Ye.",
  ui_story_5070_50700202_52_dialog_content = "He estado viviendo en Twin Pavilions Bay por un tiempo, pasando el tiempo y haciendo cosas como devolver objetos perdidos a sus legítimos dueños.",
  ui_story_5070_50700202_53_dialog_content = "Pero gracias a la sólida recomendación de la Princesa Dantang, ahora soy el jefe técnico temporal de Shadowind.",
  ui_story_5070_50700202_54_dialog_content = "No solo estoy a cargo de las reparaciones de Shadowind, sino también del mantenimiento de los Pájaros de Relojería transmisores de voz que presté al Lin Guild.",
  ui_story_5070_50700202_55_dialog_content = "¿Pájaros mecánicos? ¿Así que así lo hicieron...?",
  ui_story_5070_50700202_56_dialog_content = "¡Exacto! Básicamente, son altavoces voladores que nunca necesitan ser colgados.",
  ui_story_5070_50700202_57_dialog_content = "Pero eso no me impidió colocarles cuidadosamente picos y plumas a ellos!",
  ui_story_5070_50700202_58_dialog_content = "... Así que tú eres el gran artesano del que Dantang me habló.",
  ui_story_5070_50700202_59_dialog_content = "¡Seguro que haces honor a tu nombre!",
  ui_story_5070_50700202_60_dialog_content = "También debo mencionar algo.",
  ui_story_5070_50700202_61_dialog_content = "Esos cangrejos grandes y aterradores tirados por todo el suelo? También los diseñé yo.",
  ui_story_5070_50700202_62_dialog_content = "?",
  ui_story_5070_50700301_1_dialog_content = "Sin más preámbulos, ¡por favor den la bienvenida a la capitana Yuebai mientras pronuncia un discurso para el banquete de esta noche!",
  ui_story_5070_50700301_2_dialog_content = "Las reparaciones rápidas y eficientes de Shadowind fueron el resultado del arduo trabajo y perseverancia de todos.",
  ui_story_5070_50700301_3_dialog_content = "El banquete de esta noche es en honor a todos los presentes.",
  ui_story_5070_50700301_4_dialog_content = "La familia Lin siempre ha valorado el trabajo duro y honesto, y está más que feliz de recompensar tales esfuerzos.",
  ui_story_5070_50700301_5_dialog_content = "Así que por favor coman, beban y disfruten lo más posible esta noche.",
  ui_story_5070_50700301_6_dialog_content = "¡Guauuu!",
  ui_story_5070_50700301_7_dialog_content = "Nunca pensé que un banquete tan animado como este pudiera realizarse en un barco.",
  ui_story_5070_50700301_8_dialog_content = "Tu elogio es muy apreciado, Telema de Lumopolis.",
  ui_story_5070_50700301_9_dialog_content = "Me pregunto qué otras sorpresas me tiene preparadas Longzhou. Estoy emocionado por descubrirlo.",
  ui_story_5070_50700301_10_dialog_content = "Definitivamente.",
  ui_story_5070_50700301_11_dialog_content = "Longzhou es muy especial a la hora de recibir a invitados de lejos. Como enviado de Lumopolis, serás considerado un invitado raro y especial.",
  ui_story_5070_50700301_12_dialog_content = "Nada más que el mejor tratamiento será suficiente.",
  ui_story_5070_50700301_13_dialog_content = "Cuando lo dices así, ¡me emociona aún más visitar el otro lado del mar!",
  ui_story_5070_50700301_14_dialog_content = "Pero Longzhou aún está muy lejos, así que ¿podría primero aprender un poco más sobre las características de Shadowind?",
  ui_story_5070_50700301_15_dialog_content = "Desde que llegué a Twin Pavilions Bay, he escuchado tantos rumores interesantes sobre la tecnología de este barco.",
  ui_story_5070_50700301_16_dialog_content = "Con sus componentes meticulosamente elaborados y sus innumerables funciones, se supone que Shadowind no es menos que una obra de arte.",
  ui_story_5070_50700301_17_dialog_content = "En cualquier caso, parece mucho más agradable que cualquier tecnología voluminosa y difícil de manejar utilizada en Illumina o en el desierto.",
  ui_story_5070_50700301_18_dialog_content = "Cada lugar tiene sus propias tecnologías únicas. Naturalmente, sus ventajas y desventajas también son igual de variadas.",
  ui_story_5070_50700301_19_dialog_content = "Permíteme encontrar una guía adecuada para presentarte sus características.",
  ui_story_5070_50700301_20_dialog_content = "(Xuan Ji... ¿Dónde te has ido?)",
  ui_story_5070_50700301_21_dialog_content = "¡Ah, Sol! ¡Tu llegada no podría ser más perfecta!",
  ui_story_5070_50700301_22_dialog_content = "¿¡S-Su Alteza?! ¿C-Cómo puedo ser de ayuda?",
  ui_story_5070_50700301_23_dialog_content = "¿Serías tan amable de mostrar algunas de las características del Shadowind a nuestro amigo aquí? El enviado de Lumopolis tiene mucha curiosidad acerca de las diversas funciones del barco.",
  ui_story_5070_50700301_24_dialog_content = "¡Pero claro!",
  ui_story_5070_50700301_25_dialog_content = "He estado trasteando con estos artilugios durante las últimas décadas. ¡No encontrarás una mejor guía que yo!",
  ui_story_5070_50700301_26_dialog_content = "Entonces, dejo el resto en tus hábiles manos.",
  ui_story_5070_50700301_27_dialog_content = "Hasta que nos encontremos de nuevo, mi señora.",
  ui_story_5070_50700301_28_dialog_content = "Uf.",
  ui_story_5070_50700301_29_dialog_content = "¿Qué sucede, Su Alteza? ¿Necesita descansar?",
  ui_story_5070_50700301_30_dialog_content = "Para nada. Es demasiado temprano para que empiece a sentirme cansado.",
  ui_story_5070_50700301_31_dialog_content = "Pero... me pregunto dónde podría estar PlayerName?",
  ui_story_5070_50700301_32_dialog_content = "¿Podría ser que su trabajo haya retrasado su llegada?",
  ui_story_5070_50700301_33_dialog_content = "Siempre podría ir a buscarlo—",
  ui_story_5070_50700301_34_dialog_content = "¡Espera!",
  ui_story_5070_50700301_35_dialog_content = "¿Qué es, Jiu?",
  ui_story_5070_50700301_36_dialog_content = "Tenga cuidado con su entorno, Su Alteza.",
  ui_story_5070_50700301_37_dialog_content = "...",
  ui_story_5070_50700301_38_dialog_content = "Parece que tendré que recitar el código de conducta del Shadowind para nuestros pasajeros en otra ocasión.",
  ui_story_5070_50700301_39_dialog_content = "¿Qué es? ¡¿Qué está pasando?!",
  ui_story_5070_50700301_40_dialog_content = "Vaya, ¿qué podría ser ahora? Ya fue bastante difícil conseguir un asiento para el banquete de esta noche...",
  ui_story_5070_50700301_41_dialog_content = "Un comienzo poco auspicioso para la noche, debo decir.",
  ui_story_5070_50700301_42_dialog_content = "¡Manténganse alerta, todos!",
  ui_story_5070_50700301_43_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700301_44_dialog_content = "¡Ah! ¡El barco se mece de un lado a otro!",
  ui_story_5070_50700301_45_dialog_content = "¡Capitán! ¡Algunas de las Bestias Mecánicas han comenzado a atacar las estructuras de soporte del Shadowind!",
  ui_story_5070_50700301_46_dialog_content = "Estamos en medio de un banquete, ¿verdad? Noche Blanca en lo alto. ¿Qué diablos está pasando aquí?!",
  ui_story_5070_50700301_47_dialog_content = "¡Exijo saber qué está pasando con este barco ahora mismo!",
  ui_story_5070_50700301_48_dialog_content = "...",
  ui_story_5070_50700301_49_dialog_content = "Por favor, quédese aquí, Su Alteza. Yo me encargaré de las cosas.",
  ui_story_5070_50700301_50_dialog_content = "Muy bien, pero ten cuidado.",
  ui_story_5070_50700302_1_dialog_content = "El asunto ha sido resuelto, Su Alteza.",
  ui_story_5070_50700302_2_dialog_content = "Me alegra oírlo.",
  ui_story_5070_50700302_3_dialog_content = "Pero, ¿por qué te ves tan preocupado? No me digas que te lastimaste durante el caos...",
  ui_story_5070_50700302_4_dialog_content = "Estoy bien, Jiu.",
  ui_story_5070_50700302_5_dialog_content = "Debido a que las Bestias Mecánicas están fuera de control, el Lin Guild está debatiendo si retrasar o no la partida del Shadowind.",
  ui_story_5070_50700302_6_dialog_content = "Esta decisión no se toma por cobardía.",
  ui_story_5070_50700302_7_dialog_content = "Sin embargo, el mar está lleno de peligros, como tormentas y Eclipsites...",
  ui_story_5070_50700302_8_dialog_content = "Además de todo eso, nuestras Bestias Mecánicas han comenzado a atacarnos inexplicablemente.",
  ui_story_5070_50700302_9_dialog_content = "Es demasiado peligroso salir del puerto. Debemos ser pacientes y seguir observando cualquier cambio.",
  ui_story_5070_50700302_10_dialog_content = "Pero no tenemos tiempo para simplemente esperar y ver.",
  ui_story_5070_50700302_11_dialog_content = "Como muchos de ustedes saben, he viajado a Astra con el objetivo de cumplir dos metas.",
  ui_story_5070_50700302_12_dialog_content = "El primero es mejorar las relaciones con las facciones gobernantes de este continente y entrar formalmente en acuerdos comerciales.",
  ui_story_5070_50700302_13_dialog_content = "El segundo es intercambiar conocimientos técnicos y tácticos para enfrentar la amenaza de los Eclipsites.",
  ui_story_5070_50700302_14_dialog_content = "¿Todos saben por qué se les ha dado tanta prioridad a estos dos objetivos?",
  ui_story_5070_50700302_15_dialog_content = "Es porque las costas de Longzhou han sufrido frecuentes ataques de Eclipsites en los últimos años. Como resultado, nuestros barcos mercantes y sus viajes se han visto muy afectados.",
  ui_story_5070_50700302_16_dialog_content = "Ji, uno de los ocho reinos vasallos con los que estoy afiliado, se fundó en el comercio. Como tal, su prosperidad depende casi en su totalidad de vías fluviales seguras y un transporte sólido.",
  ui_story_5070_50700302_17_dialog_content = "Los numerosos gremios de Ji han solicitado desde hace tiempo que solucionemos este problema.",
  ui_story_5070_50700302_18_dialog_content = "Pero la corte real aún no ha encontrado una solución duradera. No importa cuántas veces los rechacemos, más oleadas de Eclipsites ocupan su lugar. Esto ha llevado a muchas de nuestras personas a abandonar las costas, dejando estas áreas susceptibles a la ocupación de piratas.",
  ui_story_5070_50700302_19_dialog_content = "Nuestros comerciantes y trabajadores de la industria naviera están bajo constante amenaza de ataque, y nuestra gente no puede llevar vidas tranquilas.",
  ui_story_5070_50700302_20_dialog_content = "Por esta razón, nuestro rey decidió nombrar y enviar a un noble emisario a Astra. Al hacerlo, espera encontrar un avance en nuestra lucha contra los Eclipsites.",
  ui_story_5070_50700302_21_dialog_content = "Convencer a Lumopolis de permitir que un enviado me acompañe de regreso a Longzhou para más conversaciones no fue tarea fácil...",
  ui_story_5070_50700302_22_dialog_content = "Pero ahora...",
  ui_story_5070_50700302_23_dialog_content = "Quiero bajarme de este barco en este mismo instante.",
  ui_story_5070_50700302_24_dialog_content = "¿No prometiste que era perfectamente seguro? ¡Ni siquiera hemos salido del puerto y ya hemos sido atacados!",
  ui_story_5070_50700302_25_dialog_content = "¿¡Esto es lo que ustedes llaman seguro?!",
  ui_story_5070_50700302_26_dialog_content = "Nadie me dijo que esos monstruos mecánicos fueran capaces de atacarnos.",
  ui_story_5070_50700302_27_dialog_content = "¡Nadie en absoluto!",
  ui_story_5070_50700302_28_dialog_content = "Yo... Yo...",
  ui_story_5070_50700302_29_dialog_content = "... Solo puedo disuadir al enviado por un tiempo.",
  ui_story_5070_50700302_30_dialog_content = "Si no podemos reparar el barco y enviarlo rápidamente en su camino, temo que las cosas empeorarán. Si es así, entonces mi misión...",
  ui_story_5070_50700302_31_dialog_content = "Bueno...",
  ui_story_5070_50700302_32_dialog_content = "La princesa tiene un buen argumento, pero no podemos permitirnos ser imprudentes, independientemente de las circunstancias.",
  ui_story_5070_50700302_33_dialog_content = "También estarías poniendo en riesgo tu propia vida.",
  ui_story_5070_50700302_34_dialog_content = "Creo que deberíamos esperar, Su Alteza.",
  ui_story_5070_50700302_35_dialog_content = "Si el enviado no quiere hacer el viaje, siempre puedo convencerlo de otras maneras.",
  ui_story_5070_50700302_36_dialog_content = "Has sacrificado mucho para llegar hasta aquí. Me niego a dejar que todo haya sido en vano.",
  ui_story_5070_50700302_37_dialog_content = "Ejem, ¿te gustaría compartir tus pensamientos, Capitán?",
  ui_story_5070_50700302_38_dialog_content = "...",
  ui_story_5070_50700302_39_dialog_content = "Este viaje es sin duda muy importante. El barco lleva más que solo la princesa y nuestra mercancía.",
  ui_story_5070_50700302_40_dialog_content = "También lleva el futuro de la familia Lin.",
  ui_story_5070_50700302_41_dialog_content = "Ya hemos sufrido demasiadas pérdidas en el mar... Me temo que no podremos resistir otro golpe fuerte.",
  ui_story_5070_50700302_42_dialog_content = "Lo cual es aún más razón para ser cauteloso—",
  ui_story_5070_50700302_43_dialog_content = "Entonces, comiencen a reparar el armazón del barco de inmediato.",
  ui_story_5070_50700302_44_dialog_content = "Zarpamos tan pronto como el Shadowind esté en condiciones de funcionamiento.",
  ui_story_5070_50700302_45_dialog_content = "A-¡Ejem!",
  ui_story_5070_50700302_46_dialog_content = "¡Capitán! C-Cómo pudiste también...",
  ui_story_5070_50700302_47_dialog_content = "¿Eh? Espera... ¡Capitán Yuebai!",
  ui_story_5070_50700302_48_dialog_content = "Honestamente, ¿por qué todos los jóvenes son así hoy en día?!",
  ui_story_5070_50700302_49_dialog_content = "¡Exactamente! Ya sabes lo que dicen. \"Prisa crea desperdicio; lento y seguro gana la carrera.\"",
  ui_story_5070_50700302_50_dialog_content = "Lamentablemente, la situación actual no parece darnos el lujo del tiempo. ¡Vaya predicamento en verdad!",
  ui_story_5070_50700302_51_dialog_content = "¿Eh? ¿Quién eres...?",
  ui_story_5070_50700302_52_dialog_content = "Interesante, no recuerdo haber invitado a un estafador a este banquete.",
  ui_story_5070_50700302_53_dialog_content = "Oh, Su Alteza.",
  ui_story_5070_50700302_54_dialog_content = "Dado todo lo que ha pasado aquí hoy, temo que muy pocas personas aún tienen apetito.",
  ui_story_5070_50700302_55_dialog_content = "Sería una lástima dejar que toda esta deliciosa comida se desperdicie, ¿no crees? Afortunadamente, resulta que tengo un apetito muy saludable esta noche.",
  ui_story_5070_50700302_56_dialog_content = "Todo sabe exquisito, aunque encuentro que el melón es un poco decepcionante.",
  ui_story_5070_50700302_57_dialog_content = "En su prisa por proveer para el banquete, parece que los agricultores cosecharon estos melones antes de que estuvieran perfectamente maduros y dulces.",
  ui_story_5070_50700302_58_dialog_content = "Ya he tenido suficiente de tus parloteos...",
  ui_story_5070_50700302_59_dialog_content = "Simplemente estaba haciendo una observación, nada más. Al final, depende de ti decidir si esperar o no el momento adecuado.",
  ui_story_5070_50700302_60_dialog_content = "Pero a veces, es mejor dejar que la naturaleza siga su curso. Dejar que el melón madure y caiga de la vid es mucho más agradable que obligar a todos a participar en una fruta amarga y desagradable.",
  ui_story_5070_50700302_61_dialog_content = "¿No estás de acuerdo?",
  ui_story_5070_50700401_1_dialog_content = "Hmm, dame un minuto para pensar en una forma de explicar esta tecnología para que puedas entender.",
  ui_story_5070_50700401_2_dialog_content = "... ¡Lo tengo! Entiendo que Astra ha realizado una amplia investigación sobre las Cuatro Fuerzas...",
  ui_story_5070_50700401_3_dialog_content = "¿Las Cuatro Fuerzas?",
  ui_story_5070_50700401_4_dialog_content = "Los cuatro elementos diferentes de Lumina.",
  ui_story_5070_50700401_5_dialog_content = "Mi campo de especialización tecnológica se centra en combinar diferentes materiales...",
  ui_story_5070_50700401_6_dialog_content = "Y creando máquinas capaces de aprovechar la Lumina, al igual que los aurorianos y las bestias espirituales.",
  ui_story_5070_50700401_7_dialog_content = "¿Eso te hace más sentido ahora?",
  ui_story_5070_50700401_8_dialog_content = "Suena mucho como la tecnología Lumina que tenemos aquí, pero el estilo es completamente diferente.",
  ui_story_5070_50700401_9_dialog_content = "Por supuesto. Nuestros objetivos son los mismos; la diferencia radica simplemente en nuestras visiones del mundo.",
  ui_story_5070_50700401_10_dialog_content = "La gente de Longzhou cree que todas las cosas en este mundo contienen Lumina.",
  ui_story_5070_50700401_11_dialog_content = "Se puede observar una vasta red circulatoria de Lumina desde la más pequeña hoja de hierba hasta el árbol más alto, y desde el insecto más diminuto hasta la bestia más salvaje.",
  ui_story_5070_50700401_12_dialog_content = "Nuestras técnicas nos permiten infundir Lumina en los materiales utilizados para fabricar componentes. Luego podemos producir cualquier cantidad de efectos regulando el flujo de esa Lumina.",
  ui_story_5070_50700401_13_dialog_content = "Con los materiales adecuados y estructuras precisas, ¡nuestra tecnología incluso puede crear un mundo completamente nuevo!",
  ui_story_5070_50700401_14_dialog_content = "¡Vaya, hablar de tu tecnología es como hablar de la filosofía de la creación!",
  ui_story_5070_50700401_15_dialog_content = "¡Jajaja, bueno, no te equivocas!",
  ui_story_5070_50700401_16_dialog_content = "Esos cangrejos de fuego de antes, así como mis libélulas de cobre, son todas manifestaciones de esa misma filosofía.",
  ui_story_5070_50700401_17_dialog_content = "Mi sombrilla peculiar tampoco es una excepción.",
  ui_story_5070_50700401_18_dialog_content = "Tiene innumerables mecanismos, por lo que es capaz de atacar y defender.",
  ui_story_5070_50700401_19_dialog_content = "Cuando se comprenden adecuadamente, los principios de nuestra tecnología pueden aplicarse a mucho más que simples bestias de engranajes.",
  ui_story_5070_50700401_20_dialog_content = "No tenía idea de que fuera tan impresionante... Supongo que el estudio de la maquinaria no es tan simple como pensaba.",
  ui_story_5070_50700401_21_dialog_content = "Por supuesto que no. Después de todo, esta tecnología es la base de todo un reino vasallo, así como la razón por la que la Familia Lin pudo restablecer sus rutas comerciales.",
  ui_story_5070_50700401_22_dialog_content = "En el Reino Ye, los cielos están llenos de pájaros mecánicos que llevan mensajes, mientras que los bueyes de madera transportan nuestras mercancías en el suelo.",
  ui_story_5070_50700401_23_dialog_content = "Si alguna vez tienes demasiada pereza para ponerte ropa, lavarte la cara o preparar comida, hay una criatura mecánica para ayudarte a terminar cualquier tarea.",
  ui_story_5070_50700401_24_dialog_content = "Si alguna vez encuentras tiempo para visitar, estaré encantado de mostrarte el verdadero alcance de nuestra tecnología.",
  ui_story_5070_50700401_25_dialog_content = "¡Suena bien para mí!",
  ui_story_5070_50700401_26_dialog_content = "Pero...",
  ui_story_5070_50700401_27_dialog_content = "¿Qué estamos haciendo exactamente ahora?",
  ui_story_5070_50700401_28_dialog_content = "¿No es obvio? Estamos buscando un almacén que se haya utilizado recientemente.",
  ui_story_5070_50700401_29_dialog_content = "Estoy bien consciente de eso, ya que ya hemos revisado varios almacenes.",
  ui_story_5070_50700401_30_dialog_content = "(Algunos de ellos también estaban cerrados con llave, pero no fui lo suficientemente rápido para evitar que Xuan Ji abriera sus cerraduras...)",
  ui_story_5070_50700401_31_dialog_content = "Pero, ¿no deberíamos estar persiguiendo al enemigo ahora mismo?",
  ui_story_5070_50700401_32_dialog_content = "Soy un artesano, ¿recuerdas? Trabajar con maquinaria es mi especialidad, así que deja la búsqueda a los pequeños informantes que he dispersado por toda la ciudad.",
  ui_story_5070_50700401_33_dialog_content = "Un grupo de matones escondidos en las sombras logró obtener mis planos de una fuente desconocida...",
  ui_story_5070_50700401_34_dialog_content = "Convirtieron a mis cangrejos de fuego en herramientas para lastimar a la gente y almacenaron un montón de ellos en el almacén del Shadowind.",
  ui_story_5070_50700401_35_dialog_content = "Esa emboscada fallida de hace un momento claramente no era su verdadero objetivo.",
  ui_story_5070_50700401_36_dialog_content = "Estoy seguro de que tienen aún más trampas escondidas alrededor de Twin Pavilions Bay.",
  ui_story_5070_50700401_37_dialog_content = "... Realmente estoy preocupado por la seguridad de Shadowind.",
  ui_story_5070_50700401_38_dialog_content = "La gente normal no tiene ninguna oportunidad contra esos cangrejos de fuego.",
  ui_story_5070_50700401_39_dialog_content = "Los fuertes no deben oprimir a los débiles, los muchos no deben oprimir a los pocos y los ricos no deben oprimir a los pobres...",
  ui_story_5070_50700401_40_dialog_content = "Con la maquinaria viene un gran poder, y quienes lo manejan nunca deben usarlo para lastimar a otros.",
  ui_story_5070_50700401_41_dialog_content = "Los artesanos de mi tierra se unieron para crear este código de conducta, y todos juramos respetarlo.",
  ui_story_5070_50700401_42_dialog_content = "Por esa razón, si alguna vez logro encontrar al ladrón que robó mis planos...",
  ui_story_5070_50700401_43_dialog_content = "(Su voz de repente se volvió fría como el hielo...)",
  ui_story_5070_50700401_44_dialog_content = "¡Así es!",
  ui_story_5070_50700401_45_dialog_content = "La forma en que lo dices, estas bestias mecánicas pueden simular el flujo de Lumina en organismos vivos...",
  ui_story_5070_50700401_46_dialog_content = "¡Esto significa que podría ser capaz de usar mis poderes para detectar la ubicación de más cangrejos de fuego!",
  ui_story_5070_50700401_47_dialog_content = "¡Qué conclusión tan interesante!",
  ui_story_5070_50700401_48_dialog_content = "Aquí va—",
  ui_story_5070_50700401_49_dialog_content = "(Solo tengo que imaginar a los cangrejos de fuego de antes y el mismo tipo de Lumina que emitían... ¡Ahí está!)",
  ui_story_5070_50700401_50_dialog_content = "Es débil, pero al menos puedo sentir su dirección. ¡Está por aquí!",
  ui_story_5070_50700401_51_dialog_content = "Nunca hubiera esperado encontrar este pequeño almacén en un lugar tan apartado.",
  ui_story_5070_50700401_52_dialog_content = "¡Eso fue bastante impresionante! Gracias por tu ayuda, PlayerName.",
  ui_story_5070_50700401_53_dialog_content = "<color=#e8d9bb>Dentro de los almacenes en ruinas hay todo tipo de cajas extrañas, cada una conteniendo—</color>",
  ui_story_5070_50700401_54_dialog_content = "Cangrejos de fuego, halcones flotantes, incluso escorpiones largos... Y todos están hechos con materiales de la más alta calidad.",
  ui_story_5070_50700401_55_dialog_content = "El dueño de estos almacenes debe tener bastante dinero para gastar.",
  ui_story_5070_50700401_56_dialog_content = "¿Qué planean hacer con tantas bestias mecánicas?",
  ui_story_5070_50700401_57_dialog_content = "¿Crees que puedes darme una mano de nuevo, PlayerName?",
  ui_story_5070_50700401_58_dialog_content = "Necesitamos abrir todas estas cajas y revisar las bestias mecánicas en busca de marcas o símbolos.",
  ui_story_5070_50700401_59_dialog_content = "Ahora que lo mencionas, hiciste exactamente lo mismo con esos cangrejos de fuego antes.",
  ui_story_5070_50700401_60_dialog_content = "Pero no veo ninguna marca en las bestias mecánicas en ninguno de estos almacenes.",
  ui_story_5070_50700401_61_dialog_content = "Como dije antes, el Reino Ye regula estrictamente el uso de invenciones de relojería, así como sus planos y canales de envío.",
  ui_story_5070_50700401_62_dialog_content = "Ya sean producidos en masa en un taller o construidos a medida por un solo artesano...",
  ui_story_5070_50700401_63_dialog_content = "Cada máquina de relojería debe llevar una marca única al finalizar.",
  ui_story_5070_50700401_64_dialog_content = "De esa manera, siempre se puede responsabilizar a alguien si surgen problemas con la máquina.",
  ui_story_5070_50700401_65_dialog_content = "Entonces, si no podemos encontrar ninguna marca, ¿significa que nuestra investigación llegó a un callejón sin salida?",
  ui_story_5070_50700401_66_dialog_content = "No.",
  ui_story_5070_50700401_67_dialog_content = "Al menos, esto demuestra que estas máquinas no fueron construidas en un taller del Reino Ye.",
  ui_story_5070_50700401_68_dialog_content = "Sus componentes han sido sacados de contrabando del país y ensamblados aquí.",
  ui_story_5070_50700401_69_dialog_content = "También se guardan otras cosas en estos almacenes.",
  ui_story_5070_50700401_70_dialog_content = "Hay un montón de otros productos mezclados con las bestias mecánicas.",
  ui_story_5070_50700401_71_dialog_content = "Espera un minuto, estas marcas... ¿el gremio Lin?",
  ui_story_5070_50700401_72_dialog_content = "Precisamente.",
  ui_story_5070_50700401_73_dialog_content = "Hace un par de días, cuando el Shadowind llegó por primera vez al puerto, escuché a algunos de los pasajeros hablar de lo mismo.",
  ui_story_5070_50700401_74_dialog_content = "Algo sobre la familia Lin involucrándose en operaciones de contrabando en Longzhou y el jefe de la familia siendo arrestado por las Oficinas de Comercio Marítimo...",
  ui_story_5070_50700401_75_dialog_content = "PlayerName, ¿puedo pedirte otro favor?",
  ui_story_5070_50700401_76_dialog_content = "Necesito que le preguntes al Capitán Yuebai...",
  ui_story_5070_50700401_77_dialog_content = "Si la familia Lin está realmente involucrada en el contrabando.",
  ui_story_5070_50700401_78_dialog_content = "He estado buscando en almacenes desde que me atacaron esos cangrejos de fuego antes.",
  ui_story_5070_50700401_79_dialog_content = "Me pregunto si ya terminó el banquete de Shadowind.",
  ui_story_5070_50700401_80_dialog_content = "¿Eh? ¿Sucedió algo a bordo del barco?",
  ui_story_5070_50700401_81_dialog_content = "Seguramente eres consciente de los beneficios mutuos que nuestra cooperación traería, Telema.",
  ui_story_5070_50700401_82_dialog_content = "Por supuesto que los conozco. No insultes mi inteligencia.",
  ui_story_5070_50700401_83_dialog_content = "Pero no importa cuán grandioso sea Longzhou o cuán vital sea nuestra misión, ¿cuál es el punto si no podemos llegar a tu tierra natal de manera segura?",
  ui_story_5070_50700401_84_dialog_content = "He tomado varias precauciones para garantizar tu seguridad en cada paso del camino.",
  ui_story_5070_50700401_85_dialog_content = "Como un honorable ciudadano de Lumopolis, realmente deseo creerte.",
  ui_story_5070_50700401_86_dialog_content = "Pero... Con todo lo que ha pasado, me temo que debo reconsiderarlo.",
  ui_story_5070_50700401_87_dialog_content = "Telema...",
  ui_story_5070_50700401_88_dialog_content = "(¿No es ese el enviado de Lumopolis del que Dantang ha estado hablando? ¿Por qué el cambio repentino de actitud?)",
  ui_story_5070_50700401_89_dialog_content = "La última ubicación sospechosa que queda por buscar es esta farmacia.",
  ui_story_5070_50700401_90_dialog_content = "Este sentimiento... Parece que hay un poderoso usuario de Flame Force Arts en el interior.",
  ui_story_5070_50700401_91_dialog_content = "Ahora bien, veamos quién se esconde justo detrás de esta puerta.",
  ui_story_5070_50700401_92_dialog_content = "<size=45>¡Toc, toc, toc!</color>",
  ui_story_5070_50700401_93_dialog_content = "¿Qué es?",
  ui_story_5070_50700401_94_dialog_content = "Perdón por la intrusión, pero tengo algunas preguntas que me gustaría hacer.",
  ui_story_5070_50700401_95_dialog_content = "¿Conoces al dueño de ese almacén de allí?",
  ui_story_5070_50700401_96_dialog_content = "Si no, entonces ¿estás familiarizado con la familia Lin?",
  ui_story_5070_50700401_97_dialog_content = "...",
  ui_story_5070_50700401_98_dialog_content = "(¿La puerta se está abriendo? ¡Mejor prepárate para luchar! Completo—)",
  ui_story_5070_50700401_99_dialog_content = "...",
  ui_story_5070_50700401_100_dialog_content = "?",
  ui_story_5070_50700401_101_dialog_content = "¿Por qué hay un niño abriendo la puerta? Perdona, pero ¿podría hablar con un adulto?",
  ui_story_5070_50700401_102_dialog_content = "¿Quién dice que soy un niño?!",
  ui_story_5070_50700401_103_dialog_content = "Bueno, claramente eres un...",
  ui_story_5070_50700401_104_dialog_content = "<color=#e8d9bb>Timbre-!</color>",
  ui_story_5070_50700401_105_dialog_content = "Eres rápido con los pies.",
  ui_story_5070_50700401_106_dialog_content = "Sabía que debería haber revisado el almanaque antes de salir hoy. Estoy seguro de que me habría advertido sobre venir a un lugar donde reciben a los visitantes sacando sus espadas.",
  ui_story_5070_50700401_107_dialog_content = "<size=45>Graaah—</size>",
  ui_story_5070_50700401_108_dialog_content = "¿Oh? Vaya, esto es realmente un comité de bienvenida inesperado.",
  ui_story_5070_50700402_1_dialog_content = "Estos chicos simplemente no saben cuándo rendirse, ¿verdad?",
  ui_story_5070_50700402_2_dialog_content = "Seguimos matándolos, pero siguen apareciendo de la nada...",
  ui_story_5070_50700402_3_dialog_content = "¿Eh? ¡Oye! ¿No vas a pelear con ella, Zhong Xu?",
  ui_story_5070_50700402_4_dialog_content = "Un paraguas de metal, una libélula de cobre y otras creaciones mecánicas finamente elaboradas.",
  ui_story_5070_50700402_5_dialog_content = "¿Podrías ser... Ministra Armilla?",
  ui_story_5070_50700402_6_dialog_content = "Espera, ¿la conoces?",
  ui_story_5070_50700402_7_dialog_content = "Nunca nos hemos encontrado, pero he escuchado mucho sobre ella.",
  ui_story_5070_50700402_8_dialog_content = "Un genio artesano del Reino Ye perteneciente a la secta Qianyun.",
  ui_story_5070_50700402_9_dialog_content = "A los quince años, sorprendió a toda la nación con sus marionetas mecánicas capaces de tocar música de manera realista.",
  ui_story_5070_50700402_10_dialog_content = "Poco después, se convirtió en asesora estratégica para el rey de Ye.",
  ui_story_5070_50700402_11_dialog_content = "Mi entendimiento es que los títulos otorgados por el Reino Ye se basan en inventos famosos. Que te hayan dado el título de \"Armilla\" significa que tu reino realmente reconoce tu ingenio.",
  ui_story_5070_50700402_12_dialog_content = "Oh, no llegaría tan lejos. Además, me retiré de la escena política hace mucho tiempo; ahora solo soy un simple artesano.",
  ui_story_5070_50700402_13_dialog_content = "Pero tú, ¿un maestro espadachín con cabello rojo y conocimiento de la política de Longzhou...?",
  ui_story_5070_50700402_14_dialog_content = "Debes ser el Sr. Zhong Xu, el estimado asociado de la familia Lin, conocido y respetado por todos los gremios en el Reino de Ji.",
  ui_story_5070_50700402_15_dialog_content = "Tus palabras son más amables de lo que merezco, mi señora.",
  ui_story_5070_50700402_16_dialog_content = "Liqing.",
  ui_story_5070_50700402_17_dialog_content = "Esta mujer joven no es nuestra enemiga.",
  ui_story_5070_50700402_18_dialog_content = "No necesariamente.",
  ui_story_5070_50700402_19_dialog_content = "¡Oye! ¿Qué se supone que significa eso? ¡¿No tienes modales?!",
  ui_story_5070_50700402_20_dialog_content = "Shh, pequeño. Los adultos están hablando ahora.",
  ui_story_5070_50700402_21_dialog_content = "¡Te dije que no soy un niño!",
  ui_story_5070_50700402_22_dialog_content = "Hace medio año, el Reino de Ji estaba rastreando un envío de mercancías de contrabando.",
  ui_story_5070_50700402_23_dialog_content = "Después de una exhaustiva investigación, descubrieron que los barcos mercantes de la familia Lin eran los únicos que tenían acceso a sus registros de salida.",
  ui_story_5070_50700402_24_dialog_content = "El gremio Lin tampoco pudo proporcionar una explicación válida sobre el asunto.",
  ui_story_5070_50700402_25_dialog_content = "¿Y qué? ¿Crees que puedes culparlos basándote únicamente en coincidencias?",
  ui_story_5070_50700402_26_dialog_content = "Tienes un punto.",
  ui_story_5070_50700402_27_dialog_content = "Aunque los únicos sospechosos en el caso son la familia Lin, muchas personas aún consideran el asunto muy cuestionable.",
  ui_story_5070_50700402_28_dialog_content = "Pero después de buscar en los almacenes cercanos justo ahora...",
  ui_story_5070_50700402_29_dialog_content = "Encontré una gran cantidad de bestias mecánicas del Reino Ye, cuyas piezas probablemente también fueron contrabandeadas fuera del país.",
  ui_story_5070_50700402_30_dialog_content = "También encontré una buena cantidad de carga con la marca del Lin Guild mezclada con las bestias de relojería.",
  ui_story_5070_50700402_31_dialog_content = "Como un distinguido asociado de la familia Lin, seguramente debes saber algo sobre esto, ¿no?",
  ui_story_5070_50700402_32_dialog_content = "¿Serías tan amable de explicar?",
  ui_story_5070_50700402_33_dialog_content = "...",
  ui_story_5070_50700402_34_dialog_content = "Es cierto. Un barco mercante de la familia Lin realmente transportó bienes de contrabando.",
  ui_story_5070_50700402_35_dialog_content = "(¿Cómo puede ser tan terca esta persona Telema? No importa cuánto lo intente Dantang, parece que no llega a ninguna parte.)",
  ui_story_5070_50700402_36_dialog_content = "(¿Qué va a pasar con su misión si esto sigue así?)",
  ui_story_5070_50700402_37_dialog_content = "... Entiendo.",
  ui_story_5070_50700402_38_dialog_content = "Respetaré y acataré su decisión, Telema de Lumopolis.",
  ui_story_5070_50700402_39_dialog_content = "Me alegra que finalmente veas las cosas a mi manera.",
  ui_story_5070_50700402_40_dialog_content = "Siempre supe que una dama hermosa y noble como usted podría simpatizar con las dificultades de los demás.",
  ui_story_5070_50700402_41_dialog_content = "De manera similar, debo pedirte que también entiendas mi propia situación, Telema.",
  ui_story_5070_50700402_42_dialog_content = "¿Ah?",
  ui_story_5070_50700402_43_dialog_content = "PlayerName.",
  ui_story_5070_50700402_44_dialog_content = "¿Estarías dispuesto a tomar el lugar de Telema como emisario de Astra y regresar a Longzhou conmigo?",
  ui_story_5070_50700402_45_dialog_content = "... ¿¡Yo?!?",
  ui_story_5070_50700501_1_dialog_content = "¡N-No hay manera! ¿¡Cómo podría servir posiblemente como un emisario?!",
  ui_story_5070_50700501_2_dialog_content = "¿Y por qué no?",
  ui_story_5070_50700501_3_dialog_content = "Bueno, para empezar, no represento a una potencia importante como Lumopolis o la Federación Illumina.",
  ui_story_5070_50700501_4_dialog_content = "Sí, pero como parte neutral, ¿no crees que estás en la mejor posición para representar los intereses de Astra?",
  ui_story_5070_50700501_5_dialog_content = "No solo eso, tus experiencias en esta tierra son tan vastas como la red de aliados que has construido con el tiempo.",
  ui_story_5070_50700501_6_dialog_content = "Eres más que conocedor de los asuntos de Astra, así como de sus estrategias para defenderse de los Eclipsites.",
  ui_story_5070_50700501_7_dialog_content = "¿No coincide eso con nuestro objetivo de establecer un puente de comunicación entre nuestros dos continentes?",
  ui_story_5070_50700501_8_dialog_content = "Pero esto es...",
  ui_story_5070_50700501_9_dialog_content = "¡De acuerdo!",
  ui_story_5070_50700501_10_dialog_content = "¡PlayerName es famoso en Astra! No he escuchado más que elogios para él, incluso antes de que tuviéramos la oportunidad de conocernos.",
  ui_story_5070_50700501_11_dialog_content = "Como representante oficial de Lumopolis, estoy dispuesto a poner las responsabilidades de esta misión diplomática a Longzhou en tus manos!",
  ui_story_5070_50700501_12_dialog_content = "E-Espera... ¡Todavía necesito pensarlo!",
  ui_story_5070_50700501_13_dialog_content = "(Lumopolis, eh... Carleen dijo que siempre ha apoyado este intercambio. Estoy seguro de que estaría decepcionada si no se concretara.)",
  ui_story_5070_50700501_14_dialog_content = "(Dantang y sus aliados también han estado enfrentando todo tipo de problemas desde que llegaron a Astra.)",
  ui_story_5070_50700501_15_dialog_content = "(Muchas personas tienen sus esperanzas puestas en esta misión, ya que involucra el futuro de dos continentes. Si soy la única persona para el trabajo en este momento, entonces...)",
  ui_story_5070_50700501_16_dialog_content = "Lo haré lo mejor que pueda.",
  ui_story_5070_50700501_17_dialog_content = "PlayerName... ¡Estoy tan feliz de escuchar eso!!!",
  ui_story_5070_50700501_18_dialog_content = "¿Estás seguro de esto?",
  ui_story_5070_50700501_19_dialog_content = "Capitán Yuebai, ¿entonces también escuchaste todo?",
  ui_story_5070_50700501_20_dialog_content = "Puedes llamarme Yuebai.",
  ui_story_5070_50700501_21_dialog_content = "Ya que está decidido, entonces como capitán de Shadowind...",
  ui_story_5070_50700501_22_dialog_content = "Doy la bienvenida a PlayerName como el emisario de todo Astra.",
  ui_story_5070_50700501_23_dialog_content = "El viaje será peligroso, así que prepárate tanto física como psicológicamente para ello.",
  ui_story_5070_50700501_24_dialog_content = "Entiendo.",
  ui_story_5070_50700501_25_dialog_content = "Espera, Capitán Yuebai... quiero decir, Yuebai. ¿Podría molestarte un minuto?",
  ui_story_5070_50700501_26_dialog_content = "Verás, un amigo mío me pidió que te preguntara acerca de la familia Lin.",
  ui_story_5070_50700501_27_dialog_content = "Es cierto. Un barco mercante de la familia Lin realmente transportó bienes de contrabando.",
  ui_story_5070_50700501_28_dialog_content = "¿Por qué le estás contando todo esto, Zhong Xu?!",
  ui_story_5070_50700501_29_dialog_content = "¡Apareció en nuestra puerta con un montón de acusaciones sin fundamento! ¡Solo di unas palabras y mándala de vuelta!",
  ui_story_5070_50700501_30_dialog_content = "¡Escuché eso, tú sabes!",
  ui_story_5070_50700501_31_dialog_content = "Pero que hables de estas cosas tan abiertamente... No me digas que piensas pelear conmigo, Sr. Zhong Xu?",
  ui_story_5070_50700501_32_dialog_content = "No tengo intención de hacer eso.",
  ui_story_5070_50700501_33_dialog_content = "Pero si una sola frase fue suficiente para hacerte dudar, Ministra Armilla...",
  ui_story_5070_50700501_34_dialog_content = "Entonces tal vez no tengas la paciencia para escuchar el resto de la verdad.",
  ui_story_5070_50700501_35_dialog_content = "¿Oh?",
  ui_story_5070_50700501_36_dialog_content = "Entonces, ¿sólo estás dispuesto a compartir tu conocimiento con aquellos que están dispuestos a escuchar? ¿Es eso?",
  ui_story_5070_50700501_37_dialog_content = "De nada, mi señora.",
  ui_story_5070_50700501_38_dialog_content = "Simplemente quiero decir que mi salud no es buena y me canso muy fácilmente. Por esta razón, pensé que era mejor darte una respuesta concisa en este momento.",
  ui_story_5070_50700501_39_dialog_content = "Ya veo. Entonces, por favor, cuéntame la versión larga de la historia.",
  ui_story_5070_50700501_40_dialog_content = "Después de todo, sería grosero de mi parte no escuchar cuando estás siendo tan honesto conmigo, Sr. Zhong Xu.",
  ui_story_5070_50700501_41_dialog_content = "Je, así que estás dispuesto a escuchar a los demás de vez en cuando.",
  ui_story_5070_50700501_42_dialog_content = "Eso es porque soy un adulto, pequeño.",
  ui_story_5070_50700501_43_dialog_content = "¡Deja de llamarme así! ¡Entiéndelo de una vez!",
  ui_story_5070_50700501_44_dialog_content = "Entonces, ¿qué fue exactamente lo que el barco mercante de la familia Lin encontró en el mar hace medio año?",
  ui_story_5070_50700501_45_dialog_content = "Piratas.",
  ui_story_5070_50700501_46_dialog_content = "Como de costumbre, los barcos de la familia Lin zarpan del Reino Ji al comienzo del trimestre.",
  ui_story_5070_50700501_47_dialog_content = "Pero al entrar en las aguas de Astra, la tripulación descubrió un envío de mercancías sin marcar y sin registrar escondido en la bodega.",
  ui_story_5070_50700501_48_dialog_content = "Poco después, se descubrió a varios piratas entre los pasajeros del barco.",
  ui_story_5070_50700501_49_dialog_content = "Entonces, ¿estos estaban usando el barco de la familia Lin para contrabandear productos ilegales?",
  ui_story_5070_50700501_50_dialog_content = "Precisamente.",
  ui_story_5070_50700501_51_dialog_content = "Pero su plan fue descubierto en el camino, así que los piratas recurrieron a la violencia para secuestrar el barco mercante.",
  ui_story_5070_50700501_52_dialog_content = "Al final, los únicos dos supervivientes fuimos Liqing, quien se desempeñaba como médico del barco en ese momento, y yo mismo.",
  ui_story_5070_50700501_53_dialog_content = "Zhong Xu también cayó por la borda después de resultar gravemente herido. Casi no lo logra.",
  ui_story_5070_50700501_54_dialog_content = "Me llevó todas mis fuerzas mantenerlo con vida, así que no pude salvar sus piernas. Así es como terminó así.",
  ui_story_5070_50700501_55_dialog_content = "No tienes razón para culparte a ti mismo, Liqing. Ya estoy eternamente agradecido contigo por salvarme la vida.",
  ui_story_5070_50700501_56_dialog_content = "Si realmente estás tan agradecido, entonces deberías escucharme y descansar más.",
  ui_story_5070_50700501_57_dialog_content = "Cada vez que aparecen invitados no deseados en nuestra puerta, siempre sales a enfrentarte a ellos sin preocuparte por ti mismo—",
  ui_story_5070_50700501_58_dialog_content = "¿Invitados no deseados?",
  ui_story_5070_50700501_59_dialog_content = "¡Graaah—!",
  ui_story_5070_50700501_60_dialog_content = "Hablando del diablo, ¡aquí están de nuevo!",
  ui_story_5070_50700501_61_dialog_content = "Siempre aparecen en el momento en que dejamos de prestar atención. ¡Hacen que comer y dormir sea un verdadero dolor!",
  ui_story_5070_50700501_62_dialog_content = "Completo—",
  ui_story_5070_50700501_63_dialog_content = "¡A cenizas!",
  ui_story_5070_50700501_64_dialog_content = "...",
  ui_story_5070_50700501_65_dialog_content = "¿Qué acabo de decir, Zhong Xu?! ¡Esto es exactamente por qué te está llevando tanto tiempo recuperarte!",
  ui_story_5070_50700501_66_dialog_content = "Lo que queda de mi vida ya no es importante.",
  ui_story_5070_50700501_67_dialog_content = "Pero el maestro del gremio Lin...",
  ui_story_5070_50700501_68_dialog_content = "Le hice una promesa en aquel entonces. ¿Cómo podría dejarlo morir en prisión cuando fue arrestado injustamente?",
  ui_story_5070_50700501_69_dialog_content = "Por eso no puedo morir. Todavía no.",
  ui_story_5070_50700501_70_dialog_content = "Juro que regresaré a Longzhou y limpiaré su buen nombre antes de dar mi último aliento.",
  ui_story_5070_50700501_71_dialog_content = "No es de extrañar que ustedes dos fueran tan cautelosos conmigo cuando llegué por primera vez.",
  ui_story_5070_50700501_72_dialog_content = "¿Has estado luchando contra estas bestias mecánicas todo el tiempo?",
  ui_story_5070_50700501_73_dialog_content = "¡Tampoco ha faltado cantidad de mercenarios occidentales persiguiéndonos!",
  ui_story_5070_50700501_74_dialog_content = "Parece que esos piratas cuentan con el respaldo de poderes aún mayores en el mundo.",
  ui_story_5070_50700501_75_dialog_content = "Con tantos asesinos persiguiéndonos constantemente, temo que estos poderes deseen vernos enterrados en estas tierras extranjeras, junto con la verdad.",
  ui_story_5070_50700501_76_dialog_content = "Si tienen éxito, la Familia Lin nunca será exonerada de estos falsos crímenes.",
  ui_story_5070_50700501_77_dialog_content = "Incluso en un momento como este, todo en lo que puedes pensar es en la familia Lin... Realmente no sé si eso es bueno o malo, Zhong Xu.",
  ui_story_5070_50700501_78_dialog_content = "¡Graaah—!",
  ui_story_5070_50700501_79_dialog_content = "¡Argh! ¡No otra vez!",
  ui_story_5070_50700501_80_dialog_content = "Por favor, perdone mi descortesía de hace un momento, Ministra Armilla. Desconocía su verdadera identidad.",
  ui_story_5070_50700501_81_dialog_content = "No deseo que te veas involucrado en nuestros problemas, así que por favor escapa mientras puedas.",
  ui_story_5070_50700501_82_dialog_content = "No te preocuparías por implicarme.",
  ui_story_5070_50700501_83_dialog_content = "En todo caso, soy el perpetrador aquí.",
  ui_story_5070_50700501_84_dialog_content = "Yo fui quien diseñó estas bestias mecánicas...",
  ui_story_5070_50700501_85_dialog_content = "Pero nunca se suponía que fueran explotados y convertidos en armas por villanos escondidos en las sombras.",
  ui_story_5070_50700501_86_dialog_content = "Al principio estaba preocupado de que no encontraría más pistas, pero los tontos las han entregado directamente en mis manos.",
  ui_story_5070_50700501_87_dialog_content = "En realidad, debería estar agradeciéndoles a los dos, sinceramente.",
  ui_story_5070_50700501_88_dialog_content = "Tienes suerte, Sr. Zhong Xu. Parece que tenemos un enemigo en común.",
  ui_story_5070_50700501_89_dialog_content = "... Entonces, después de todo eso, ¿nunca fuimos enemigos desde el principio?!",
  ui_story_5070_50700501_90_dialog_content = "¡Nuestros enemigos probablemente se morían de risa, viéndonos discutir todo el día!",
  ui_story_5070_50700501_91_dialog_content = "No te preocupes, pequeño. Después de encargarnos de estos malos, te haré todo tipo de juguetes divertidos para jugar.",
  ui_story_5070_50700501_92_dialog_content = "¿Qué te parece una bonita y brillante bola?",
  ui_story_5070_50700501_93_dialog_content = "También puedo reparar la silla de ruedas del Sr. Zhong Xu y agregarle algunas funciones nuevas, ¿si lo desea?",
  ui_story_5070_50700501_94_dialog_content = "Tu buena voluntad es muy apreciada.",
  ui_story_5070_50700501_95_dialog_content = "Pero esta silla de ruedas es solo mi medio de transporte. No requiere modificaciones innecesarias.",
  ui_story_5070_50700501_96_dialog_content = "¡Jajaja! Puede que no seas un artesano, Sr. Zhong Xu, pero definitivamente entiendes el verdadero significado de nuestro oficio.",
  ui_story_5070_50700501_97_dialog_content = "Y eso te hace cien veces más poderoso que los cobardes que manejan los hilos de toda esta conspiración.",
  ui_story_5070_50700502_1_dialog_content = "Y eso... es lo que le sucedió a la familia Lin.",
  ui_story_5070_50700502_2_dialog_content = "Escuché rumores sobre la participación del Lin Guild en un incidente de contrabando hace seis meses, así como el daño que causó a su nombre. Sin embargo, esta es la primera vez que me cuentan los detalles del asunto.",
  ui_story_5070_50700502_3_dialog_content = "Si lo que dices es cierto, el veredicto en este caso parece bastante arbitrario.",
  ui_story_5070_50700502_4_dialog_content = "No hay pruebas concluyentes de que la familia Lin esté contrabandeando, pero todo lo demás parece indicarlo.",
  ui_story_5070_50700502_5_dialog_content = "Esto sin duda pone a la Familia Lin en desventaja. Todo lo que pueden hacer es soportar la vergüenza de este crimen.",
  ui_story_5070_50700502_6_dialog_content = "Esto también explica por qué la familia Lin estaba tan decidida a enfrentarse a los mares a pesar de perder su esfera armilar.",
  ui_story_5070_50700502_7_dialog_content = "Están desesperados por encontrar una oportunidad para restablecer sus rutas comerciales y revitalizar su gremio.",
  ui_story_5070_50700502_8_dialog_content = "*Suspiro* La tripulación de Shadowind ha estado plagada de problemas desde el principio.",
  ui_story_5070_50700502_9_dialog_content = "Por eso están tan ansiosos por zarpar y regresar a Longzhou.",
  ui_story_5070_50700502_10_dialog_content = "PlayerName.",
  ui_story_5070_50700502_11_dialog_content = "¿Qué pasa, Dantang? ¿Y por qué te ves tan serio?",
  ui_story_5070_50700502_12_dialog_content = "El mar es un lugar impredecible. Desde tiempos inmemoriales, innumerables barcos no han logrado regresar a salvo de travesías tan largas como esta.",
  ui_story_5070_50700502_13_dialog_content = "Aparte de las rutas marítimas siempre cambiantes y las emboscadas enemigas, el viaje que nos espera estará lleno de otros peligros ocultos.",
  ui_story_5070_50700502_14_dialog_content = "Si estás dispuesto a abordar el Shadowind, también debes estar dispuesto a aventurarte en lo desconocido.",
  ui_story_5070_50700502_15_dialog_content = "Yuebai está comprometido con la restauración del Lin Guild, y yo tengo mis propias responsabilidades, las cuales no puedo abandonar.",
  ui_story_5070_50700502_16_dialog_content = "Todos tenemos nuestras razones para enfrentarnos al mar y hemos aceptado las consecuencias de hacerlo.",
  ui_story_5070_50700502_17_dialog_content = "Pero tú eres diferente, PlayerName.",
  ui_story_5070_50700502_18_dialog_content = "... Como Princesa Zhuohua, arrastrarte a nuestros problemas fue la única solución que se me ocurrió en ese momento.",
  ui_story_5070_50700502_19_dialog_content = "Pero como tu amigo, Dantang... me preocupo por tu seguridad.",
  ui_story_5070_50700502_20_dialog_content = "Entendería completamente si decides rechazar mi oferta.",
  ui_story_5070_50700502_21_dialog_content = "Honestamente, no sé qué esperaba que dijeras.",
  ui_story_5070_50700502_22_dialog_content = "¿Ah?",
  ui_story_5070_50700502_23_dialog_content = "Dices que me \"arrastraste\" a tus problemas.",
  ui_story_5070_50700502_24_dialog_content = "Pero ya sea que sea el enviado de Astra, el último de los Celestitas, o simplemente el viejo yo.",
  ui_story_5070_50700502_25_dialog_content = "Siempre tomo en cuenta cuidadosamente estas situaciones antes de tomar cualquier decisión.",
  ui_story_5070_50700502_26_dialog_content = "Y como tu amigo, naturalmente también quiero ayudarte.",
  ui_story_5070_50700502_27_dialog_content = "PlayerName... Si ese es el caso, entonces juro que haré todo lo que esté en mi poder para protegerte en este viaje.",
  ui_story_5070_50700502_28_dialog_content = "Solo rezo para que no enfrentemos demasiados desafíos en el camino...",
  ui_story_5070_50700502_29_dialog_content = "¿Oh? ¿Por qué el barco aún no ha partido? ¿Y por qué todos parecen estar a punto de llorar?",
  ui_story_5070_50700502_30_dialog_content = "...",
  ui_story_5070_50700502_31_dialog_content = "¡Relájense, todos! Resulta que encontré a un experimentado veterano de combate y a un médico legendario para llevar en el viaje.",
  ui_story_5070_50700502_32_dialog_content = "Y si lo peor llega a lo peor, ¡también estaré cerca!",
  ui_story_5070_50700502_33_dialog_content = "Puede que ya no sea consejero del rey de Ye, pero enfrentaría una montaña de espadas y un mar de llamas si la princesa lo ordenara.",
  ui_story_5070_50700502_34_dialog_content = "¡Su Alteza, la Señora Xuan Ji ha regresado!",
  ui_story_5070_50700502_35_dialog_content = "Sí, pude darme cuenta por todo el ruido que era ella.",
  ui_story_5070_50700502_36_dialog_content = "Tus palabras son tan excéntricas como siempre, Ministra Armilla.",
  ui_story_5070_50700502_37_dialog_content = "Ten cuidado, o podría ponerte en ese tipo de dilema peligroso.",
  ui_story_5070_50700502_38_dialog_content = "¡Jajajaja! Bueno, ya basta de bromas por ahora.",
  ui_story_5070_50700502_39_dialog_content = "Escuché que el Shadowind fue atacado antes, así que necesito inspeccionar su casco una vez más.",
  ui_story_5070_50700502_40_dialog_content = "Nunca pensé que mis cangrejos de fuego serían utilizados para atacar un barco algún día.",
  ui_story_5070_50700502_41_dialog_content = "Parece que también tendré que reforzar o modificar los sistemas de suministro de energía y navegación.",
  ui_story_5070_50700502_42_dialog_content = "No te preocupes, haré todo lo posible para que este barco sea lo más seguro posible antes de salir al mar.",
  ui_story_5070_50700601_1_dialog_content = "(Queridos Vice y Carleen.)",
  ui_story_5070_50700601_2_dialog_content = "(Perdón por responder tan tarde. En un abrir y cerrar de ojos, nuestro día de partida finalmente llegó.)",
  ui_story_5070_50700601_3_dialog_content = "(Estamos en medio de hacer nuestros preparativos finales para el viaje, así que todos han estado muy ocupados últimamente.)",
  ui_story_5070_50700601_4_dialog_content = "¡Carpintero de barcos Li! ¡Haz que tu equipo aplique un revestimiento resistente al fuego en las secciones críticas del casco!",
  ui_story_5070_50700601_5_dialog_content = "Necesitamos estar preparados para incendios inesperados, ¡así como para ataques de cangrejos de fuego!",
  ui_story_5070_50700601_6_dialog_content = "Voy a inspeccionar el barco en busca de señales de fugas.",
  ui_story_5070_50700601_7_dialog_content = "Además, ¿alguien sabe dónde está la capitana? Necesito convencerla de comprar algunos dispositivos de almacenamiento de energía más antes de que nos vayamos de Astra.",
  ui_story_5070_50700601_8_dialog_content = "Cualquier cosa puede pasar en el mar, y tener reservas de energía adicionales nos ayudará a estar preparados.",
  ui_story_5070_50700601_9_dialog_content = "Sr. Zhong Xu?",
  ui_story_5070_50700601_10_dialog_content = "Perdóname por no hablar contigo antes. Los últimos días han sido muy ocupados...",
  ui_story_5070_50700601_11_dialog_content = "Gracias por contarme la verdad sobre el incidente de contrabando. Con esta información, el buen nombre de la familia Lin finalmente puede ser restaurado.",
  ui_story_5070_50700601_12_dialog_content = "Estoy seguro de que el regreso seguro de Lin Guildmaster también lo animará aún más. Para entonces, no deberíamos tener problemas para superar estos obstáculos.",
  ui_story_5070_50700601_13_dialog_content = "Simplemente estoy cumpliendo con mi deber... Después de todo, fui yo quien no pudo protegerlo.",
  ui_story_5070_50700601_14_dialog_content = "Aun así, no se sabe cuándo los piratas atacarán de nuevo.",
  ui_story_5070_50700601_15_dialog_content = "Durante nuestro encuentro hace seis meses, pude discernir aproximadamente su método de ataque.",
  ui_story_5070_50700601_16_dialog_content = "Podemos utilizar esta información para formular nuestras contramedidas.",
  ui_story_5070_50700601_17_dialog_content = "Sándalo, pasto en polvo, menta, arrurruz...",
  ui_story_5070_50700601_18_dialog_content = "¿Tienes estas hierbas en stock? Si es así, ¡me llevaré todo lo que tengas!",
  ui_story_5070_50700601_19_dialog_content = "Eso es un pedido bastante grande, joven.",
  ui_story_5070_50700601_20_dialog_content = "Oye, yo no elegí ser responsable de la salud de todo un barco.",
  ui_story_5070_50700601_21_dialog_content = "Necesito abastecerme de todo lo que pueda usarse para tratar cosas como escalofríos y mareos. ¡Cuanto más, mejor!",
  ui_story_5070_50700601_22_dialog_content = "Todos están ocupados haciendo quién sabe qué, así que alguien tiene que asegurarse de que tengamos suficientes suministros médicos para el viaje, ¿verdad?",
  ui_story_5070_50700601_23_dialog_content = "Ahora solo necesito comprar suficiente comida para mantener a todos en buen estado de salud mientras estamos en el mar.",
  ui_story_5070_50700601_24_dialog_content = "¿Ya terminaste de escribir tus cartas de despedida, Jiu?",
  ui_story_5070_50700601_25_dialog_content = "Sí, Su Alteza. La verdad es que no necesito despedirme de muchas personas.",
  ui_story_5070_50700601_26_dialog_content = "Pero, ¿realmente necesitas enviar tantas cartas?",
  ui_story_5070_50700601_27_dialog_content = "Hicimos muchos amigos y conocimos a muchas personas importantes durante nuestro tiempo aquí, después de todo.",
  ui_story_5070_50700601_28_dialog_content = "Debemos mantener nuestras buenas relaciones si queremos trabajar juntos en el futuro.",
  ui_story_5070_50700601_29_dialog_content = "Esto me recuerda que todavía necesito escribir una carta a la Asociación de Gremios de Twin Pavilions Bay.",
  ui_story_5070_50700601_30_dialog_content = "Cómplices de piratas han aparecido en la ciudad y necesitan ser detenidos lo más pronto posible.",
  ui_story_5070_50700601_31_dialog_content = "(Incluso tuve que hacer un par de viajes a Umbraton para ayudar a todos a comprar cosas que solo se pueden encontrar en Astra.)",
  ui_story_5070_50700601_32_dialog_content = "(Honestamente, me hizo sentir mucho más como un verdadero emisario de Astra.)",
  ui_story_5070_50700601_33_dialog_content = "(Una vez que envíe esta carta, el Shadowind zarpará poco después).",
  ui_story_5070_50700601_34_dialog_content = "(Espero estar a la altura de las expectativas de todos y completar mi misión sin demasiados problemas.)",
  ui_story_5070_50700601_35_dialog_content = "(Cuando regrese, ¡me aseguraré de traer muchas historias de Longzhou para que todos las escuchen!)",
  ui_story_5070_50700601_36_dialog_content = "¡Bueno, si no es PlayerName!",
  ui_story_5070_50700601_37_dialog_content = "¡Oye, eres ese adivino de antes!",
  ui_story_5070_50700601_38_dialog_content = "¡Ni una palabra más, amigo! Mis poderes de adivinación me dicen que acabas de enviar una carta. ¿Es eso correcto?",
  ui_story_5070_50700601_39_dialog_content = "...",
  ui_story_5070_50700601_40_dialog_content = "¿De qué estás hablando? Claramente me acabas de ver salir de la Unión de Mensajeros.",
  ui_story_5070_50700601_41_dialog_content = "Jeje, solo estoy bromeando.",
  ui_story_5070_50700601_42_dialog_content = "Al igual que tú, también soy un pasajero a bordo del Shadowind.",
  ui_story_5070_50700601_43_dialog_content = "¿Te gustaría regresar al barco conmigo?",
  ui_story_5070_50700601_44_dialog_content = "Supongo que no. ¿También estabas enviando una carta?",
  ui_story_5070_50700601_45_dialog_content = "Es mejor si no hablamos de eso.",
  ui_story_5070_50700601_46_dialog_content = "Quería disfrutar de una última comida en Astra antes de regresar a casa, pero no he tenido mucha suerte hoy.",
  ui_story_5070_50700601_47_dialog_content = "A pesar de deambular por la ciudad durante medio día, no he tenido la suerte de encontrarme con personas adineradas.",
  ui_story_5070_50700601_48_dialog_content = "Una pena, de verdad.",
  ui_story_5070_50700601_49_dialog_content = "¿Qué tienen que ver los ricos contigo comiendo una comida?",
  ui_story_5070_50700601_50_dialog_content = "Puede que no lo sepas, pero a pesar de mi apariencia sencilla...",
  ui_story_5070_50700601_51_dialog_content = "En realidad, soy aún más pobre de lo que parezco. De hecho, ¡no tengo ni un solo Nightium a mi nombre!",
  ui_story_5070_50700601_52_dialog_content = "Y tú... ¿elegiste viajar por el mundo a pesar de eso?",
  ui_story_5070_50700601_53_dialog_content = "Bueno, soy bastante diferente a los otros pasajeros. No tengo motivos especiales de los que hablar, per se.",
  ui_story_5070_50700601_54_dialog_content = "Mi curiosidad por ver tierras lejanas es lo que me impulsa a viajar. Para mí, lo que más disfruto es el viaje en sí.",
  ui_story_5070_50700601_55_dialog_content = "No hace diferencia si viajo a otro continente o al otro lado de un estanque.",
  ui_story_5070_50700601_56_dialog_content = "... Bien entonces.",
  ui_story_5070_50700601_57_dialog_content = "(Aunque apenas entendí algo de lo que dijo, de alguna manera tiene sentido.)",
  ui_story_5070_50700601_58_dialog_content = "Me encuentras un poco verboso, ¿no, amigo mío?",
  ui_story_5070_50700601_59_dialog_content = "Entonces, ¿por qué no te hago una adivinación de verdad?",
  ui_story_5070_50700601_60_dialog_content = "Mi Adivinación Hexagrama Celestial incluye ratas, bueyes, tigres, conejos y todos los demás animales del zodiaco, y los divide en yin y yang.",
  ui_story_5070_50700601_61_dialog_content = "Con ello, puedo discernir los secretos del cielo y predecir el futuro. ¡No puedo garantizar que tengas otra oportunidad como esta!",
  ui_story_5070_50700601_62_dialog_content = "¿Ratas y bueyes? Pero, ¿no son solo animales? ¿Qué pueden mostrarte?",
  ui_story_5070_50700601_63_dialog_content = "Una gran cantidad de conocimientos, amigo mío.",
  ui_story_5070_50700601_64_dialog_content = "Tomemos el Shadowind como ejemplo. Vamos, podemos caminar mientras hablamos.",
  ui_story_5070_50700601_65_dialog_content = "¿Sabías que los doce animales del zodíaco están a bordo del barco?",
  ui_story_5070_50700601_66_dialog_content = "Bueno, las ratas en un barco no son algo nuevo, pero aún no he visto bueyes.",
  ui_story_5070_50700601_67_dialog_content = "La gente de Longzhou es muy particular con respecto a las imágenes. De hecho, ciertas cosas se nombran según las imágenes a las que se asemejan.",
  ui_story_5070_50700601_68_dialog_content = "¿Ves esa cuña utilizada para estabilizar el mástil del barco? En nuestras tierras, se le conoce como \"puente de rata\".",
  ui_story_5070_50700601_69_dialog_content = "¿Y las barandillas a lo largo de los bordes de la cubierta? A esas se les llama \"vallas de buey\".",
  ui_story_5070_50700601_70_dialog_content = "Las tablas en la cubierta se llaman \"caras de caballo\", mientras que el armazón del barco se conoce como el \"esqueleto del dragón\". ¿Necesito explicar más?",
  ui_story_5070_50700601_71_dialog_content = "No me di cuenta de que tenían nombres tan imaginativos.",
  ui_story_5070_50700601_72_dialog_content = "De hecho, y al igual que este barco, mis hexagramas reflejan toda la existencia, lo que me permite ver el futuro.",
  ui_story_5070_50700601_73_dialog_content = "Entonces, ¿puedes ver qué va a pasar con este barco durante nuestro viaje?",
  ui_story_5070_50700601_74_dialog_content = "De nuevo... Es mejor si no preguntas. Solo ten en cuenta que también hice una predicción cuando el Shadowind fue atacado antes.",
  ui_story_5070_50700601_75_dialog_content = "El resultado fue el buey yin y el caballo yin.",
  ui_story_5070_50700601_X75_dialog_content = "\"El buey muerto no se mueve, y el caballo muerto no relincha\". Al principio, pensé que significaba que el barco no podría salir del puerto...",
  ui_story_5070_50700601_76_dialog_content = "¡Pero el Shadowind está a punto de partir!",
  ui_story_5070_50700601_77_dialog_content = "De hecho, esto significa que mi predicción requiere una interpretación más profunda. Tal vez pueda obtener más inspiración de las caras de caballo y las vallas de buey a bordo del barco?",
  ui_story_5070_50700601_78_dialog_content = "Es sabio no escuchar las divagaciones de un mentiroso, PlayerName.",
  ui_story_5070_50700601_79_dialog_content = "Vamos, Su Alteza. Mi arte es solo un medio para alimentarme, nada más.",
  ui_story_5070_50700601_80_dialog_content = "No le hagas caso, PlayerName. La mayoría de los pasajeros ya están en el barco, así que por favor sube a bordo.",
  ui_story_5070_50700601_81_dialog_content = "... Permítame repasar la lista de pasajeros por última vez.",
  ui_story_5070_50700601_82_dialog_content = "Sr. Zhong Xu, Doctor Liqing, Princesa Dantang, Señorita Jiu y PlayerName.",
  ui_story_5070_50700601_83_dialog_content = "Li, Sun y Lady Xuan Ji también se unirán a nuestro viaje a Longzhou como técnicos del Shadowind.",
  ui_story_5070_50700601_84_dialog_content = "Todos están presentes y contabilizados ahora.",
  ui_story_5070_50700601_85_dialog_content = "...",
  ui_story_5070_50700601_86_dialog_content = "Como capitán del barco, debería ser la última persona en aumentar las preocupaciones de sus pasajeros.",
  ui_story_5070_50700601_87_dialog_content = "Pero, dadas las circunstancias especiales de nuestro viaje, siento que debo dejar algo muy claro para todos.",
  ui_story_5070_50700601_88_dialog_content = "Sin nuestra esfera armilar, no se puede determinar la ubicación del Shadowind mientras navegamos en alta mar.",
  ui_story_5070_50700601_89_dialog_content = "Nos corresponde determinar el rumbo del barco.",
  ui_story_5070_50700601_90_dialog_content = "Tormentas repentinas, feroces Eclipsites e incluso enemigos invisibles también son de esperar allá afuera.",
  ui_story_5070_50700601_91_dialog_content = "Los peligros que nos esperan serán mucho mayores que cualquier cosa que hayamos enfrentado en viajes anteriores.",
  ui_story_5070_50700601_92_dialog_content = "Si alguien desea abandonar el barco, ahora es el momento de hacerlo.",
  ui_story_5070_50700601_93_dialog_content = "(Como era de esperar, nadie se mueve ni un músculo. Todos están decididos a hacer el viaje de regreso.)",
  ui_story_5070_50700601_94_dialog_content = "Ya que todos ustedes han decidido confiar en el Shadowind, como capitán del barco, juro llevarnos a salvo a las costas de Longzhou.",
  ui_story_5070_50700601_95_dialog_content = "¡El Shadowind zarpa ahora!",
  ui_story_5070_50700701_1_dialog_content = "<color=#e8d9bb>Chapoteo... Chapoteo...</color>",
  ui_story_5070_50700701_2_dialog_content = "(Han pasado unos días desde que salimos. Esta es la primera vez que dejo Astra en barco.)",
  ui_story_5070_50700701_3_dialog_content = "(El cielo azul, las olas, la refrescante brisa marina y un destino desconocido... Además, un poco de soledad.)",
  ui_story_5070_50700701_4_dialog_content = "Estás tan absorto. ¿Qué tienes en mente?",
  ui_story_5070_50700701_5_dialog_content = "¡Oh, Xuan Ji!",
  ui_story_5070_50700701_6_dialog_content = "Estaba pensando que la sensación de cruzar el océano en barco es totalmente diferente a montar un Coloso.",
  ui_story_5070_50700701_7_dialog_content = "¿Oh? ¿Cómo está en el Coloso?",
  ui_story_5070_50700701_8_dialog_content = "Es raro que saques el tema. En general, un Colossus es una máquina, ¿verdad?",
  ui_story_5070_50700701_9_dialog_content = "¿No es eso un poco amplio?",
  ui_story_5070_50700701_10_dialog_content = "Ese no es el punto.",
  ui_story_5070_50700701_11_dialog_content = "El punto es, ¿realmente puedes controlar ese coloso más grande que Shadowind por ti mismo?",
  ui_story_5070_50700701_12_dialog_content = "¿Qué tan rápido es? ¿Cuál es el consumo de combustible? ¿Cómo manejan los materiales los cambios de estaciones?",
  ui_story_5070_50700701_13_dialog_content = "Como máquina voladora, además de la propulsión, su forma también afecta la aerodinámica y la elevación...",
  ui_story_5070_50700701_14_dialog_content = "Nunca me explicaste del todo eso antes.",
  ui_story_5070_50700701_15_dialog_content = "E-Espera un segundo... ¿Acabo de abrir una lata de gusanos...?",
  ui_story_5070_50700701_16_dialog_content = "Bueno, si es confidencial, ¡deberíamos mantenerlo así!",
  ui_story_5070_50700701_17_dialog_content = "No es confidencial. Simplemente es que incluso yo no puedo ofrecer una respuesta adecuada a algunas preguntas.",
  ui_story_5070_50700701_18_dialog_content = "¡Piénsalo! La borda, el timón, el mástil del Shadowind...",
  ui_story_5070_50700701_19_dialog_content = "Yuebai y su grupo tienen que manejar todo en el barco manualmente.",
  ui_story_5070_50700701_20_dialog_content = "Si hay algún cambio en la velocidad o dirección del viento, deben decidir cómo modificar la nave de inmediato.",
  ui_story_5070_50700701_21_dialog_content = "Pero la información en su base de datos permite que Soroz maneje todo este tipo de cosas.",
  ui_story_5070_50700701_22_dialog_content = "Solo en momentos críticos necesito guiarlo con palabras o melodías.",
  ui_story_5070_50700701_23_dialog_content = "Entonces va más allá del simple control, permitiendo que realice rutinas lógicas y simplemente ejecute comandos.",
  ui_story_5070_50700701_24_dialog_content = "Es como un mito hecho realidad.",
  ui_story_5070_50700701_25_dialog_content = "¿Mito? ¿Longzhou?",
  ui_story_5070_50700701_26_dialog_content = "Correcto. Los libros de historia antigua hablaban de genios lo suficientemente grandes como para bloquear el sol.",
  ui_story_5070_50700701_27_dialog_content = "Operado por personas llamadas \"Asistentes de Djinn\" para atravesar la tierra y el mar en conquistas.",
  ui_story_5070_50700701_28_dialog_content = "¡Guau, eso es increíble... Soroz no puede bloquear el sol.",
  ui_story_5070_50700701_29_dialog_content = "Por más alto que vueles, el cielo y la luna siempre parecen estar fuera de alcance...",
  ui_story_5070_50700701_30_dialog_content = "No estoy seguro de eso.",
  ui_story_5070_50700701_31_dialog_content = "¿Ah?",
  ui_story_5070_50700701_32_dialog_content = "Subí a la cubierta para medir la altitud del sol.",
  ui_story_5070_50700701_33_dialog_content = "¿Ese no es el nombre de algo, verdad? ¿El sol sobre nosotros?",
  ui_story_5070_50700701_34_dialog_content = "Hay una antigua escuela de astrología en Longzhou.",
  ui_story_5070_50700701_35_dialog_content = "Todo lo que necesitas es un astrolabio para calcular la distancia entre el sol, la luna o incluso dos estrellas cualesquiera.",
  ui_story_5070_50700701_36_dialog_content = "Dado que podemos calcular la altitud y la trayectoria...",
  ui_story_5070_50700701_37_dialog_content = "¡No será difícil ajustar el marco de tu Colossus para bloquear el sol!",
  ui_story_5070_50700701_38_dialog_content = "Es obviamente una hipérbole, pero viniendo de ti, no sonó como una broma en absoluto...",
  ui_story_5070_50700701_39_dialog_content = "Entonces estaré agradecido por tu confianza en mí.",
  ui_story_5070_50700701_40_dialog_content = "Pero sí conozco el principio de \"lento y seguro gana la carrera\", construyendo un dispositivo pieza por pieza.",
  ui_story_5070_50700701_41_dialog_content = "Aunque no podemos llegar allí ahora mismo...",
  ui_story_5070_50700701_42_dialog_content = "Pero aún podemos hacer mucho sabiendo la posición, el ángulo y otros datos del sol.",
  ui_story_5070_50700701_43_dialog_content = "Por ejemplo, complementando las cartas de Lin para averiguar las coordenadas actuales de Shadowind.",
  ui_story_5070_50700701_44_dialog_content = "Mientras siempre estés consciente de tu posición, ¡nunca te perderás en el mar!",
  ui_story_5070_50700701_45_dialog_content = "Más fácil decirlo que hacerlo. El mar es demasiado impredecible para que una estimación artificial se mantenga consistente y precisa.",
  ui_story_5070_50700701_46_dialog_content = "Por eso, el esfera armilar, capaz de mostrar constelaciones y ubicaciones precisas, es apreciado como el tesoro de Lin.",
  ui_story_5070_50700701_47_dialog_content = "Hace imposible desviar intencionalmente un barco del rumbo con un astrónomo competente a bordo.",
  ui_story_5070_50700701_48_dialog_content = "Lástima, eso sí...",
  ui_story_5070_50700701_49_dialog_content = "Esfera armilar... Recuerdo que estaba en ese barco de la familia Lin que fue secuestrado por piratas, desapareciendo junto con el barco.",
  ui_story_5070_50700701_50_dialog_content = "Sí, por eso estoy llenando.",
  ui_story_5070_50700701_51_dialog_content = "Todo fue hecho por aparatos en el pasado, así que qué impactante es que un artesano tome el lugar de la máquina.",
  ui_story_5070_50700701_52_dialog_content = "Pero de esta manera, Xuan Ji también podría considerarse el navegante de Shadowind.",
  ui_story_5070_50700701_53_dialog_content = "Solo temporalmente.",
  ui_story_5070_50700701_54_dialog_content = "No te menosprecies, Ministra Armilla.",
  ui_story_5070_50700701_55_dialog_content = "El nombre Xuan Ji significa Armilla, que es otro nombre para la esfera armilar.",
  ui_story_5070_50700701_56_dialog_content = "Armilla es el título perfecto para ti.",
  ui_story_5070_50700701_57_dialog_content = "Entonces, lo más adecuado sería que Xuan Ji reemplace la esfera.",
  ui_story_5070_50700701_58_dialog_content = "¿Me lo estoy imaginando? ¿Cómo es que parece decir que Xuan Ji no estaba haciendo un buen trabajo antes?",
  ui_story_5070_50700701_59_dialog_content = "Un consejero clave abandona un puesto vital sin permiso, dejando solo una carta atrás.",
  ui_story_5070_50700701_60_dialog_content = "Una destacada y reconocida artesana abandona su taller y su multitud de maravillosos objetos, para viajar sola con solo un paraguas en la mano.",
  ui_story_5070_50700701_61_dialog_content = "¿Cómo explicaría la propiedad de eso, Ministra Armilla?",
  ui_story_5070_50700701_62_dialog_content = "Su Alteza...",
  ui_story_5070_50700701_63_dialog_content = "Su Alteza, estoy seguro de que Lady Xuan Ji tiene sus razones.",
  ui_story_5070_50700701_64_dialog_content = "...",
  ui_story_5070_50700701_65_dialog_content = "Vamos, no es tan complicado.",
  ui_story_5070_50700701_66_dialog_content = "Un borrador de diseño fue robado y mi escuela justo me pidió que recuperara un artefacto de Astra.",
  ui_story_5070_50700701_67_dialog_content = "Sucedió tan rápido que no tuve tiempo de despedirme correctamente.",
  ui_story_5070_50700701_68_dialog_content = "No sigues enojada porque me negué a enseñarte sobre dispositivos, ¿verdad, princesa?",
  ui_story_5070_50700701_69_dialog_content = "Yo también era joven e ignorante en ese entonces, así que ¿por qué no me perdona, Su Alteza?",
  ui_story_5070_50700701_70_dialog_content = "¿A qué te refieres con \"en ese entonces\"? No veo que eso cambie...",
  ui_story_5070_50700701_71_dialog_content = "Pff—Ah, lo siento.",
  ui_story_5070_50700701_72_dialog_content = "Es raro ver a Dantang con este tipo de expresión. Parece que estoy viendo un lado diferente al habitual.",
  ui_story_5070_50700701_73_dialog_content = "Vaya, tú también...",
  ui_story_5070_50700701_74_dialog_content = "Perdóname, por favor disculpa mi metedura de pata.",
  ui_story_5070_50700701_75_dialog_content = "Este no es el momento ni el lugar para que charle.",
  ui_story_5070_50700701_76_dialog_content = "La Ministra Armilla tiene asignadas las funciones de navegación...",
  ui_story_5070_50700701_77_dialog_content = "Pero como invitado, tomaste la iniciativa de explorar la superficie del océano, PlayerName.",
  ui_story_5070_50700701_78_dialog_content = "Ya me siento lo suficientemente avergonzado y culpable, mucho menos interrumpirlos a ambos.",
  ui_story_5070_50700701_79_dialog_content = "No te preocupes. Después de todo, puedo sentir la aproximación de los Eclipsites, así que aceptar esta tarea...",
  ui_story_5070_50700701_80_dialog_content = "¡Espera!",
  ui_story_5070_50700701_81_dialog_content = "Tal vez no desee entrometerse, princesa.",
  ui_story_5070_50700701_82_dialog_content = "Pero ciertas cosas allá afuera no son tan educadas como tú.",
  ui_story_5070_50700701_83_dialog_content = "Están llegando para molestar a PlayerName en este momento.",
  ui_story_5070_50700702_1_dialog_content = "Uf, ¡finalmente resuelto! No esperaba que aparecieran tantos Eclipsites de repente.",
  ui_story_5070_50700702_2_dialog_content = "Eso es un buen augurio, en realidad.",
  ui_story_5070_50700702_3_dialog_content = "¿¡Eclipsites activos son buenas noticias?!",
  ui_story_5070_50700702_4_dialog_content = "Eso significa que estamos lo suficientemente cerca de Astra donde los Eclipsites deambulan.",
  ui_story_5070_50700702_5_dialog_content = "Los instrumentos no mienten, pero no se puede decir lo mismo de nuestros ojos.",
  ui_story_5070_50700702_6_dialog_content = "Según los cálculos, deberíamos estar cerca de Astra, pero es difícil verificarlo en el vasto mar.",
  ui_story_5070_50700702_7_dialog_content = "Que se lancen hacia nosotros demuestra que estamos en el camino correcto.",
  ui_story_5070_50700702_8_dialog_content = "No solo se sacrificaron, sino que también me ofrecieron pruebas.",
  ui_story_5070_50700702_9_dialog_content = "Los maté con absoluta gratitud en mente.",
  ui_story_5070_50700702_10_dialog_content = "No tengo idea de cómo se sentirán esos Eclipsites cuando escuchen tus pensamientos...",
  ui_story_5070_50700702_11_dialog_content = "Ya que los cálculos son correctos, eso significa que Shadowind va en el rumbo correcto.",
  ui_story_5070_50700702_12_dialog_content = "El viento está empujando el barco desde el ángulo correcto, así que podemos ahorrar en combustible.",
  ui_story_5070_50700702_13_dialog_content = "¡Ponte a trabajar, Sun el Hábil!",
  ui_story_5070_50700702_14_dialog_content = "... Aunque eso es lo que dijo Lady Xuan Ji, debemos estar alerta ya que esos malvados espíritus simplemente no se rendirán.",
  ui_story_5070_50700702_15_dialog_content = "Su Alteza, por favor, manténgase cerca de mí.",
  ui_story_5070_50700702_16_dialog_content = "Los espíritus traviesos son mucho más comunes en Astra que en Longzhou.",
  ui_story_5070_50700702_17_dialog_content = "¿Espíritu maligno? Lo he escuchado antes, ¿es ese el término de Longzhou?",
  ui_story_5070_50700702_18_dialog_content = "En efecto. Las criaturas llamadas Eclipsites en Astra son conocidas como espíritus malvados en Longzhou.",
  ui_story_5070_50700702_19_dialog_content = "Sr. Zhong Xu...",
  ui_story_5070_50700702_20_dialog_content = "¿Está bien no descansar en la cabaña? Acabo de ver a Liqing gritando para que traigas medicina.",
  ui_story_5070_50700702_21_dialog_content = "Liqing siempre ha puesto todo su corazón en tratar a sus pacientes.",
  ui_story_5070_50700702_22_dialog_content = "Aunque ya no pueda caminar, aún puedo usar mi espada, así que estaré bien.",
  ui_story_5070_50700702_23_dialog_content = "...",
  ui_story_5070_50700702_24_dialog_content = "Zhong Xu... Señor.",
  ui_story_5070_50700702_25_dialog_content = "Princesa Dantang, no necesitas ser tan cuidadosa con un vagabundo como yo. Todos deberían relajarse un poco.",
  ui_story_5070_50700702_26_dialog_content = "Amigo joven, deberías descansar y dejarme a mí el deber de vigilar.",
  ui_story_5070_50700702_27_dialog_content = "¿Eh? No te preocupes por mí, como estas aguas son tan peligrosas, siempre es bueno tener más personas vigilando.",
  ui_story_5070_50700702_28_dialog_content = "Gracias por tu vigilancia. Las cosas mejorarán en la costa de Longzhou.",
  ui_story_5070_50700702_29_dialog_content = "Después de todo, esas criaturas de la oscuridad son mucho menos activas en Longzhou que en Astra.",
  ui_story_5070_50700702_30_dialog_content = "El imperio organiza regularmente un gran ritual para suprimir los espíritus malignos. Los reinos vasallos también tienen sus propias formas de lidiar con ellos.",
  ui_story_5070_50700702_31_dialog_content = "Los espíritus malvados generalmente se esconden en las montañas, apareciendo solo cuando su supervivencia está en riesgo para capturar a aquellos que viajan solos.",
  ui_story_5070_50700702_32_dialog_content = "Probablemente no estés al tanto de que los espíritus malignos en muchos lugares han estado inquietos en los últimos meses.",
  ui_story_5070_50700702_33_dialog_content = "Las incursiones contra civiles están ocurriendo con mayor frecuencia. Algunos de estos monstruos incluso infiltraron ciudades y causaron estragos.",
  ui_story_5070_50700702_34_dialog_content = "Las defensas de los diversos estados respondieron incansablemente, pero en vano.",
  ui_story_5070_50700702_35_dialog_content = "Ahora, la gente vive con miedo, sin saber si es el Fiendling u otros elementos...",
  ui_story_5070_50700702_36_dialog_content = "¿No te gustan los Fiendlings?",
  ui_story_5070_50700702_37_dialog_content = "¿Qué? No, solo estoy preocupado, eso es todo...",
  ui_story_5070_50700702_38_dialog_content = "Espera, ¿qué es un diablillo?",
  ui_story_5070_50700702_39_dialog_content = "Creciste en Astra, así que el nombre te resulta desconocido. Son similares a los semihumanos de Astra.",
  ui_story_5070_50700702_40_dialog_content = "La única diferencia es que los demi-humanos tienen naturalmente características animales.",
  ui_story_5070_50700702_41_dialog_content = "Mientras que los Fiendlings obtuvieron sus formas de demi-humanos después de aprender las Artes de la Fuerza.",
  ui_story_5070_50700702_42_dialog_content = "A algunos les disgustan los Fiendlings, pero a otros les gustan debido a sus habilidades y lo que representan.",
  ui_story_5070_50700702_43_dialog_content = "Por ejemplo, la gente marinera está ansiosa por abrir sus puertas a cualquier Fiendling con forma de pez dócil que aparezca.",
  ui_story_5070_50700702_44_dialog_content = "... Aunque he tenido muchas aventuras en el mar, no me llevo bien con los peces, así que nunca recibiré sus bendiciones.",
  ui_story_5070_50700702_45_dialog_content = "Los peces grandes son peligrosos, así que espero que no nos encontremos con ninguno.",
  ui_story_5070_50700702_46_dialog_content = "Lo tengo.",
  ui_story_5070_50700702_47_dialog_content = "Es como en Astra, donde algunas personas creen que ciertos animales traen buena suerte, mientras que otros presagian la perdición.",
  ui_story_5070_50700702_48_dialog_content = "Exactamente, pero la afirmación de que los diabólicos otorgan bendiciones no es completamente infundada.",
  ui_story_5070_50700702_49_dialog_content = "En el pasado, algunos Fiendlings han protegido activamente la paz en ciertas áreas después de perfeccionar sus formas semihumanas.",
  ui_story_5070_50700702_50_dialog_content = "Incluso la corte imperial estaba dispuesta a reconocerlos con edictos imperiales y permitió que la gente construyera templos para adorarlos.",
  ui_story_5070_50700702_51_dialog_content = "Vaya, no sé si tendré la oportunidad de ver a estos Fiendlings.",
  ui_story_5070_50700702_52_dialog_content = "Sabes mucho sobre esto, Zhong Xu.",
  ui_story_5070_50700702_53_dialog_content = "Ya sea desterrando demonios o realizando rituales...",
  ui_story_5070_50700702_54_dialog_content = "Nadie a bordo puede igualarlo en términos de conocimiento y experiencia.",
  ui_story_5070_50700702_55_dialog_content = "Puedes preguntarle al Señor Zhong Xu si deseas saber algo más, PlayerName.",
  ui_story_5070_50700702_56_dialog_content = "Solo espero que los espíritus malvados en el mar actúen lentamente para darnos tiempo de coordinar.",
  ui_story_5070_50700702_57_dialog_content = "(Lástima que los Eclipsites no fueran tan inteligentes, ya que nos llevó varias batallas más antes de que finalmente pudiéramos pasar por la zona.)",
  ui_story_5070_50700702_58_dialog_content = "(No me había dado cuenta todavía.)",
  ui_story_5070_50700702_59_dialog_content = "(Pero los Eclipsites estaban lejos de ser los únicos peligros en el océano.)",
  ui_story_5070_50700801_1_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5070_50700801_2_dialog_content = "<color=#e8d9bb>¡Chapoteo—!</color>",
  ui_story_5070_50700801_3_dialog_content = "¡PlayerName! ¡PlayerName! ¡Despierta!",
  ui_story_5070_50700801_4_dialog_content = "Eh... Xuan Ji?",
  ui_story_5070_50700801_5_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700801_6_dialog_content = "Vaya... ¿Qué pasa?",
  ui_story_5070_50700801_7_dialog_content = "¡El fuego se propaga rápido! ¡Rápido, trae esas bolsas de agua aquí!",
  ui_story_5070_50700801_8_dialog_content = "¡Ugh! ¡La evacuación no está terminada! ¡Deja de empujar! ¡No te apretujes en la cabina!",
  ui_story_5070_50700801_9_dialog_content = "¡Cállate! Protege la bóveda de combustible; si se quema aquí, ¡estamos acabados!",
  ui_story_5070_50700801_10_dialog_content = "Vaya alboroto... ¿Qué está pasando en el barco?",
  ui_story_5070_50700801_11_dialog_content = "Entramos al mar lejano hace no mucho tiempo, donde el clima se volvía cada vez más impredecible.",
  ui_story_5070_50700801_12_dialog_content = "La suerte tampoco está de nuestro lado. Sacamos la pajita más corta posible.",
  ui_story_5070_50700801_13_dialog_content = "—Tormenta eléctrica.",
  ui_story_5070_50700801_14_dialog_content = "Podíamos manejar tormentas comunes sin problema, pero un rayo acaba de golpear el barco y causó una explosión.",
  ui_story_5070_50700801_15_dialog_content = "Ahora tenemos lucha contra incendios y evacuaciones en marcha.",
  ui_story_5070_50700801_16_dialog_content = "¿Rayos, explosiones?",
  ui_story_5070_50700801_17_dialog_content = "¿No revisamos la protección contra rayos e incendios antes de irnos? ¿Cómo es esto posible?",
  ui_story_5070_50700801_18_dialog_content = "Solo son efectivos contra incendios naturales.",
  ui_story_5070_50700801_19_dialog_content = "El problema es que ese podría no ser el único problema que tenemos.",
  ui_story_5070_50700801_20_dialog_content = "¿Ah?",
  ui_story_5070_50700801_21_dialog_content = "Este no es el momento para explicar, y de todos modos, tampoco sé exactamente qué está pasando con los rayos y el fuego.",
  ui_story_5070_50700801_22_dialog_content = "¿Puedo ayudar en algo?",
  ui_story_5070_50700801_23_dialog_content = "Bueno, la idea era llevarte a un lugar seguro, pero ahora te has convertido en un par de manos extra para ayudar.",
  ui_story_5070_50700801_24_dialog_content = "Entonces te ponemos a trabajar.",
  ui_story_5070_50700801_25_dialog_content = "Sígueme.",
  ui_story_5070_50700801_26_dialog_content = "¿Por qué el fuego aún no está controlado? ¿Qué están haciendo todos ustedes?!",
  ui_story_5070_50700801_27_dialog_content = "¡Inténtalo tú mismo! ¡Ya estamos arriesgando nuestras vidas para evitar que el fuego se propague hacia afuera!",
  ui_story_5070_50700801_28_dialog_content = "¡Maldita sea, por qué empieza el fuego desde abajo? La cabaña es toda de madera; ¡no aguantará!",
  ui_story_5070_50700801_29_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700801_30_dialog_content = "<color=#e8d9bb>Esta vez, la fuerte explosión está justo adelante; ¡la puerta de la cabina delantera se abre de golpe, con llamas irrumpiendo!</color>",
  ui_story_5070_50700801_31_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5070_50700801_32_dialog_content = "<color=#e8d9bb>El trozo de madera ardiente se detiene a solo centímetros del constructor de barcos, rompiéndose en múltiples fragmentos en el aire.</color>",
  ui_story_5070_50700801_33_dialog_content = "Tanto el fuego como el agua son despiadados. Lo último que debes hacer cuando ocurre algo inesperado es entrar en pánico.",
  ui_story_5070_50700801_34_dialog_content = "Está bien tener miedo, pero no dejes que tus compañeros paguen el precio de tu temor.",
  ui_story_5070_50700801_35_dialog_content = "Sr. Zhong Xu! ¡G-Gracias, señor, por salvarnos!",
  ui_story_5070_50700801_36_dialog_content = "La verdad es que no puedo manejar los problemas de este barco solo. Necesito su apoyo, señor.",
  ui_story_5070_50700801_37_dialog_content = "Por favor, díganos, ¿qué debemos hacer ahora?",
  ui_story_5070_50700801_38_dialog_content = "En este barco, deberías seguir las órdenes del capitán, no las mías.",
  ui_story_5070_50700801_39_dialog_content = "Sr. Zhong Xu, gracias por ayudarnos.",
  ui_story_5070_50700801_40_dialog_content = "Capitán, lamento hacerte lidiar con nuestros problemas mientras diriges el barco...",
  ui_story_5070_50700801_41_dialog_content = "No digas más. Un capitán que no asume las mayores responsabilidades en el barco no es un capitán digno.",
  ui_story_5070_50700801_42_dialog_content = "He revisado el estado del barco. Deberíamos poder detener este incendio si actuamos ahora.",
  ui_story_5070_50700801_43_dialog_content = "¡Sí!",
  ui_story_5070_50700801_44_dialog_content = "La tormenta sigue siendo feroz... Dr. Liqing, por favor lleve a los evacuados más lejos!",
  ui_story_5070_50700801_45_dialog_content = "Todos los demás deben preparar bolsas de lino y romper objetos en llamas con ganchos para fuego.",
  ui_story_5070_50700801_46_dialog_content = "Los refuerzos llegarán más tarde.",
  ui_story_5070_50700801_47_dialog_content = "*Tose* El aire aquí se está calentando. No podremos quedarnos mucho más tiempo.",
  ui_story_5070_50700801_48_dialog_content = "He traído algunas otras cosas, Xuan Ji. ¿Hay algo que podamos usar?",
  ui_story_5070_50700801_49_dialog_content = "La madera de la que está hecha la cabina no será lo suficientemente resistente, dada la presión del agua...",
  ui_story_5070_50700801_50_dialog_content = "Xuan Ji?",
  ui_story_5070_50700801_51_dialog_content = "De vuelta con las cosas tan rápido, PlayerName?",
  ui_story_5070_50700801_52_dialog_content = "En realidad, hace bastante tiempo, pero estabas tan concentrado que no te diste cuenta.",
  ui_story_5070_50700801_53_dialog_content = "Aunque me pediste que encontrara materiales útiles...",
  ui_story_5070_50700801_54_dialog_content = "Todo lo que pude encontrar cerca eran cajas vacías y piezas descartadas.",
  ui_story_5070_50700801_55_dialog_content = "¿De verdad crees que podemos hacer algo para apagar el fuego con solo estas cosas?",
  ui_story_5070_50700801_56_dialog_content = "Tendremos que hacerlo. El incendio bloqueó el pasaje hacia la bodega, así que eso nos deja la improvisación como única opción.",
  ui_story_5070_50700801_57_dialog_content = "Pero para los artesanos, no es necesario utilizar componentes predeterminados o los mejores.",
  ui_story_5070_50700801_58_dialog_content = "Podemos endurecer la madera con un revestimiento, reemplazar los clavos faltantes con mortaja y espiga, y modificar la estructura para hacer todo más fuerte.",
  ui_story_5070_50700801_59_dialog_content = "Combina todo lo que hemos visto y aprendido para crear lo que necesites.",
  ui_story_5070_50700801_60_dialog_content = "La adaptación flexible es la verdadera esencia de la tecnología.",
  ui_story_5070_50700801_61_dialog_content = "¡Listo! Ahora podemos ir a ayudar.",
  ui_story_5070_50700801_62_dialog_content = "¡Capitán! El fuego de arriba finalmente está bajo control, pero dentro de la cabina...",
  ui_story_5070_50700801_63_dialog_content = "Está bien.",
  ui_story_5070_50700801_64_dialog_content = "Lamento hacerte esperar—",
  ui_story_5070_50700801_65_dialog_content = "Tomó un tiempo armar algo improvisado, ¡pero la satisfacción está garantizada!",
  ui_story_5070_50700801_66_dialog_content = "Lady Xuan Ji, ¿qué es esta... cosa?",
  ui_story_5070_50700801_67_dialog_content = "Puedes encender eso ahora, PlayerName.",
  ui_story_5070_50700801_68_dialog_content = "¡Está bien!",
  ui_story_5070_50700801_69_dialog_content = "<color=#e8d9bb>Snap, snap.</color>",
  ui_story_5070_50700801_70_dialog_content = "<color=#e8d9bb>Las tiras de madera y las placas de metal, antes dispersas y sueltas, se retuercen, unen y encajan espontáneamente.</color>",
  ui_story_5070_50700801_71_dialog_content = "<color=#e8d9bb>Con un extremo colgando en el agua de mar desde el costado del barco y el otro en la cubierta, se asemeja a un dragón mecánico que se levanta orgulloso del mar.</color>",
  ui_story_5070_50700801_72_dialog_content = "Aunque esté hecho de tiras de caja y piezas desechadas, sigue siendo suficiente para apagar el fuego.",
  ui_story_5070_50700801_73_dialog_content = "¡Lo llamaremos el Dragón de Agua!",
  ui_story_5070_50700801_74_dialog_content = "<color=#e8d9bb>Potentes chorros de agua salen de la boca del dragón y el humo blanco se arremolina en la cabina, apagando las llamas feroces en grandes áreas.</color>",
  ui_story_5070_50700801_75_dialog_content = "No te quedes ahí parado. Muévete ya.",
  ui_story_5070_50700801_76_dialog_content = "Xuan Ji, tú estás a cargo aquí.",
  ui_story_5070_50700801_77_dialog_content = "¡No te decepcionaré!",
  ui_story_5070_50700801_78_dialog_content = "Especialmente con PlayerName aquí también... ¿PlayerName?",
  ui_story_5070_50700801_79_dialog_content = "Tengo una sensación graciosa.",
  ui_story_5070_50700801_80_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700801_81_dialog_content = "<color=#e8d9bb>Las llamas previamente sofocadas vuelven a encenderse.</color>",
  ui_story_5070_50700801_82_dialog_content = "No, esto nunca va a terminar.",
  ui_story_5070_50700801_83_dialog_content = "Usaré mi habilidad psíquica para encontrar el origen de la explosión. Tal vez pueda encontrar una solución también.",
  ui_story_5070_50700801_84_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700801_85_dialog_content = "(No aquí. Necesito seguir bajando.)",
  ui_story_5070_50700801_86_dialog_content = "(La fuente es... ¿El sostén? ¿Qué hay ahí...?)",
  ui_story_5070_50700801_87_dialog_content = "¡Whoa!",
  ui_story_5070_50700801_88_dialog_content = "<size=45>¡Graaah!!</size>",
  ui_story_5070_50700801_89_dialog_content = "<color=#e8d9bb>La cubierta de abajo es golpeada por la bestia mecánica, abriéndose y revelando un mar de llamas debajo.</color>",
  ui_story_5070_50700801_90_dialog_content = "¡PlayerName!",
  ui_story_5070_50700801_91_dialog_content = "(¡Cayó adentro—!)",
  ui_story_5070_50700801_92_dialog_content = "¡A cenizas!",
  ui_story_5070_50700801_93_dialog_content = "!",
  ui_story_5070_50700801_94_dialog_content = "Ay... Mi espalda realmente duele. Pero...",
  ui_story_5070_50700801_95_dialog_content = "Claramente he caído justo donde comenzó el fuego, pero ¿cómo es que las llamas no están ni un poco calientes?",
  ui_story_5070_50700801_96_dialog_content = "Joven amigo, ¿cómo están tus heridas?",
  ui_story_5070_50700801_97_dialog_content = "Zhong Xu?! ¿Por qué me seguiste hasta aquí?! Es demasiado peligroso. ¿Estás bien...?",
  ui_story_5070_50700801_98_dialog_content = "Afortunadamente, la Ministra Armilla modificó mi silla de ruedas. Sigue estando bien después de recibir ese impacto.",
  ui_story_5070_50700801_99_dialog_content = "Esa no es la pregunta...",
  ui_story_5070_50700801_100_dialog_content = "También soy bastante hábil en las Artes de la Fuerza de la Llama y puedo controlar el fuego descontrolado en este barco.",
  ui_story_5070_50700801_101_dialog_content = "No te quemarás con las llamas en absoluto.",
  ui_story_5070_50700801_102_dialog_content = "¡Increíble! ¿No significa esto que puedes moverte libremente en el fuego?",
  ui_story_5070_50700801_103_dialog_content = "Por cierto, este lugar está cerca de la bodega. ¡Con la habilidad de Zhong Xu, incluso podríamos lidiar directamente con la fuente del fuego!",
  ui_story_5070_50700801_104_dialog_content = "Un momento.",
  ui_story_5070_50700801_105_dialog_content = "Tienes algunos poderes especiales, pero te falta condición física. Deberías ir a un lugar seguro primero.",
  ui_story_5070_50700801_106_dialog_content = "¿Cómo podría dejar pasar una oportunidad tan inesperada?",
  ui_story_5070_50700801_107_dialog_content = "Esa no es tu responsabilidad.",
  ui_story_5070_50700801_108_dialog_content = "Como enviada de otra tierra, eres muy importante y debes valorar tu propia seguridad primero. Nadie te criticará duramente por hacer eso.",
  ui_story_5070_50700801_109_dialog_content = "No hay necesidad de ponerte en peligro.",
  ui_story_5070_50700801_110_dialog_content = "Sé que solo te preocupas por mí, pero si siempre te preocupas por cosas que aún no han sucedido...",
  ui_story_5070_50700801_111_dialog_content = "¿Alguna vez podrías lograr algo?",
  ui_story_5070_50700801_112_dialog_content = "Además, el Zhong Xu que acaba de saltar conmigo dijo esto... ¿No es un poco poco convincente?",
  ui_story_5070_50700801_113_dialog_content = "Zhong Xu no es responsable de salvarme, ¿verdad?",
  ui_story_5070_50700801_114_dialog_content = "...",
  ui_story_5070_50700801_115_dialog_content = "Jajaja, haces un buen punto.",
  ui_story_5070_50700801_116_dialog_content = "Nunca pensé que estaría diciéndole a alguien más que tenga cuidado.",
  ui_story_5070_50700801_117_dialog_content = "Eres una persona bastante increíble.",
  ui_story_5070_50700801_118_dialog_content = "Vamos juntos.",
  ui_story_5070_50700801_119_dialog_content = "Confirmaré la ubicación del origen del fuego.",
  ui_story_5070_50700801_120_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700801_121_dialog_content = "Espera, hay algo extraño en esta fuente de fuego. Y...",
  ui_story_5070_50700801_122_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700801_123_dialog_content = "<size=45>¡Cuidado!</size>",
  ui_story_5070_50700801_124_dialog_content = "<color=#e8d9bb>Una repentina ráfaga de llamas envuelve todo.</color>",
  ui_story_5070_50700802_1_dialog_content = "*Tos* *tos*... Hay humo por todas partes.",
  ui_story_5070_50700802_2_dialog_content = "Apenas puedo respirar y me cuesta concentrarme... pero juro que sentí a alguien aquí hace un momento...",
  ui_story_5070_50700802_3_dialog_content = "...",
  ui_story_5070_50700802_4_dialog_content = "*Tose* ¿Quién eres...?",
  ui_story_5070_50700802_5_dialog_content = "<color=#e8d9bb>Un peculiar destello de luz blanca pasa en medio del humo.</color>",
  ui_story_5070_50700802_6_dialog_content = "¡Joven amigo!",
  ui_story_5070_50700802_7_dialog_content = "Zhong Xu... *tos*...",
  ui_story_5070_50700802_8_dialog_content = "¡Dame tu mano!",
  ui_story_5070_50700802_9_dialog_content = "Espera, por ahí...",
  ui_story_5070_50700802_10_dialog_content = "<color=#e8d9bb>Una bola de fuego explota al frente.</color>",
  ui_story_5070_50700802_11_dialog_content = "Salgamos de aquí primero.",
  ui_story_5070_50700802_12_dialog_content = "¿Cómo está PlayerName, Sr. Zhong Xu? ¿Está bien?",
  ui_story_5070_50700802_13_dialog_content = "¡Oye! ¡Fuera del camino! ¡Todos ustedes!",
  ui_story_5070_50700802_14_dialog_content = "¡Dejen pasar al médico!",
  ui_story_5070_50700901_1_dialog_content = "Urgh...",
  ui_story_5070_50700901_2_dialog_content = "¡Miau!",
  ui_story_5070_50700901_3_dialog_content = "... ¿Por qué hay un gato en mi cama?",
  ui_story_5070_50700901_4_dialog_content = "¿No eres ese gato que siempre está cerca del Doctor Liqing... Tinytail, verdad?",
  ui_story_5070_50700901_5_dialog_content = "¡Miau!",
  ui_story_5070_50700901_6_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_5070_50700901_7_dialog_content = "Oh sí, tengo que preguntar sobre el incendio de ayer... ¿Todos están bien?!",
  ui_story_5070_50700901_8_dialog_content = "¡Miau! ¡Miau!",
  ui_story_5070_50700901_9_dialog_content = "Oye... Apártate, Tinytail. Eso es peligroso.",
  ui_story_5070_50700901_10_dialog_content = "Oh, fui a buscar unas hierbas y ¿ya estás despierto?",
  ui_story_5070_50700901_11_dialog_content = "Acuéstate en este instante.",
  ui_story_5070_50700901_12_dialog_content = "Miau...",
  ui_story_5070_50700901_13_dialog_content = "¡Bien hecho, Tinytail!",
  ui_story_5070_50700901_14_dialog_content = "Sabía que PlayerName sería un paciente difícil como Zhong Xu.",
  ui_story_5070_50700901_15_dialog_content = "¿De verdad fuiste tú quien hizo que Tinytail se interpusiera en mi camino?",
  ui_story_5070_50700901_16_dialog_content = "Por supuesto, no subestimes ese humo que te ahogó.",
  ui_story_5070_50700901_17_dialog_content = "Estarías en serios problemas si el humo venenoso entrara en tus pulmones.",
  ui_story_5070_50700901_18_dialog_content = "Acuéstate y espera.",
  ui_story_5070_50700901_19_dialog_content = "4.5g de fritillaria, 3g de trichosanthes y 2.4g de polen, wolfiporia, mandarina y platycodon cada uno.",
  ui_story_5070_50700901_20_dialog_content = "¿Qué es esto?",
  ui_story_5070_50700901_21_dialog_content = "Es la receta de un antiinflamatorio que desintoxicará tus pulmones.",
  ui_story_5070_50700901_22_dialog_content = "No olvides aumentar tu consumo de agua, descansar más y respirar más aire fresco. En cuanto a tu comida, come ligero.",
  ui_story_5070_50700901_23_dialog_content = "Ven a verme de inmediato si experimentas tos, flema o congestión en el pecho. ¿Entendido?",
  ui_story_5070_50700901_24_dialog_content = "¿Por qué me miras así?",
  ui_story_5070_50700901_25_dialog_content = "Liqing parece bastante confiable en este momento.",
  ui_story_5070_50700901_26_dialog_content = "Básicamente, es como... ¿Cómo se diría en Longzhou? ¡Estilo de médico poderoso!",
  ui_story_5070_50700901_27_dialog_content = "¿En serio?! Ejem... Digo, ¿no es eso lo esperado?",
  ui_story_5070_50700901_28_dialog_content = "Está bien, aquí está tu medicina. Tómala mientras aún está caliente.",
  ui_story_5070_50700901_29_dialog_content = "Tss... B-bastante un sabor complejo.",
  ui_story_5070_50700901_30_dialog_content = "El Maestro Bu dice: \"La buena medicina es amarga. Es el precio que pagas por la recuperación.\"",
  ui_story_5070_50700901_31_dialog_content = "... ¿En realidad es tan malo?",
  ui_story_5070_50700901_32_dialog_content = "No es exactamente desagradable, es solo la primera vez que pruebo algo tan complejo...",
  ui_story_5070_50700901_33_dialog_content = "No estoy realmente acostumbrado",
  ui_story_5070_50700901_34_dialog_content = "¿Qué voy a hacer con ustedes, jóvenes?",
  ui_story_5070_50700901_35_dialog_content = "Aquí, toma esta fruta confitada. Te ayudará después de tomar tu medicina.",
  ui_story_5070_50700901_36_dialog_content = "Pero solo obtendrás este. Solo logré esconder una bolsa mientras abordaba el barco.",
  ui_story_5070_50700901_37_dialog_content = "Gracias, Liqing. Eso es muy considerado de tu parte.",
  ui_story_5070_50700901_38_dialog_content = "No se puede evitar, ¡después de todo soy un gran médico!",
  ui_story_5070_50700901_39_dialog_content = "Descansa bien. Tengo que ver a los demás.",
  ui_story_5070_50700901_40_dialog_content = "¿Hay alguien más herido?",
  ui_story_5070_50700901_41_dialog_content = "Mantente abajo. Tu condición fue la más grave ayer, así que olvídate de los demás.",
  ui_story_5070_50700901_42_dialog_content = "No te preocupes, estará bien.",
  ui_story_5070_50700901_43_dialog_content = "Tengo que darle a todos un poco de medicina refrescante y desintoxicante como precaución.",
  ui_story_5070_50700901_44_dialog_content = "Hablando de los demás...",
  ui_story_5070_50700901_45_dialog_content = "Muchos vinieron a visitar mientras dormías. Ahora que estás despierto, puedo llamarlos a todos.",
  ui_story_5070_50700901_46_dialog_content = "No, no, no. Sé que todos están bien, así que no hay necesidad de preocuparse...",
  ui_story_5070_50700901_47_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700901_48_dialog_content = "¡No es necesario ser formal!",
  ui_story_5070_50700901_49_dialog_content = "*Jadeo*",
  ui_story_5070_50700901_50_dialog_content = "Dantang¿?",
  ui_story_5070_50700901_51_dialog_content = "Lady Xuan Ji, por favor no presione a Su Alteza de esa manera.",
  ui_story_5070_50700901_52_dialog_content = "¿No eres un poco sobreprotector, Jiu? Relájate, Su Alteza es preciosa, pero tampoco es frágil.",
  ui_story_5070_50700901_53_dialog_content = "Xuan Ji? Jiu? ¿Por qué están todos aquí?",
  ui_story_5070_50700901_54_dialog_content = "Para ver al héroe de ayer, por supuesto.",
  ui_story_5070_50700901_55_dialog_content = "Me alegra que no hayas resultado gravemente herido, o no sabría cómo compensarte.",
  ui_story_5070_50700901_56_dialog_content = "No tienes motivo para disculparte. Nadie hubiera pensado que cometería un desliz en ese momento.",
  ui_story_5070_50700901_57_dialog_content = "Y todos están bien, lo que demuestra que tu invento tuvo éxito en apagar el fuego...",
  ui_story_5070_50700901_58_dialog_content = "Bueno, estás lo suficientemente sano como para ser extenso, así que debes estar bien.",
  ui_story_5070_50700901_59_dialog_content = "Entonces, ¿cómo se siente al ver la recuperación de PlayerName en persona, Princesa Dantang?",
  ui_story_5070_50700901_60_dialog_content = "Mucho mejor que husmear, ¿verdad?",
  ui_story_5070_50700901_61_dialog_content = "Debes haber confundido a alguien más conmigo, Ministra Armilla.",
  ui_story_5070_50700901_62_dialog_content = "Es mi deber preocuparme por la salud de un enviado importante como PlayerName.",
  ui_story_5070_50700901_63_dialog_content = "No tengo necesidad de, como dijiste, fisgonear.",
  ui_story_5070_50700901_64_dialog_content = "Sí, sí, creo que todo ese humo de ayer todavía está afectando mis ojos.",
  ui_story_5070_50700901_65_dialog_content = "Entonces te dejaré cumplir con tu deber, Princesa Dantang. ¡Por favor continúa preocupándote por PlayerName!",
  ui_story_5070_50700901_66_dialog_content = "Yo...",
  ui_story_5070_50700901_67_dialog_content = "Está bien, Dantang. Estoy perfectamente saludable ahora y no hay nada de qué preocuparse.",
  ui_story_5070_50700901_68_dialog_content = "No hay nada que me moleste tampoco, um... Excepto por ese olor a medicina. Realmente es algo...",
  ui_story_5070_50700901_69_dialog_content = "¿Medicina? Sí, tengo una solución para eso.",
  ui_story_5070_50700901_70_dialog_content = "Cuando estés fuera de peligro inmediato, sanar a través de la comida es la opción superior.",
  ui_story_5070_50700901_71_dialog_content = "Dado que Liqing también está presente, me gustaría preparar una deliciosa comida medicinal para todos. ¿Qué te parece la idea?",
  ui_story_5070_50700901_72_dialog_content = "¡Hacerlo sabroso?! ¡No hay problema!",
  ui_story_5070_50700901_73_dialog_content = "Conozco la receta de muchos tónicos e incluso compré ingredientes especialmente para este viaje.",
  ui_story_5070_50700901_74_dialog_content = "La raíz de loto promueve la salud, el melón de invierno nutre la piel, la wolfiporia nutre la mente...",
  ui_story_5070_50700901_75_dialog_content = "¡Puedo hacer tantas cosas!",
  ui_story_5070_50700901_76_dialog_content = "...",
  ui_story_5070_50700901_77_dialog_content = "¿No viene Xuan Ji a comer algo...? ¿Xuan Ji?",
  ui_story_5070_50700901_78_dialog_content = "¿Sí? ¿Algo en lo que pueda ayudar?",
  ui_story_5070_50700901_79_dialog_content = "Nope. Pareces un poco distraído y no has dicho nada desde hace un rato.",
  ui_story_5070_50700901_80_dialog_content = "¿Es tan obvio?",
  ui_story_5070_50700901_81_dialog_content = "Supongo que aún tengo que trabajar en mi compostura. Nota para mí: Hacer una máscara que pueda ayudar a mantener la expresión facial deseada.",
  ui_story_5070_50700901_82_dialog_content = "En realidad, he estado pensando en anoche.",
  ui_story_5070_50700901_83_dialog_content = "Cuando el Sr. Zhong Xu te sacó del humo...",
  ui_story_5070_50700901_84_dialog_content = "Seguías murmurando sobre incendios y figuras.",
  ui_story_5070_50700901_85_dialog_content = "¿Qué viste?",
  ui_story_5070_50700901_86_dialog_content = "No es realmente ver per se, más bien es sentir.",
  ui_story_5070_50700901_87_dialog_content = "Parecía haber algo realmente extraño en la bodega, como fuego, pero no podía sentir el calor que las llamas deberían emitir.",
  ui_story_5070_50700901_88_dialog_content = "No tenía calor, pero aún así parecía más sustancial que todas las llamas circundantes juntas.",
  ui_story_5070_50700901_89_dialog_content = "Era como... Un sol en miniatura.",
  ui_story_5070_50700901_90_dialog_content = "... Sé que mi descripción es un poco extraña.",
  ui_story_5070_50700901_91_dialog_content = "De todos modos, sospecho que el rayo fue solo el catalizador, y esto fue la verdadera causa del incendio.",
  ui_story_5070_50700901_92_dialog_content = "En cuanto a la figura, no pude verla lo suficientemente bien, pero se mantuvo cerca de la bodega todo el tiempo...",
  ui_story_5070_50700901_93_dialog_content = "Todo es un poco raro.",
  ui_story_5070_50700901_94_dialog_content = "Entiendo.",
  ui_story_5070_50700901_95_dialog_content = "Pero controlemos el impulso la próxima vez, PlayerName.",
  ui_story_5070_50700901_96_dialog_content = "Detén el escaneo mental de cualquier cosa inusual que hayas detectado...",
  ui_story_5070_50700901_97_dialog_content = "No puedo sacarte de peligro todo el tiempo, incluso si quisiera.",
  ui_story_5070_50700901_98_dialog_content = "Lo siento... prestaré atención.",
  ui_story_5070_50700901_99_dialog_content = "Bueno, tengo que correr ahora.",
  ui_story_5070_50700901_100_dialog_content = "Espera.",
  ui_story_5070_50700901_101_dialog_content = "¿Pasó algo más malo mientras dormía?",
  ui_story_5070_50700901_102_dialog_content = "...",
  ui_story_5070_50700901_103_dialog_content = "Bueno, supongo que realmente tengo que hacer que la máscara de expresión sea una agenda.",
  ui_story_5070_50700901_104_dialog_content = "Suponiendo que regrese a mi taller en Longzhou.",
  ui_story_5070_50700901_105_dialog_content = "¿Hay algo malo con el viaje?",
  ui_story_5070_50700901_106_dialog_content = "Hay un dicho en la navegación:",
  ui_story_5070_50700901_X106_dialog_content = "\"Navega por las estrellas de noche, el sol de día, la penumbra con brújula y sal del área lo más pronto posible cuando nada de eso funcione.\"",
  ui_story_5070_50700901_107_dialog_content = "¿Observar estrellas y sol? ¿Te refieres a determinar la dirección de un barco por las estrellas, como antes de Xuan Ji?",
  ui_story_5070_50700901_108_dialog_content = "Exacto. Si no hay estrellas ni luna, aún tienes una brújula para guiarte en la dirección correcta.",
  ui_story_5070_50700901_109_dialog_content = "Pero si incluso los instrumentos fallan, no tienes forma de saber a dónde vas.",
  ui_story_5070_50700901_110_dialog_content = "Si no sales pronto, te perderás en el mar.",
  ui_story_5070_50700901_111_dialog_content = "Después del alboroto de anoche, intenté de todo para orientarnos en la tormenta.",
  ui_story_5070_50700901_112_dialog_content = "...¿Nada es efectivo?",
  ui_story_5070_50700901_113_dialog_content = "<color=#e8d9bb>Xuan Ji asiente levemente.</color>",
  ui_story_5070_50700901_114_dialog_content = "Nada ha funcionado, incluso ahora.",
  ui_story_5070_50700901_115_dialog_content = "Eso no le pasaría al Shadowind en un viaje normal.",
  ui_story_5070_50700901_116_dialog_content = "Pero estamos tan lejos y sin un mapa completo, que ni siquiera podemos confiar en el sol cuando sale.",
  ui_story_5070_50700901_117_dialog_content = "Entonces, estoy bastante seguro en este mismo momento...",
  ui_story_5070_50700901_118_dialog_content = "El Shadowind se desvió del curso.",
  ui_story_5070_50700902_1_dialog_content = "Estamos perdidos y aún tenemos que lidiar con los Eclipsites... El viaje ha sido muy movido.",
  ui_story_5070_50700902_2_dialog_content = "Tenemos que orientarnos lo más pronto posible.",
  ui_story_5070_50700902_3_dialog_content = "Entiendo el razonamiento, pero ¿cuál es la conexión con mover la Trampa del Dragón de Agua?",
  ui_story_5070_50700902_4_dialog_content = "Le dábamos un propósito a cada dispositivo que fabricábamos, pero eso no significaba que fuera lo único para lo que servían.",
  ui_story_5070_50700902_5_dialog_content = "<color=#e8d9bb>Con un estruendo atronador, el agua de mar es bombeada en barriles de madera previamente preparados a través de tuberías de latón.</color>",
  ui_story_5070_50700902_6_dialog_content = "Mira, además de agua de mar, también atrapamos un montón de peces y camarones.",
  ui_story_5070_50700902_7_dialog_content = "El mar puede ser grande, pero tiene diferentes criaturas viviendo en distintas partes.",
  ui_story_5070_50700902_8_dialog_content = "Entonces, si podemos atrapar algunos animales marinos icónicos de la región...",
  ui_story_5070_50700902_9_dialog_content = "Deberíamos obtener una pista educada sobre dónde estamos aproximadamente comparándolas con las imágenes en la guía.",
  ui_story_5070_50700902_10_dialog_content = "Entonces, incluso este ángulo puede ser considerado.",
  ui_story_5070_50700902_11_dialog_content = "¿Atrapaste algo especial?",
  ui_story_5070_50700902_12_dialog_content = "Lamentablemente, solo eran criaturas simples, buenas solo para las comidas medicinales que la princesa quería preparar.",
  ui_story_5070_50700902_13_dialog_content = "Aunque hay que aclarar que hay riesgos involucrados en esto.",
  ui_story_5070_50700902_14_dialog_content = "Los marineros nos pescan todos los días, ¿cuál es el riesgo?",
  ui_story_5070_50700902_15_dialog_content = "En realidad, solo mencioné la mitad.",
  ui_story_5070_50700902_16_dialog_content = "Aunque los dispositivos se pueden adaptar para muchas cosas, no fueron diseñados para eso.",
  ui_story_5070_50700902_17_dialog_content = "Entonces, es posible que algo inesperado suceda...",
  ui_story_5070_50700902_18_dialog_content = "Toma el Cangrejo de Fuego, por ejemplo. Es excelente para soldar.",
  ui_story_5070_50700902_19_dialog_content = "Pero terrible para asar carne.",
  ui_story_5070_50700902_20_dialog_content = "¿Tienes idea de lo desagradable que sabe la carne carbonizada?",
  ui_story_5070_50700902_21_dialog_content = "Preferiría no saberlo. Nunca.",
  ui_story_5070_50700902_22_dialog_content = "¿Y exactamente cuándo usarías cangrejos de fuego para cocinar?",
  ui_story_5070_50700902_23_dialog_content = "Muy similar a usar una bomba para atrapar peces en este momento.",
  ui_story_5070_50700902_24_dialog_content = "Es una emergencia grave.",
  ui_story_5070_50700902_25_dialog_content = "Aunque no estoy muy familiarizado con los dichos de Longzhou.",
  ui_story_5070_50700902_26_dialog_content = "Pero algo me dice que asar cangrejos con fuego no encaja con la palabra.",
  ui_story_5070_50700902_27_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_28_dialog_content = "¿En qué chocó el barco?",
  ui_story_5070_50700902_29_dialog_content = "Apaga el Dragón de Agua.",
  ui_story_5070_50700902_30_dialog_content = "La acción de bombeo es tan intensa que probablemente ha atraído algo enorme en el océano.",
  ui_story_5070_50700902_31_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_32_dialog_content = "¡El barco se inclina! Todos, agarren algo y sosténganse fuerte.",
  ui_story_5070_50700902_33_dialog_content = "Yo... lo hice.",
  ui_story_5070_50700902_34_dialog_content = "Finalmente llegué a la cubierta para tomar un poco de aire fresco, ¡y tenía que encontrarme con algo así!",
  ui_story_5070_50700902_35_dialog_content = "Menos mal que no me alejé de las cercas de bueyes. ¿No me digas que esa adivinación realmente significaba... ¡Ay!",
  ui_story_5070_50700902_36_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_37_dialog_content = "La inclinación empeora. No podemos hacer nada así.",
  ui_story_5070_50700902_38_dialog_content = "¡Todos, muévanse al otro lado! ¡Tenemos que equilibrar el barco!",
  ui_story_5070_50700902_39_dialog_content = "Usaré el Cangrejo de Fuego para impulsar el quemador de Shadowind. Solo agárrate y pronto ganaremos velocidad.",
  ui_story_5070_50700902_40_dialog_content = "¡Éxito! La sombra en el mar ha quedado atrás.",
  ui_story_5070_50700902_41_dialog_content = "He sido atacado por cangrejos de fuego tantas veces que es extraño ser salvado por ellos en esta ocasión.",
  ui_story_5070_50700902_42_dialog_content = "¿Qué te dije? Un artilugio es tan bueno o malo como aquellos que lo manejan.",
  ui_story_5070_50700902_43_dialog_content = "Depende del usuario usarlo para salvar una vida o terminarla.",
  ui_story_5070_50700902_44_dialog_content = "Tal vez debería cambiar de opinión acerca de esos \"cangrejos grandes y aterradores\"...",
  ui_story_5070_50700902_45_dialog_content = "Esta es la primera vez que Shadowind se mueve a tal velocidad. ¿Es sostenible?",
  ui_story_5070_50700902_46_dialog_content = "Solo en tus sueños.",
  ui_story_5070_50700902_47_dialog_content = "Obtenemos el poder que tenemos ahora todo gracias a la Fuerza de la Llama dentro del Cangrejo de Fuego.",
  ui_story_5070_50700902_48_dialog_content = "Se acabará muy rápido si no lo reponemos, entonces...",
  ui_story_5070_50700902_49_dialog_content = "Lady Xuan Ji! El chico junto a la caldera me dijo que todos los cangrejos de fuego ya no se mueven más.",
  ui_story_5070_50700902_50_dialog_content = "¿Como justo ahora?",
  ui_story_5070_50700902_51_dialog_content = "Bueno, murió más rápido de lo que anticipé.",
  ui_story_5070_50700902_52_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_53_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700902_54_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_55_dialog_content = "¿Funcionó?",
  ui_story_5070_50700902_56_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_57_dialog_content = "Por favor, detente. ¡No somos ni comida ni juguetes!",
  ui_story_5070_50700902_58_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5070_50700902_59_dialog_content = "No. Solo puedo hacer que se detenga por un tiempo. Aún nos alcanzarán a menos que Shadowind aumente la distancia.",
  ui_story_5070_50700902_60_dialog_content = "Y lo que percibí de su cuerpo bajo el agua es muchas veces más grande que la sombra en la superficie...",
  ui_story_5070_50700902_61_dialog_content = "¿Exactamente cuánto más grande es?",
  ui_story_5070_50700902_62_dialog_content = "¿Qué?",
  ui_story_5070_50700902_63_dialog_content = "Podemos medir la silueta en el agua.",
  ui_story_5070_50700902_X63_dialog_content = "Y luego calcula su tamaño basándote en tu enlace mental, PlayerName.",
  ui_story_5070_50700902_64_dialog_content = "Finalmente, determina su rango de amenaza según el peso de Shadowind y el ángulo de inclinación del impacto...",
  ui_story_5070_50700902_65_dialog_content = "¡Sé lo que hay debajo del agua!",
  ui_story_5070_50700902_66_dialog_content = "¿Puedes mantenerlo a raya por un tiempo, PlayerName? Tengo que buscar algo en mi cabaña que probablemente pueda alejarlo.",
  ui_story_5070_50700902_67_dialog_content = "Vale. Déjamelo a mí.",
  ui_story_5070_50700902_68_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700902_69_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_70_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50700902_71_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_72_dialog_content = "(Tss... ¿Cuántas veces?? Tienes que estar bromeando. ¿Y no es Xuan Ji mejor?)",
  ui_story_5070_50700902_73_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50700902_74_dialog_content = "¡Impulso de fuerza...!",
  ui_story_5070_50700902_75_dialog_content = "Ya estoy de vuelta, PlayerName!",
  ui_story_5070_50700902_76_dialog_content = "Brillante—",
  ui_story_5070_50700902_77_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5070_50700902_78_dialog_content = "(El impacto más violento hasta ahora ocurrió, y fui lanzado físicamente al aire.)",
  ui_story_5070_50700902_79_dialog_content = "¡Agarra mi sombrilla!",
  ui_story_5070_50700902_80_dialog_content = "(¡No! ¡No podré distraer al monstruo marino ahora...!)",
  ui_story_5070_50700902_81_dialog_content = "Xuan Ji! ¡Dame lo que tienes en la mano!",
  ui_story_5070_50700902_82_dialog_content = "¡¿?!",
  ui_story_5070_50700902_83_dialog_content = "¿Qué tipo de temerario eres tú...? Vale, aquí va!",
  ui_story_5070_50700902_84_dialog_content = "(¡Una ventaja de estar en lo alto es que puedes lanzar más lejos!)",
  ui_story_5070_50700902_85_dialog_content = "¡Deja de perseguir! ¡Este juguete es más adecuado para ti!",
  ui_story_5070_50700902_86_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5070_50700902_87_dialog_content = "<color=#e8d9bb>La piedra tomada de Xuan Ji cae al mar.</color>",
  ui_story_5070_50700902_88_dialog_content = "(Sentí que el monstruo marino giraba y vi a Xuan Ji abrir el paraguas para intentar atraparme.)",
  ui_story_5070_50700902_89_dialog_content = "(No hay tiempo, pero no importa porque... ¡Esa persona sigue ahí abajo!)",
  ui_story_5070_50700902_90_dialog_content = "¡A cenizas!",
  ui_story_5070_50700902_91_dialog_content = "<color=#e8d9bb>Con llamas escarlatas surgiendo hacia el cielo y el motor resonando con un zumbido a toda velocidad, el Shadowind acelera una vez más.</color>",
  ui_story_5070_50700902_92_dialog_content = "(Caí en llamas tranquilas y apacibles.)",
  ui_story_5070_50700902_93_dialog_content = "Uf, esta vez, perdimos al monstruo marino de una vez por todas. Por fin ha terminado...",
  ui_story_5070_50700902_94_dialog_content = "Joven amigo.",
  ui_story_5070_50700902_95_dialog_content = "Realmente admiro tu gran valentía.",
  ui_story_5070_50700902_96_dialog_content = "Pero, ¿no crees que fue demasiado imprudente ponerte en peligro de esa manera?",
  ui_story_5070_50700902_97_dialog_content = "(¡Q-qué tono tan serio!)",
  ui_story_5070_50700902_98_dialog_content = "Lo siento... por preocupar a todos. Sin embargo, en realidad estoy bastante seguro.",
  ui_story_5070_50700902_99_dialog_content = "Porque vi Zhong Xu aquí.",
  ui_story_5070_50700902_100_dialog_content = "Muchas gracias.",
  ui_story_5070_50700902_101_dialog_content = "... Está bien. Deberías agradecer a la Ministra Armilla en lugar de a mí.",
  ui_story_5070_50700902_102_dialog_content = "Sin las modificaciones que ella hizo a mi silla de ruedas, no podría moverme libremente en este barco inestable.",
  ui_story_5070_50700902_103_dialog_content = "¡PlayerName!",
  ui_story_5070_50700902_104_dialog_content = "¡Sabía que eras afortunado! Puedes lograr cualquier cosa siempre que lo intentes.",
  ui_story_5070_50700902_105_dialog_content = "Jaja, gracias por creerme. Pero, ¿cómo podría un trozo de roca atraer al monstruo marino?",
  ui_story_5070_50700902_106_dialog_content = "Porque esa no es una roca común, sino una piedra luminosa, cuanto más oscuro esté a su alrededor, más brillante se vuelve.",
  ui_story_5070_50700902_107_dialog_content = "No se ha escrito mucho sobre ese monstruo, excepto que habitaba en las profundidades del mar.",
  ui_story_5070_50700902_108_dialog_content = "Y criaturas como esas siempre se sienten atraídas por la luz.",
  ui_story_5070_50700902_109_dialog_content = "Así que pensé que sería un excelente señuelo.",
  ui_story_5070_50700902_110_dialog_content = "Por suerte, funcionó.",
  ui_story_5070_50700902_111_dialog_content = "¿Están todos bien?",
  ui_story_5070_50700902_112_dialog_content = "Estamos bien, excepto que estamos a segundos de ser comida de monstruos.",
  ui_story_5070_50700902_113_dialog_content = "Navegar por el océano es realmente difícil...",
  ui_story_5070_50700902_114_dialog_content = "Por suerte, este tipo de cosas no están en el cielo, de lo contrario Soroz y yo también estaríamos en peligro.",
  ui_story_5070_50700902_115_dialog_content = "Bueno, deberíamos estar a salvo por un tiempo después de ese encuentro angustioso.",
  ui_story_5070_50700902_116_dialog_content = "Después de todo, es raro encontrarse con tales colosos en el mar.",
  ui_story_5070_50700902_117_dialog_content = "Al menos no habrá otro ataque del que preocuparse hasta que hayamos salido de su territorio.",
  ui_story_5070_50700902_118_dialog_content = "Entonces, ¿estás diciendo que ahora podemos usar tantas Trampas de Dragón de Agua como queramos?",
  ui_story_5070_50700902_119_dialog_content = "Hasta el máximo, incluso.",
  ui_story_5070_50700902_120_dialog_content = "Que todos los que no estén ocupados vengan aquí. Aprovechemos esta oportunidad para esforzarnos al máximo, trabajar juntos y pescar más peces.",
  ui_story_5070_50700902_121_dialog_content = "Llevamos navegando un buen tiempo y es hora de reponer nuestras provisiones en el Shadowind.",
  ui_story_5070_50700902_122_dialog_content = "Okey... okey, ya viene.",
  ui_story_5070_50700902_123_dialog_content = "Uy.",
  ui_story_5070_50700902_124_dialog_content = "Perdón. Lo siento, no quise chocar contigo...",
  ui_story_5070_50700902_125_dialog_content = "¿Sun el Hábil? Está bien, simplemente no te vi llegar tampoco.",
  ui_story_5070_50700902_126_dialog_content = "¿Qué estás sosteniendo? Huele bien.",
  ui_story_5070_50700902_127_dialog_content = "Es cebo. El capitán nos dijo que pescáramos algunos peces.",
  ui_story_5070_50700902_128_dialog_content = "Con un aroma tan delicioso, debe ser fácil atrapar peces grandes.",
  ui_story_5070_50700902_129_dialog_content = "...¿Dónde está ella?",
  ui_story_5070_50700902_130_dialog_content = "¡Capitán! ¡Venga a ver lo que hemos pescado!",
  ui_story_5070_50700902_131_dialog_content = "¿Qué haces aquí, PlayerName?",
  ui_story_5070_50700902_132_dialog_content = "Justo ahora... ¿Sol el Hábil?",
  ui_story_5070_50700902_133_dialog_content = "...",
  ui_story_5070_50700902_134_dialog_content = "No importa, olvídalo.",
  ui_story_5070_50700902_135_dialog_content = "<size=25>Mientras el cebo permanezca, los peces subirán sin importar cuán profundo naden.</size>",
  ui_story_5070_50700902_136_dialog_content = "¿Qué dijiste?",
  ui_story_5070_50700902_137_dialog_content = "¡Nada! Vamos, vamos a ver la fiesta por allá.",
  ui_story_5070_50700902_138_dialog_content = "Está bien entonces... ¿Eh? ¿Cómo conseguiste tanta madera?",
  ui_story_5070_50700902_139_dialog_content = "Estos son restos de barcos hundidos.",
  ui_story_5070_50700902_140_dialog_content = "Pero el tipo de madera, pintura y grado de corrosión son diferentes. Es obvio que son de barcos distintos.",
  ui_story_5070_50700902_141_dialog_content = "Me temo que hay una concentración de naufragios en algún lugar por aquí.",
  ui_story_5070_50700902_142_dialog_content = "Incluso podría ser un cementerio de barcos.",
  ui_story_5070_50701001_1_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5070_50701001_2_dialog_content = "¿Yuebai?!",
  ui_story_5070_50701001_3_dialog_content = "¿Yuebai acaba de saltar de cabeza al mar?!",
  ui_story_5070_50701001_4_dialog_content = "No te preocupes. Yuebai nada mejor que todos en este barco juntos.",
  ui_story_5070_50701001_5_dialog_content = "Como pasajeros, debemos confiar en el capitán, así que solo esperemos y veamos.",
  ui_story_5070_50701001_6_dialog_content = "(Hay muchos tipos de peligros en el mar. Rocas, remolinos, feroces bestias marinas...)",
  ui_story_5070_50701001_7_dialog_content = "(Pero todos tienen algo en común. Todos son responsables de destruir innumerables barcos en diversas aguas.)",
  ui_story_5070_50701001_8_dialog_content = "(Después de que un barco se hunde, sus restos serán empujados por la corriente del océano y terminarán en el mismo lugar bajo el agua, formando un cementerio de barcos.)",
  ui_story_5070_50701001_9_dialog_content = "(¿Es este el lugar?)",
  ui_story_5070_50701001_10_dialog_content = "(Nunca pensé que un día navegaría un barco hacia un cementerio como este.)",
  ui_story_5070_50701001_11_dialog_content = "(Los esqueletos de barcos rotos están apilados, cubiertos gradualmente por corales y algas marinas, erosionándose y pudriéndose.",
  ui_story_5070_50701001_12_dialog_content = "(Es como si el mar estuviera celebrando un funeral para despedir a estos barcos.)",
  ui_story_5070_50701001_13_dialog_content = "(¡... Ese barco!)",
  ui_story_5070_50701001_14_dialog_content = "En un momento, Ministra Armilla, joven amigo, ¿puedes rescatar más de estos fragmentos de barco para mí?",
  ui_story_5070_50701001_15_dialog_content = "Estos fragmentos me parecen un poco familiares.",
  ui_story_5070_50701001_16_dialog_content = "Por lo que puedo ver, no hay ninguna diferencia entre estos trozos de madera.",
  ui_story_5070_50701001_17_dialog_content = "Cualquier cosa puede decirte algo si miras lo suficientemente de cerca.",
  ui_story_5070_50701001_18_dialog_content = "Quizás no sea tan bueno como Zhong Xu, pero aún puedo aprovechar mucho de ello.",
  ui_story_5070_50701001_19_dialog_content = "Mira, esta pieza tiene el nombre del barco en ella.",
  ui_story_5070_50701001_20_dialog_content = "Y este de aquí tiene Agujeros de Fortuna.",
  ui_story_5070_50701001_21_dialog_content = "¿No es solo una brecha rota?",
  ui_story_5070_50701001_22_dialog_content = "No, estos fueron perforados a propósito.",
  ui_story_5070_50701001_23_dialog_content = "Para guardar amuletos de la suerte como monedas o espejos en su interior.",
  ui_story_5070_50701001_24_dialog_content = "Está destinado a garantizar una navegación suave.",
  ui_story_5070_50701001_25_dialog_content = "Pero como se encontró en un naufragio, es probable que la tripulación y los pasajeros ya no estén... El destino es caprichoso.",
  ui_story_5070_50701001_26_dialog_content = "Cuanto más escombros se sacan, más siento que este lugar es realmente peligroso...",
  ui_story_5070_50701001_27_dialog_content = "¿Para qué es esa expresión, Zhong Xu...? ¿Qué ves?",
  ui_story_5070_50701001_28_dialog_content = "Uno de estos barcos pertenecía a piratas.",
  ui_story_5070_50701001_29_dialog_content = "¡¿Piratas?!",
  ui_story_5070_50701001_30_dialog_content = "He tenido muchos tratos con ellos, así que creo que tengo razón.",
  ui_story_5070_50701001_31_dialog_content = "Pero los piratas deambulan por el mar todo el año y están mucho más alerta de las aguas peligrosas que la gente común.",
  ui_story_5070_50701001_32_dialog_content = "Me pregunto si fueron traídos aquí por el viento o perseguidos por algo.",
  ui_story_5070_50701001_33_dialog_content = "Eso suena un poco aterrador... ¡Ya hemos sentido la presión de los Eclipsites, tormentas y monstruos marinos!",
  ui_story_5070_50701001_34_dialog_content = "Y ahora, ¿debemos preocuparnos por lo que destruyó el barco de los piratas y si es una amenaza para nosotros?!",
  ui_story_5070_50701001_35_dialog_content = "<color=#e8d9bb>¡Bum!</color>",
  ui_story_5070_50701001_36_dialog_content = "¡Es Yuebai! ¡Ha salido a la superficie!",
  ui_story_5070_50701001_37_dialog_content = "Sé dónde está esto.",
  ui_story_5070_50701001_38_dialog_content = "Debajo de nosotros hay un barco pesquero de alta mar que naufragó hace varios años.",
  ui_story_5070_50701001_39_dialog_content = "Juzgando por la ruta que debería haber tomado, este debería ser un punto de conexión entre las aguas del océano y Longzhou.",
  ui_story_5070_50701001_40_dialog_content = "Entonces, ¿eso no significa...?",
  ui_story_5070_50701001_41_dialog_content = "Sí, eso significa que no estamos lejos de Longzhou.",
  ui_story_5070_50701001_42_dialog_content = "¡Eso es genial!",
  ui_story_5070_50701001_43_dialog_content = "Es demasiado temprano para relajarse.",
  ui_story_5070_50701001_44_dialog_content = "Este lugar es famoso por ser un lugar de muerte en el mar. No hay cartas náuticas correspondientes para estas aguas y no está en la ruta establecida de Shadowind.",
  ui_story_5070_50701001_45_dialog_content = "Incluso si conocemos su ubicación aproximada, no podremos determinar en qué dirección deberíamos navegar.",
  ui_story_5070_50701001_46_dialog_content = "También nos estamos quedando sin comida, así que no tenemos tiempo que perder.",
  ui_story_5070_50701001_47_dialog_content = "¿Podrías pedirle a Zhong Xu y Xuan Ji que pongan el motor a toda marcha para que podamos salir de aquí?",
  ui_story_5070_50701001_48_dialog_content = "No. Hay muchos remolinos por aquí. Un error y podríamos terminar descansando en el cementerio de barcos en el fondo del mar.",
  ui_story_5070_50701001_49_dialog_content = "Incluso si ellos están aquí, nuestra situación seguirá siendo desesperada. A menos que...",
  ui_story_5070_50701001_50_dialog_content = "¿A menos que...?",
  ui_story_5070_50701001_51_dialog_content = "A menos que alguien notara que Shadowind se había desviado hace un tiempo y ya hubiera planeado una contramedida.",
  ui_story_5070_50701001_52_dialog_content = "La primera persona en notar el cabeceo... Xuan Ji?",
  ui_story_5070_50701001_53_dialog_content = "...",
  ui_story_5070_50701001_54_dialog_content = "Oye, no me mires así.",
  ui_story_5070_50701001_55_dialog_content = "Tengo una idea, pero...",
  ui_story_5070_50701001_56_dialog_content = "Es hacer o morir.",
  ui_story_5070_50701001_57_dialog_content = "Aunque estemos en un aprieto, aún podemos avanzar poco a poco en Shadowind.",
  ui_story_5070_50701001_58_dialog_content = "Pero si intentamos esto y fallamos, todo el barco se hundirá en llamas.",
  ui_story_5070_50701001_59_dialog_content = "Y nos convertimos en comida para peces.",
  ui_story_5070_50701001_60_dialog_content = "Es demasiado arriesgado a menos que sea el último recurso.",
  ui_story_5070_50701001_61_dialog_content = "¡Capitán! ¡Capitán! Malas noticias, hay niebla adelante!",
  ui_story_5070_50701001_62_dialog_content = "No podemos ver mucho a nuestro alrededor ahora; ¿qué debemos hacer?",
  ui_story_5070_50701001_63_dialog_content = "Intentar navegar en una niebla tan espesa es como caminar hacia una muerte segura con los ojos cerrados.",
  ui_story_5070_50701001_64_dialog_content = "Pero ya no tenemos elección.",
  ui_story_5070_50701001_65_dialog_content = "Está bien.",
  ui_story_5070_50701001_66_dialog_content = "Guardé algo especial en la bodega cuando subí a bordo.",
  ui_story_5070_50701001_67_dialog_content = "Puede alimentar todos y cada uno de los dispositivos.",
  ui_story_5070_50701001_68_dialog_content = "Cangrejo de Fuego, Dragón de Agua, incluso el quemador que impulsa el Shadowind...",
  ui_story_5070_50701001_69_dialog_content = "Todos pueden desempeñarse como nunca antes bajo su poder.",
  ui_story_5070_50701001_70_dialog_content = "Pero es inestable y muy desafiante de controlar.",
  ui_story_5070_50701001_71_dialog_content = "Se ha registrado que en varias pruebas, la salida fue tan excesiva...",
  ui_story_5070_50701001_72_dialog_content = "El objetivo no era lo suficientemente resistente y se autodestruyó.",
  ui_story_5070_50701001_73_dialog_content = "Entonces, incluso si decidimos usarlo, tengo que probarlo bajo el agua primero.",
  ui_story_5070_50701001_74_dialog_content = "El Shadowind también deberá someterse a modificaciones para que al menos pueda resistir el impacto operacional.",
  ui_story_5070_50701001_75_dialog_content = "De lo contrario, no será nuestra última esperanza, sino nuestra muerte.",
  ui_story_5070_50701001_76_dialog_content = "Te daré una lista de los materiales en Shadowind más tarde. Solo haz lo que necesites hacer.",
  ui_story_5070_50701001_77_dialog_content = "También informaré a los carpinteros de barcos que deben seguir tus órdenes.",
  ui_story_5070_50701001_78_dialog_content = "Tal vez mis Artes Flame Force también sean útiles.",
  ui_story_5070_50701001_79_dialog_content = "¿Por qué no me encargo del pescado que acabamos de atrapar y lo preparo de una manera que te parezca novedosa?",
  ui_story_5070_50701001_80_dialog_content = "Pero yo... ¿Qué puedo hacer?",
  ui_story_5070_50701001_81_dialog_content = "Tengo que buscar cosas en la bodega, PlayerName.",
  ui_story_5070_50701001_82_dialog_content = "¿Te importaría encontrar al pequeño y conseguir algunas pociones para resistir los gases tóxicos?",
  ui_story_5070_50701001_83_dialog_content = "¿Me estás diciendo que Xuan Ji trajo un Flame Sprite a bordo?!",
  ui_story_5070_50701001_84_dialog_content = "Me preguntaba por qué seguía oliendo uno a bordo. ¡Casi pensé que había algo malo con mi nariz!",
  ui_story_5070_50701001_85_dialog_content = "Entonces ella está detrás de esto. Hacer algo tan peligroso...",
  ui_story_5070_50701001_86_dialog_content = "Según el Maestro Bu, un antiguo ser consciente como ese podría controlar el yin y el yang, ¡y cambiar el día por la noche!",
  ui_story_5070_50701001_87_dialog_content = "Suspiro, esto va a ser un dolor.",
  ui_story_5070_50701001_88_dialog_content = "Toma esta medicina y dile que no haga explotar este barco.",
  ui_story_5070_50701001_89_dialog_content = "Tengo la medicina, Xuan Ji.",
  ui_story_5070_50701001_90_dialog_content = "Pero, ¿de qué estás hablando exactamente?",
  ui_story_5070_50701001_91_dialog_content = "Acabo de repetir tu descripción y Liqing de inmediato comenzó a armar un alboroto.",
  ui_story_5070_50701001_92_dialog_content = "Todos los demás parecían entender. ¿Soy solo yo quien se siente completamente en la oscuridad?",
  ui_story_5070_50701001_93_dialog_content = "Bueno, eso no es para que lo digas tú, PlayerName.",
  ui_story_5070_50701001_94_dialog_content = "No estoy seguro de saber más que tú sobre este barco.",
  ui_story_5070_50701001_95_dialog_content = "¿Yo?",
  ui_story_5070_50701001_96_dialog_content = "Lo sabrás cuando lo saque.",
  ui_story_5070_50701001_97_dialog_content = "¿Sacarlo? ¿De dónde?",
  ui_story_5070_50701001_98_dialog_content = "Hablando de eso, he querido preguntar desde hace tiempo... ¿Por qué hay tantas vacas de madera en la bodega?",
  ui_story_5070_50701001_99_dialog_content = "Son bueyes de madera, el artefacto más común en Longzhou y que ha existido durante generaciones.",
  ui_story_5070_50701001_100_dialog_content = "Principalmente se utilizan para transportar mercancías, aunque también son útiles para llevar equipaje.",
  ui_story_5070_50701001_101_dialog_content = "Simplemente ábrelo así y podrás sacar cosas.",
  ui_story_5070_50701001_102_dialog_content = "Es bastante espacioso por dentro. Probablemente podría caber una persona allí.",
  ui_story_5070_50701001_103_dialog_content = "¿Quieres probarlo?",
  ui_story_5070_50701001_104_dialog_content = "¡De ninguna manera! No tengo interés en convertirme en una mercancía.",
  ui_story_5070_50701001_105_dialog_content = "Eso pensé yo también.",
  ui_story_5070_50701001_106_dialog_content = "Entonces, veamos a la estrella del espectáculo de hoy.",
  ui_story_5070_50701001_107_dialog_content = "¿Esta pequeña caja?",
  ui_story_5070_50701001_108_dialog_content = "No subestimes esto.",
  ui_story_5070_50701001_109_dialog_content = "Qianyun, mi escuela, es una de las mejores creadoras de dispositivos en Ye, e incluso en todo Longzhou.",
  ui_story_5070_50701001_110_dialog_content = "Cuenta con un legado de técnicas secretas y artefactos durante siglos.",
  ui_story_5070_50701001_111_dialog_content = "Pero incluso si juntas todo eso, aún podría no compararse con esto.",
  ui_story_5070_50701001_112_dialog_content = "Una de las mayores razones para visitar Astra es...",
  ui_story_5070_50701001_113_dialog_content = "Para encontrar el inestimable tesoro perdido en el extranjero hace muchos años...",
  ui_story_5070_50701001_114_dialog_content = "La Llama Zhuyin.",
  ui_story_5070_50701001_115_dialog_content = "Desde la perspectiva de Astra, también es una valiosa reliquia antigua.",
  ui_story_5070_50701001_116_dialog_content = "¿Reliquia antigua?!",
  ui_story_5070_50701001_117_dialog_content = "¿Quieres ver cuán poderoso es?",
  ui_story_5070_50701001_118_dialog_content = "Es un poco arriesgado en el Shadowind. Probemos en un bote pequeño lejos de aquí.",
  ui_story_5070_50701001_119_dialog_content = "Observa la verdadera obra maestra de tiempos pasados que lo alimentaba todo.",
  ui_story_5070_50701002_1_dialog_content = "Sin duda encaja como una reliquia antigua. Es incluso más poderoso de lo que esperaba.",
  ui_story_5070_50701002_2_dialog_content = "Tú también lo sentiste con tus poderes psíquicos, ¿verdad, PlayerName? ¿Cómo se siente?",
  ui_story_5070_50701002_3_dialog_content = "Bastante impresionante.",
  ui_story_5070_50701002_4_dialog_content = "No solo puede impulsar sin cesar a las Bestias Mecánicas, que ya se han quedado sin energía, sino que también puede...",
  ui_story_5070_50701002_5_dialog_content = "También evapora toda la humedad circundante, creando un vacío.",
  ui_story_5070_50701002_6_dialog_content = "En respuesta, parece más sustancial que todas las demás llamas, incluso como...",
  ui_story_5070_50701002_7_dialog_content = "¿Un sol en miniatura?",
  ui_story_5070_50701002_8_dialog_content = "Totalmente... Espera, ¿no es esa mi propia descripción?",
  ui_story_5070_50701002_9_dialog_content = "La Llama Zhuyin... ¡Eso podría haber causado la explosión en el barco ese día!",
  ui_story_5070_50701002_10_dialog_content = "Vaya, pillado.",
  ui_story_5070_50701002_11_dialog_content = "¿No aceptaste que echara un vistazo usando mi habilidad? ¡Solo obedecí!",
  ui_story_5070_50701002_12_dialog_content = "Después de todo, ver es creer. ¡Te muestra más de lo que yo podría explicar!",
  ui_story_5070_50701002_13_dialog_content = "No es de extrañar que Liqing haya tenido una reacción tan fuerte.",
  ui_story_5070_50701002_14_dialog_content = "¿Quién podría haber pensado que habría algo tan peligroso a bordo?",
  ui_story_5070_50701002_15_dialog_content = "Lo sellé cuidadosamente antes de subirlo a bordo para que estuviera seguro.",
  ui_story_5070_50701002_16_dialog_content = "Pero alguien la abrió intencionalmente el día del incendio.",
  ui_story_5070_50701002_17_dialog_content = "Lo subí a bordo en secreto.",
  ui_story_5070_50701002_18_dialog_content = "Incluso Yuebai no sabía qué era, y eso que le di un aviso sobre ello.",
  ui_story_5070_50701002_19_dialog_content = "Pero alguien lo sabía e intentó acercarse.",
  ui_story_5070_50701002_20_dialog_content = "¿Podría ser esa figura que vi antes...?!",
  ui_story_5070_50701002_21_dialog_content = "Me temo que sí.",
  ui_story_5070_50701002_22_dialog_content = "Para este tipo de cosas... Tenemos que informar a los demás de inmediato.",
  ui_story_5070_50701002_23_dialog_content = "Resulta que la prueba de la Llama Zhuyin fue exitosa, así que el Shadowind puede salir de aquí de inmediato.",
  ui_story_5070_50701002_24_dialog_content = "Aprovecha el momento para atrapar a ese tipo malvado—",
  ui_story_5070_50701002_25_dialog_content = "No recuerdo haber declarado el examen exitoso.",
  ui_story_5070_50701002_26_dialog_content = "¿Qué? ¿No se han activado todas estas Bestias Mecánicas sin problemas?",
  ui_story_5070_50701002_27_dialog_content = "No cabe duda de que la Llama Zhuyin es una fuente de poder, pero ¿no viste lo que les pasó a las bestias mecánicas?",
  ui_story_5070_50701002_28_dialog_content = "... Roto en pedazos y cayó al mar.",
  ui_story_5070_50701002_29_dialog_content = "Las bestias no eran grandes, y aun así eso era todo lo que podía manejar con cierta seguridad.",
  ui_story_5070_50701002_30_dialog_content = "Entonces, incluso si refuerzas Shadowind con todos los materiales que puedas encontrar...",
  ui_story_5070_50701002_31_dialog_content = "No va a resistir la Llama Zhuyin a plena potencia.",
  ui_story_5070_50701002_32_dialog_content = "¿Realmente Xuan Ji tampoco podría resolverlo?",
  ui_story_5070_50701002_33_dialog_content = "Eso no es del todo cierto.",
  ui_story_5070_50701002_34_dialog_content = "Pero hasta entonces, tengo una petición, PlayerName.",
  ui_story_5070_50701002_35_dialog_content = "Por favor, mantén en secreto el experimento fallido y a alguien vigilando la Llama.",
  ui_story_5070_50701002_36_dialog_content = "Tal vez... Pero, ¿qué debemos hacer ahora?",
  ui_story_5070_50701002_37_dialog_content = "Solo espera.",
  ui_story_5070_50701002_38_dialog_content = "<color=#e8d9bb>El siguiente día...</color>",
  ui_story_5070_50701002_39_dialog_content = "Todos, vengan y tomen una copia del plano. Sigan las marcas y comiencen a trabajar en sus lugares asignados.",
  ui_story_5070_50701002_40_dialog_content = "¿Qué tipo de plano es este?",
  ui_story_5070_50701002_41_dialog_content = "Eh... este plano...",
  ui_story_5070_50701002_42_dialog_content = "He estado lidiando con barcos toda mi vida, y nunca había visto algo así en un barco...",
  ui_story_5070_50701002_43_dialog_content = "Ignorar el gran agujero en la cubierta es una cosa, ¿pero agrandarlo a propósito?",
  ui_story_5070_50701002_44_dialog_content = "Casi está exponiendo el núcleo de Shadowind. Eso es demasiado extraño... Sol, ¿qué opinas al respecto?",
  ui_story_5070_50701002_45_dialog_content = "Yo... yo tampoco lo entiendo...",
  ui_story_5070_50701002_46_dialog_content = "¿Por qué molestarse con todo eso? Lady Xuan Ji es mucho más hábil que nosotros, ¿verdad?",
  ui_story_5070_50701002_47_dialog_content = "Vamos a trabajar ahora; una vez terminado, definitivamente podremos salir de aquí.",
  ui_story_5070_50701002_48_dialog_content = "<color=#e8d9bb>Día Tres</color>",
  ui_story_5070_50701002_49_dialog_content = "Chicos, acompáñenme a pescar.",
  ui_story_5070_50701002_50_dialog_content = "Ugh, ¿cuántos días llevamos sobreviviendo con pescado? Y ahora, incluso se nos está acabando el condimento. Saben... No hay palabras para describirlo.",
  ui_story_5070_50701002_51_dialog_content = "Solo espera unos días. Las cosas mejorarán una vez que se complete la remodelación del barco.",
  ui_story_5070_50701002_52_dialog_content = "<color=#e8d9bb>Día Cinco</color>",
  ui_story_5070_50701002_53_dialog_content = "La niebla en nuestro lugar de pesca se está volviendo más espesa; apenas podemos pescar algún pez ahora.",
  ui_story_5070_50701002_54_dialog_content = "¿No terminamos la renovación de Shadowind? ¿Por qué Lady Xuan Ji no nos ha dado más instrucciones...",
  ui_story_5070_50701002_55_dialog_content = "Li, no le digas a nadie, pero escuché de Sun el Hábil que nuestros esfuerzos en esta renovación no tienen sentido.",
  ui_story_5070_50701002_56_dialog_content = "¿No has notado que Lady Xuan Ji sale en un bote pequeño todos los días? Dice que es para explorar, ¡pero parece que intenta ocultar lo perdido que está!",
  ui_story_5070_50701002_57_dialog_content = "¿De qué tonterías están hablando todos ustedes? Y tú, Sun, no dejes que el Capitán Yuebai te atrape difundiendo rumores sin fundamento...",
  ui_story_5070_50701002_58_dialog_content = "¡Oye! PlayerName! PlayerName!",
  ui_story_5070_50701002_59_dialog_content = "Has estado saliendo con Lady Xuan Ji estos últimos días. ¿Has escuchado algo sobre cómo vamos a salir de aquí?",
  ui_story_5070_50701002_60_dialog_content = "Bueno, lo único que puedo decir es que hay una forma... T-Tengo que darle algo a Xuan Ji, ¡así que me voy!",
  ui_story_5070_50701002_61_dialog_content = "Phew...",
  ui_story_5070_50701002_62_dialog_content = "Ven rápido, PlayerName. Hice modificaciones estructurales similares según tu descripción del Coloso.",
  ui_story_5070_50701002_63_dialog_content = "¿Qué? Parece que tuviste otra ronda con la tripulación.",
  ui_story_5070_50701002_64_dialog_content = "Jaja... Después de todo, hemos estado aquí varios días. Todos están un poco nerviosos y quieren salir de aquí lo más pronto posible.",
  ui_story_5070_50701002_65_dialog_content = "Este modelo, bueno, comparado con el Colossus, parece más bien un Shadowind con alas. Déjame ver...",
  ui_story_5070_50701002_66_dialog_content = "¿No tienes ninguna pregunta para mí, PlayerName?",
  ui_story_5070_50701002_67_dialog_content = "¿Qué?",
  ui_story_5070_50701002_68_dialog_content = "Te pedí que guardaras un secreto sin darte una explicación sólida.",
  ui_story_5070_50701002_69_dialog_content = "Luego, instruí a otros para hacer tantas modificaciones solo para quedarme en un bote todo el día y evitar todas las preguntas.",
  ui_story_5070_50701002_70_dialog_content = "Incluso yo sospecharía que estoy tramando algo malo.",
  ui_story_5070_50701002_71_dialog_content = "¿Por qué confiaste en mí, PlayerName?",
  ui_story_5070_50701002_72_dialog_content = "Realmente no te creo.",
  ui_story_5070_50701002_73_dialog_content = "Pensé eso...",
  ui_story_5070_50701002_74_dialog_content = "Pero sí creo en la maquinaria.",
  ui_story_5070_50701002_75_dialog_content = "¿Ah?",
  ui_story_5070_50701002_76_dialog_content = "Por supuesto, no fue precisamente relajante lidiar con esas Bestias Mecánicas que aparecieron de la nada.",
  ui_story_5070_50701002_77_dialog_content = "Pero la primera vez que nos conocimos, una libélula me ayudó a recoger la carta.",
  ui_story_5070_50701002_78_dialog_content = "Cangrejos de fuego para impulsar el motor, dragones de agua para apagar incendios...",
  ui_story_5070_50701002_79_dialog_content = "Las criaturas mecánicas me han ayudado una y otra vez.",
  ui_story_5070_50701002_80_dialog_content = "Lo dijiste tú mismo, Xuan Ji: La maquinaria no es una tecnología omnipotente y en constante cambio.",
  ui_story_5070_50701002_81_dialog_content = "Creo en la maquinaria, sobre la cual nunca mentirías.",
  ui_story_5070_50701002_82_dialog_content = "Así que también creo que encontrarás una manera de llevarnos a salvo a Longzhou.",
  ui_story_5070_50701002_83_dialog_content = "Está.",
  ui_story_5070_50701002_84_dialog_content = "Bueno, no puedo refutar eso en absoluto.",
  ui_story_5070_50701002_85_dialog_content = "Dado lo que dijiste, PlayerName...",
  ui_story_5070_50701002_86_dialog_content = "Sería negligente como artesano si no te muestro el potencial de mi oficio.",
  ui_story_5070_50701002_87_dialog_content = "Estoy deseando que llegue. Pero mentiría si dijera que no tengo curiosidad.",
  ui_story_5070_50701002_88_dialog_content = "¿Qué exactamente estás esperando, Xuan Ji?",
  ui_story_5070_50701002_89_dialog_content = "Bueno en realidad...",
  ui_story_5070_50701002_90_dialog_content = "<color=#e8d9bb>Explosión de silbato</color>",
  ui_story_5070_50701002_91_dialog_content = "¿Qué es ese sonido del Shadowind? ¿Por qué suena la bocina?",
  ui_story_5070_50701002_92_dialog_content = "Esa es la señal para la comunicación entre barcos en el mar.",
  ui_story_5070_50701002_93_dialog_content = "¿Podría haber otro barco?!",
  ui_story_5070_50701002_94_dialog_content = "<color=#e8d9bb>Hace un ratito</color>",
  ui_story_5070_50701002_95_dialog_content = "Jiu, Yuebai, ven a ver esto.",
  ui_story_5070_50701002_96_dialog_content = "¿Es ese un barco allá afuera?",
  ui_story_5070_50701002_97_dialog_content = "Su Alteza, por favor, retroceda del borde del barco.",
  ui_story_5070_50701002_98_dialog_content = "Eso no es lo que deberías preocuparte, Jiu.",
  ui_story_5070_50701002_99_dialog_content = "Tu seguridad es de suma importancia, así que debemos tomar todas las precauciones necesarias.",
  ui_story_5070_50701002_100_dialog_content = "No puedo ver qué está pasando en el barco, pero algunos barcos comerciantes se acercan hacia nosotros.",
  ui_story_5070_50701002_101_dialog_content = "Nunca pensé que encontraríamos otros barcos en estas aguas.",
  ui_story_5070_50701002_102_dialog_content = "¿Deberíamos ponernos en contacto con ellos? Me pregunto si tendrán suficientes suministros. Si no...",
  ui_story_5070_50701002_103_dialog_content = "Probablemente ya sea demasiado tarde para evitarlos de todos modos.",
  ui_story_5070_50701002_104_dialog_content = "Toca la bocina y veamos cómo reaccionan.",
  ui_story_5070_50701002_105_dialog_content = "<color=#e8d9bb>Explosión de silbato</color>",
  ui_story_5070_50701002_106_dialog_content = "<color=#e8d9bb>Explosión de silbato</color>",
  ui_story_5070_50701002_107_dialog_content = "¡Respuesta recibida!",
  ui_story_5070_50701002_108_dialog_content = "¿Es un barco que también está atrapado aquí? Perfecto, podemos pensar juntos en una forma de salir.",
  ui_story_5070_50701002_109_dialog_content = "Quizás también podamos intercambiar algo de comida y agua con ellos.",
  ui_story_5070_50701002_110_dialog_content = "Entonces, volvamos al barco y resolvámoslo.",
  ui_story_5070_50701002_111_dialog_content = "Los tengo a la vista. Está claro que se acercan al Shadowind.",
  ui_story_5070_50701002_112_dialog_content = "Uh... ¿No van un poco rápido?",
  ui_story_5070_50701002_113_dialog_content = "¿No solo están fallando en desacelerar, sino que en realidad están acelerando?!",
  ui_story_5070_50701002_114_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5070_50701002_115_dialog_content = "¿Cómo... Cómo pudo ese barco embestir al Shadowind?!",
  ui_story_5070_50701002_116_dialog_content = "Oh no...",
  ui_story_5070_50701002_117_dialog_content = "¡Es un barco pirata!",
  ui_story_5070_50701002_118_dialog_content = "¡Apúrate, PlayerName, Shadowind está en problemas!",
  ui_story_5070_50701101_1_dialog_content = "¡Por qué, insolentes rufianes! ¿Cómo se atreven a hacerle eso a Jiu...",
  ui_story_5070_50701101_2_dialog_content = "¡Espera!",
  ui_story_5070_50701101_3_dialog_content = "<color=#e8d9bb>¡Swoosh!</color>",
  ui_story_5070_50701101_4_dialog_content = "<color=#e8d9bb>La cubierta a los pies de Dantang es golpeada, quemando un gran agujero.</color>",
  ui_story_5070_50701101_5_dialog_content = "...",
  ui_story_5070_50701101_6_dialog_content = "Su Alteza, sé que no es mi lugar decir esto; me atrevo a recordarle...",
  ui_story_5070_50701101_7_dialog_content = "Puede que se sienta bien ganar una pelea verbal, pero en el mar, es mejor prevenir que lamentar.",
  ui_story_5070_50701101_8_dialog_content = "Parece que Dantang está siendo atacado. ¡Subamos allí rápidamente—",
  ui_story_5070_50701101_9_dialog_content = "Espera, ellos saben quiénes somos, así que no creo que les pase nada malo a la princesa y a Jiu.",
  ui_story_5070_50701101_10_dialog_content = "Pero aún no sabemos qué traman, así que si subimos ahora solo nos capturarán.",
  ui_story_5070_50701101_11_dialog_content = "Simplemente mantente oculto y averigua la situación antes de hacer un movimiento.",
  ui_story_5070_50701101_12_dialog_content = "Mmm... ¿La voz de quien estaba hablando con Dantang me suena un poco familiar?",
  ui_story_5070_50701101_13_dialog_content = "Ese es el hábil Sol.",
  ui_story_5070_50701101_14_dialog_content = "¡¿Él?!",
  ui_story_5070_50701101_15_dialog_content = "Shh.",
  ui_story_5070_50701101_16_dialog_content = "Sigue escuchando.",
  ui_story_5070_50701101_17_dialog_content = "No eres el verdadero Sun el Hábil, ¿verdad?",
  ui_story_5070_50701101_18_dialog_content = "Je, Sun el Hábil no es más que una fachada.",
  ui_story_5070_50701101_19_dialog_content = "Pero para personas humildes como tú, solo me conocerás como Sun el Hábil.",
  ui_story_5070_50701101_20_dialog_content = "Tú... ¡No puedo creer que realmente hayas conspirado con piratas!",
  ui_story_5070_50701101_21_dialog_content = "¿Has olvidado el favor que nos hizo la familia Lin? Tú, traidor desleal...",
  ui_story_5070_50701101_22_dialog_content = "¡Ciérralo!",
  ui_story_5070_50701101_23_dialog_content = "Mantén la voz baja si no quieres terminar ahogándote allí abajo junto a la señorita Jiu.",
  ui_story_5070_50701101_24_dialog_content = "Ten en cuenta: el guerrero más hábil de esta nave ya ha estirado la pata.",
  ui_story_5070_50701101_25_dialog_content = "Supongo que no hay mucho espacio para luchar de tu parte.",
  ui_story_5070_50701101_26_dialog_content = "¡Eso es porque recurriste a tácticas deplorables!",
  ui_story_5070_50701101_27_dialog_content = "Jiu no estaría en desventaja sin ese rayo peculiar!",
  ui_story_5070_50701101_28_dialog_content = "¿Recurre a insultos, eh? Princesa, realmente te sugiero que cuides tu lengua.",
  ui_story_5070_50701101_29_dialog_content = "¡Esa es una maravillosa creación mecánica a la par con... No, ¡supera por completo al Shadowind!",
  ui_story_5070_50701101_30_dialog_content = "Cualquiera puede presumir.",
  ui_story_5070_50701101_31_dialog_content = "¿Qué tan honorable puedes ser al esconderte en tu barco y solo tender emboscadas desde lejos?",
  ui_story_5070_50701101_32_dialog_content = "(Así es, princesa Dantang. Sigue irritándolo intencionalmente.)",
  ui_story_5070_50701101_33_dialog_content = "(Necesitamos obtener tanta información como podamos antes de que Jiu y los demás regresen.)",
  ui_story_5070_50701101_34_dialog_content = "Además de lanzar un ataque sorpresa, lo único que han hecho sus hombres después de abordar nuestro barco es capturar a Zhong Xu y Liqing.",
  ui_story_5070_50701101_35_dialog_content = "Sois un grupo de cobardes que solo se atreven a atacar a un hombre discapacitado y a un niño.",
  ui_story_5070_50701101_36_dialog_content = "Vamos a dividir.",
  ui_story_5070_50701101_37_dialog_content = "Esa creación obviamente tiene una potente salida para proyectar el rayo letal.",
  ui_story_5070_50701101_38_dialog_content = "Tengo que ir a echar un vistazo más de cerca.",
  ui_story_5070_50701101_39_dialog_content = "¿Yo?",
  ui_story_5070_50701101_40_dialog_content = "Quédate en el barco y mantén un ojo en Shadowind.",
  ui_story_5070_50701101_41_dialog_content = "Asegúrate de mantenerte escondido. Me tengo que ir—",
  ui_story_5070_50701101_42_dialog_content = "Esto no se llama división del trabajo.",
  ui_story_5070_50701101_43_dialog_content = "?",
  ui_story_5070_50701101_44_dialog_content = "Esto solo significa dejarme en un lugar seguro, mientras tú asumes los riesgos.",
  ui_story_5070_50701101_45_dialog_content = "De alguna manera...",
  ui_story_5070_50701101_46_dialog_content = "Pero el tiempo es precioso.",
  ui_story_5070_50701101_47_dialog_content = "Quiero regresar a Shadowind. Aunque no puedo luchar como tú...",
  ui_story_5070_50701101_48_dialog_content = "Debe haber algo que pueda hacer allá arriba.",
  ui_story_5070_50701101_49_dialog_content = "Incluso si te descubren, podría ser capaz de ganarte algo de tiempo.",
  ui_story_5070_50701101_50_dialog_content = "ESTO se llama división del trabajo.",
  ui_story_5070_50701101_51_dialog_content = "¿Qué pasa si rechazo esa idea?",
  ui_story_5070_50701101_52_dialog_content = "Entonces esperaré a que te vayas y luego me colaré en el barco.",
  ui_story_5070_50701101_53_dialog_content = "No me digas que lanzarse imprudentemente al peligro es un rasgo de los Caelestites.",
  ui_story_5070_50701101_54_dialog_content = "¿Es cosa de artesanos querer proteger a todos detrás de ellos y hacer todo por sí mismos?",
  ui_story_5070_50701101_55_dialog_content = "Supongo que eso nos hace uno y lo mismo.",
  ui_story_5070_50701101_56_dialog_content = "Confías en mí, PlayerName...",
  ui_story_5070_50701101_57_dialog_content = "Entonces, si no confío en ti a cambio, PlayerName, eso sería bastante injusto.",
  ui_story_5070_50701101_58_dialog_content = "Pues bien, buena suerte.",
  ui_story_5070_50701102_1_dialog_content = "¡Impulso de fuerza! Pensaste en algo que olvidaste—",
  ui_story_5070_50701102_2_dialog_content = "¡Ey! ¿El jefe se ha olvidado de mi recompensa? Tengo que ir a recordárselo...",
  ui_story_5070_50701102_3_dialog_content = "<color=#e8d9bb>¡Tom, tom, tom!</color>",
  ui_story_5070_50701102_4_dialog_content = "(Excelente, estos piratas de Longzhou no tienen ningún conocimiento ni experiencia sobre las habilidades telepáticas de Caelestite.)",
  ui_story_5070_50701102_5_dialog_content = "(Entonces puedo dar un pequeño empujón en silencio así, sugiriendo que aquellos que estén preocupados podrían salir de allí por un tiempo...)",
  ui_story_5070_50701102_6_dialog_content = "¿Por qué se fue el tipo de la puerta? ¿Seguimos patrullando o qué?",
  ui_story_5070_50701102_7_dialog_content = "Está bien. De todos modos, no afectará nuestra tarea.",
  ui_story_5070_50701102_8_dialog_content = "Solo estamos vigilando a un discapacitado y a un niño, ambos en jaulas. ¿Realmente tienes que estar tan tenso?",
  ui_story_5070_50701102_9_dialog_content = "(¡Tantos piratas! Y en la jaula mecánica... ¿Zhong Xu y Liqing?!)",
  ui_story_5070_50701102_10_dialog_content = "(¿Eh? ¿Qué está haciendo Liqing?)",
  ui_story_5070_50701102_11_dialog_content = "*Olfatea...*",
  ui_story_5070_50701102_12_dialog_content = "(¡Esto huele como... PlayerName!)",
  ui_story_5070_50701102_13_dialog_content = "(¡Aquí! ¡Mira por aquí—! ¡Nuestras miradas se cruzaron!)",
  ui_story_5070_50701102_14_dialog_content = "Miau...",
  ui_story_5070_50701102_15_dialog_content = "¿Qué estás haciendo? ¿Intentando maullar como un gato?",
  ui_story_5070_50701102_16_dialog_content = "Estoy aburrido. No puedes dejarme salir a caminar ahora, ¿verdad?",
  ui_story_5070_50701102_17_dialog_content = "(¿Qué significa Liqing?)",
  ui_story_5070_50701102_18_dialog_content = "Miau...",
  ui_story_5070_50701102_19_dialog_content = "(¡Tinytail! Y junto a Zhong Xu... Son Yixin, Yimeng y Yinuo, ¿verdad?)",
  ui_story_5070_50701102_20_dialog_content = "(¿De dónde vienen?)",
  ui_story_5070_50701102_21_dialog_content = "¿Lo oyes?! ¿Está pasando algo en la puerta?",
  ui_story_5070_50701102_22_dialog_content = "Nah, probablemente escuchaste mal.",
  ui_story_5070_50701102_23_dialog_content = "Primero, dijiste que el cojo pelirrojo te parecía familiar, y ahora dices que algo está pasando en la puerta. Vamos, ¿puedes darme un respiro?",
  ui_story_5070_50701102_24_dialog_content = "Iré a comprobarlo.",
  ui_story_5070_50701102_25_dialog_content = "(!!!)",
  ui_story_5070_50701102_26_dialog_content = "(No hay tiempo para esconderme. ¡Solo tengo una oportunidad en esto!)",
  ui_story_5070_50701102_27_dialog_content = "Por favor, ¡ayúdame a ganar algo de tiempo!",
  ui_story_5070_50701102_28_dialog_content = "¡Miau!",
  ui_story_5070_50701102_29_dialog_content = "¡¿Qué es eso?!",
  ui_story_5070_50701102_30_dialog_content = "¿De dónde diablos salió este gato salvaje? ¡Piérdete! Sisea... ¡y realmente muerde!",
  ui_story_5070_50701102_31_dialog_content = "(Ahora es el momento, para todos en la habitación...)",
  ui_story_5070_50701102_32_dialog_content = "¡Provócalos con Impulso de Fuerza!",
  ui_story_5070_50701102_33_dialog_content = "Ah, ¿por qué de repente me late la cabeza con dolor?!",
  ui_story_5070_50701102_34_dialog_content = "¡Gato—! ¡Un gato me está arañando la cara!",
  ui_story_5070_50701102_35_dialog_content = "PlayerName¡Rescata a Zhong Xu primero!",
  ui_story_5070_50701102_36_dialog_content = "Miau...",
  ui_story_5070_50701102_37_dialog_content = "¿Trajiste la llave? Gracias, Tinytail.",
  ui_story_5070_50701102_38_dialog_content = "Espera, Zhong Xu. Lo estoy desbloqueando ahora mismo.",
  ui_story_5070_50701102_39_dialog_content = "Gracias, pero no tienes que apresurarte porque estoy bien.",
  ui_story_5070_50701102_40_dialog_content = "Puede que tú no estés preocupado, ¡pero yo sí! ¡Eres muy lento, PlayerName! ¡Lo haré yo!",
  ui_story_5070_50701102_41_dialog_content = "Liqing?! ¿Cómo saliste?",
  ui_story_5070_50701102_42_dialog_content = "¡Las aberturas de esta jaula son enormes! ¿No puedes simplemente pasar de lado?!",
  ui_story_5070_50701102_43_dialog_content = "¿Es algo que los aurorianos comunes pueden hacer...?",
  ui_story_5070_50701102_44_dialog_content = "Los aurorianos normales no pueden, pero yo no soy un auroriano común y corriente.",
  ui_story_5070_50701102_45_dialog_content = "¡¿No ordinario?!",
  ui_story_5070_50701102_46_dialog_content = "¿No te lo dije?",
  ui_story_5070_50701102_47_dialog_content = "Soy un gato.",
  ui_story_5070_50701102_48_dialog_content = "¡¿?!",
  ui_story_5070_50701102_49_dialog_content = "Para ser precisos, soy un gato Diablillo. Tinytail allí es mi hermano mayor.",
  ui_story_5070_50701102_50_dialog_content = "H-Hermano...",
  ui_story_5070_50701102_51_dialog_content = "¿PlayerName? ¿Qué ocurre?",
  ui_story_5070_50701102_52_dialog_content = "No hay Fiendlings en Astra, así que entiendo por qué estás tan sorprendido.",
  ui_story_5070_50701102_53_dialog_content = "Zhong Xu...",
  ui_story_5070_50701102_54_dialog_content = "¿Qué es?",
  ui_story_5070_50701102_55_dialog_content = "Tienes tres gatos a tu alrededor, pero... no puedes ser un Diablillo, ¿verdad?",
  ui_story_5070_50701102_56_dialog_content = "¿No te vas a convertir de repente en un gato también?",
  ui_story_5070_50701102_57_dialog_content = "¡Jajaja! Realmente soy solo una persona común, así que me temo que te decepcionará.",
  ui_story_5070_50701102_58_dialog_content = "No, no! Mejor decir que es genial... Y sigue siendo el mismo viejo y confiable Zhong Xu de siempre.",
  ui_story_5070_50701102_59_dialog_content = "Ugh... tú, todos ustedes...",
  ui_story_5070_50701102_60_dialog_content = "PlayerName, estos granujas han vuelto en sí.",
  ui_story_5070_50701102_61_dialog_content = "Y no son solo ellos. Un grupo se acerca a la entrada. Deberían venir de la cubierta.",
  ui_story_5070_50701102_62_dialog_content = "¡Rodéalos!",
  ui_story_5070_50701102_63_dialog_content = "El único luchador capaz aquí es el lisiado, pero solo es hábil con Flame Force Arts.",
  ui_story_5070_50701102_64_dialog_content = "Mientras sofocamos sus llamas, es inútil.",
  ui_story_5070_50701102_65_dialog_content = "¡Estos chicos!",
  ui_story_5070_50701102_66_dialog_content = "Espera, Zhong Xu. Asegúrate de estar a salvo primero, mientras Liqing y yo ideamos un plan.",
  ui_story_5070_50701102_67_dialog_content = "¿Eh? PlayerName, ¿no lo sabías? En realidad...",
  ui_story_5070_50701102_68_dialog_content = "Agradezco tus buenas intenciones.",
  ui_story_5070_50701102_69_dialog_content = "El Lin maestro del gremio... Era débil y frágil, pero siempre me protegía así.",
  ui_story_5070_50701102_70_dialog_content = "He tenido tratos con estas personas durante muchos años, así que supongo que es el destino que me hayan capturado aquí.",
  ui_story_5070_50701102_71_dialog_content = "Tal vez incluso los cielos creen que es hora de que arregle las cosas con estos piratas de una vez por todas.",
  ui_story_5070_50701102_72_dialog_content = "Entonces, ¿puedes esperar un momento y dejarme a mí estos enemigos, por favor?",
  ui_story_5070_50701102_73_dialog_content = "Está bien. Haré lo mejor que pueda para apoyar—",
  ui_story_5070_50701102_74_dialog_content = "Eso no será necesario. Tus extraños poderes probablemente sean más útiles para la Princesa Dantang y la Ministra Armilla.",
  ui_story_5070_50701102_75_dialog_content = "En cuanto a mí, solo conozco una forma de luchar y solo necesito esta única forma de pelear.",
  ui_story_5070_50701102_76_dialog_content = "Si realmente quieres ayudarme, entrégame mi espada que me quitaron antes.",
  ui_story_5070_50701102_77_dialog_content = "Está bien, es este, ¿verdad...? ¡Es pesado!",
  ui_story_5070_50701102_78_dialog_content = "Gracias.",
  ui_story_5070_50701102_79_dialog_content = "(En el instante en que tomó la espada, los ojos de Zhong Xu parecieron cambiar.)",
  ui_story_5070_50701102_80_dialog_content = "Ja, ¿qué está balbuceando este lisiado? ¡Realmente piensa que puede enfrentarnos a todos por sí mismo!?",
  ui_story_5070_50701102_81_dialog_content = "Está metido en algo que le queda grande—",
  ui_story_5070_50701102_82_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5070_50701102_83_dialog_content = "Oh...",
  ui_story_5070_50701102_84_dialog_content = "<color=#e8d9bb>La sonrisa arrogante aún no había desaparecido de su rostro, pero el cuerpo del pirata ya había caído al suelo.</color>",
  ui_story_5070_50701102_85_dialog_content = "¿Qué... qué acaba de hacer él?",
  ui_story_5070_50701102_86_dialog_content = "¡No entren en pánico! ¡Él es solo rápido con su espada! Somos tantos—¡Ah!",
  ui_story_5070_50701102_87_dialog_content = "En lugar de darme este cumplido inapropiado, preferiría que simplemente te cayeras.",
  ui_story_5070_50701102_88_dialog_content = "¡Oye! ¿Quién dijo que todo estaría bien siempre y cuando controlemos su fuego?",
  ui_story_5070_50701102_89_dialog_content = "Este chico... ¡Ni siquiera usó su fuego en absoluto!",
  ui_story_5070_50701102_90_dialog_content = "El impulso de los piratas fue suprimido por Zhong Xu en solitario.",
  ui_story_5070_50701102_91_dialog_content = "Por supuesto, estamos hablando de Zhong Xu aquí!",
  ui_story_5070_50701102_92_dialog_content = "¡Ve... VETE AL INFIERNO!",
  ui_story_5070_50701102_93_dialog_content = "Zhong Xu! ¡Detrás de ti!",
  ui_story_5070_50701102_94_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5070_50701102_95_dialog_content = "¡Ahhh!",
  ui_story_5070_50701102_96_dialog_content = "Mi preocupación fue en vano, ya que Zhong Xu sacó su espada más rápido de lo que pude gritar.",
  ui_story_5070_50701102_97_dialog_content = "¿Ves? Incluso en una silla de ruedas, este grupo de desaliñados no es nada para Zhong Xu.",
  ui_story_5070_50701102_98_dialog_content = "El naufragio me arrebató las piernas.",
  ui_story_5070_50701102_99_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5070_50701102_100_dialog_content = "Y también puedes intentar suprimir mis llamas ardientes.",
  ui_story_5070_50701102_101_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5070_50701102_102_dialog_content = "Pero mientras aún tenga un brazo y una espada.",
  ui_story_5070_50701102_103_dialog_content = "<color=#e8d9bb>¡Silbido!</color>",
  ui_story_5070_50701102_104_dialog_content = "Continuaré blandiendo mi espada y matando enemigos.",
  ui_story_5070_50701102_105_dialog_content = "Esta es la única forma de luchar que conozco.",
  ui_story_5070_50701102_106_dialog_content = "Monstruo... ¡Un maldito monstruo—!",
  ui_story_5070_50701102_107_dialog_content = "Hace muchos años, la gente solía llamarme así.",
  ui_story_5070_50701102_108_dialog_content = "Tú... Espera, no me digas...",
  ui_story_5070_50701102_109_dialog_content = "¡Ahora recuerdo!",
  ui_story_5070_50701102_110_dialog_content = "Cabello rojo y una túnica larga.",
  ui_story_5070_50701102_111_dialog_content = "Con solo una espada, puede eliminar a un barco lleno de piratas con una sola mano.",
  ui_story_5070_50701102_112_dialog_content = "El general que acabó con el último grupo de piratas que dominaban las aguas alrededor del Reino Ji... ¡eres tú!",
  ui_story_5070_50701102_113_dialog_content = "¡El Gran General personalmente honrado por el Emperador!",
  ui_story_5070_50701102_114_dialog_content = "Eso ya es cosa del pasado.",
  ui_story_5070_50701102_115_dialog_content = "<color=#e8d9bb>Chasquido—</color>",
  ui_story_5070_50701102_116_dialog_content = "<color=#e8d9bb>El último enemigo cae al suelo.</color>",
  ui_story_5070_50701102_117_dialog_content = "Ahora solo soy un errante...",
  ui_story_5070_50701102_118_dialog_content = "O un hombre de mediana edad que pueda brindar ayuda a los jóvenes.",
  ui_story_5070_50701201_1_dialog_content = "<color=#e8d9bb>Mientras tanto, en la nave enemiga</color>",
  ui_story_5070_50701201_2_dialog_content = "(¿Este barco está construido como el Shadowind?!)",
  ui_story_5070_50701201_3_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5070_50701201_4_dialog_content = "!",
  ui_story_5070_50701201_5_dialog_content = "Debería sentirme honrado de ser saludado de tal manera.",
  ui_story_5070_50701201_6_dialog_content = "Es obviamente un aguijón de escorpión, pero no está disparando toxinas...",
  ui_story_5070_50701201_7_dialog_content = "¿Pero el rayo de Lumina del pueblo Astra?",
  ui_story_5070_50701201_8_dialog_content = "¡Graagh!",
  ui_story_5070_50701201_9_dialog_content = "La cola es una lanza, las pinzas son cuchillas, con un caparazón grueso de metal...",
  ui_story_5070_50701201_10_dialog_content = "¡Activación completa!",
  ui_story_5070_50701201_11_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  ui_story_5070_50701201_12_dialog_content = "Suena como piedra pero ligero como jade.",
  ui_story_5070_50701201_13_dialog_content = "No hay señales de daño por el bombardeo. Supongo que está hecho de materiales raros.",
  ui_story_5070_50701201_14_dialog_content = "Ya sabes...",
  ui_story_5070_50701201_15_dialog_content = "Click-clack...",
  ui_story_5070_50701201_16_dialog_content = "Esta cosa debe consumir mucha energía.",
  ui_story_5070_50701201_17_dialog_content = "Pero no se ha debilitado y, después de todas estas peleas, incluso se ha vuelto más fuerte.",
  ui_story_5070_50701201_18_dialog_content = "Qué increíble debe ser su núcleo... No puede haber más que unos pocos en el mundo.",
  ui_story_5070_50701201_19_dialog_content = "Qué coincidencia, que haya otro en Shadowind.",
  ui_story_5070_50701201_20_dialog_content = "Si desmonto a este monstruo, ¿encontraré la fuente de energía...?",
  ui_story_5070_50701201_21_dialog_content = "¿Ser otra Llama Zhuyin?",
  ui_story_5070_50701201_22_dialog_content = "Probablemente ni siquiera puedas romperlo.",
  ui_story_5070_50701201_23_dialog_content = "Ah, finalmente te muestras.",
  ui_story_5070_50701201_24_dialog_content = "Primero, te hiciste pasar por Sun, luego enviaste a este grandulón feo a por mí.",
  ui_story_5070_50701201_25_dialog_content = "Empezaba a pensar que solo hacías cosas cuando tenías algo detrás de lo cual esconderte.",
  ui_story_5070_50701201_26_dialog_content = "Je, no me molestaré en discutir contigo.",
  ui_story_5070_50701201_27_dialog_content = "Después de todo, las palabras afiladas del perdedor solo significan impotencia.",
  ui_story_5070_50701201_28_dialog_content = "¿Perdedor? Lo tienes al revés.",
  ui_story_5070_50701201_29_dialog_content = "La razón es que estabas seguro de tu inferioridad y te convenciste a ti mismo de que eras el perdedor.",
  ui_story_5070_50701201_30_dialog_content = "Planeaste y maquinaste para obtener lo que pertenecía a otras personas.",
  ui_story_5070_50701201_31_dialog_content = "Tú primero robaste el plano del Cangrejo de Fuego.",
  ui_story_5070_50701201_32_dialog_content = "Luego pasaron a contrabandear piezas y llevaron a los piratas a saquear al comerciante Lin.",
  ui_story_5070_50701201_33_dialog_content = "Ahora usaste el mismo truco para robar la Llama Zhuyin para tu grotesco trabajo de remiendo.",
  ui_story_5070_50701201_34_dialog_content = "Aunque tengo una pregunta.",
  ui_story_5070_50701201_35_dialog_content = "Vamos a oírlo.",
  ui_story_5070_50701201_36_dialog_content = "Qianyun siempre ha sentido orgullo de ser recto y tener una reputación intachable.",
  ui_story_5070_50701201_37_dialog_content = "Entonces, ¿cuándo promovió el robo y tácticas encubiertas como esta?",
  ui_story_5070_50701201_38_dialog_content = "Ja...",
  ui_story_5070_50701201_39_dialog_content = "Oh, me has reconocido.",
  ui_story_5070_50701201_40_dialog_content = "Pero todo lo que te importa siempre es la mecánica. Me pregunto si mi cara aún te suena.",
  ui_story_5070_50701201_41_dialog_content = "Ha pasado un tiempo, Xuan Ji... mi hermana menor.",
  ui_story_5070_50701201_42_dialog_content = "Zhui Hu.",
  ui_story_5070_50701201_43_dialog_content = "Ni siquiera puedes llamarme \"hermana mayor\", ¿eh? La ilustre Ministra Armilla es, de hecho, diferente al pasado.",
  ui_story_5070_50701201_44_dialog_content = "Hace mucho que te expulsaron y no eres apto para llamarte a ti mismo nada.",
  ui_story_5070_50701201_45_dialog_content = "Je, palabras afiladas de nuevo... ¿Sabes qué? Dejaré que pase esta vez.",
  ui_story_5070_50701201_46_dialog_content = "Después de todo, has sido considerado un genio por la secta desde la infancia, siempre teniendo las cosas a tu favor. Pero ahora, no tienes forma de manejar las obras de un discípulo abandonado...",
  ui_story_5070_50701201_47_dialog_content = "Debe picar un poco.",
  ui_story_5070_50701201_48_dialog_content = "Pero está bien. Aunque a ti no te importen nuestros viejos tiempos, a mí sí.",
  ui_story_5070_50701201_49_dialog_content = "Entonces, dado nuestro pasado compartido al crecer en la secta, si admites honestamente tu derrota, estoy dispuesto a dejarte ir.",
  ui_story_5070_50701201_50_dialog_content = "Hermana menor, quizás no lo sepas... ¡pero la era de los estrategas está a punto de comenzar!",
  ui_story_5070_50701201_51_dialog_content = "En el siempre cambiante panorama político de los ocho reinos vasallos en el futuro, talentos como tú siempre encontrarán un punto de apoyo.",
  ui_story_5070_50701201_52_dialog_content = "Esta nave bajo tus pies. Considérala mi regalo de despedida para ti. ¿Qué te parece?",
  ui_story_5070_50701201_53_dialog_content = "Por supuesto.",
  ui_story_5070_50701201_54_dialog_content = "No solo buscas la Llama Zhuyin, sino también el Shadowind.",
  ui_story_5070_50701201_55_dialog_content = "Pero no pensé que simplemente me dejarías a la deriva en el mar para morir.",
  ui_story_5070_50701201_56_dialog_content = "Realmente, no puedo ocultar nada de tus perspicaces ojos.",
  ui_story_5070_50701201_57_dialog_content = "Ya que este barco es una copia del Shadowind, aunque solo en apariencia y en ningún aspecto comparable.",
  ui_story_5070_50701201_58_dialog_content = "Después de todo, el núcleo de Shadowind fue creado mediante los esfuerzos combinados de muchos expertos. Es difícil para mí replicarlo solo.",
  ui_story_5070_50701201_59_dialog_content = "En realidad, mi misión original era simplemente adquirir los planos del Shadowind.",
  ui_story_5070_50701201_60_dialog_content = "Pero ya que hay una oportunidad de tomar todo el barco, ¿por qué no?",
  ui_story_5070_50701201_61_dialog_content = "Aunque el actual Shadowind está desordenado debido a tus caprichosas modificaciones...",
  ui_story_5070_50701201_62_dialog_content = "Pero no me importa enfrentarme a este lío.",
  ui_story_5070_50701201_63_dialog_content = "(Misión, dijiste...)",
  ui_story_5070_50701201_64_dialog_content = "Comparado con charlar con esos jóvenes locales tercos en la mazmorra, esta forma de hacer las cosas es mucho más satisfactoria.",
  ui_story_5070_50701201_65_dialog_content = "Entonces, ¿también planeaste el robo del barco Lin?",
  ui_story_5070_50701201_66_dialog_content = "Eres rápido para captar, ¿verdad?",
  ui_story_5070_50701201_67_dialog_content = "Con esta técnica conveniente de disfraz y mimetismo...",
  ui_story_5070_50701201_68_dialog_content = "Era pan comido hacerse pasar por un pasajero o un trabajador del barco y derribar las defensas del barco desde adentro.",
  ui_story_5070_50701201_69_dialog_content = "He hecho preparativos meticulosos en Twin Pavilions Bay, con la esperanza de recrear lo que sucedió en el Shadowind...",
  ui_story_5070_50701201_70_dialog_content = "Hasta que descubrí que había algo especial escondido en la cabina.",
  ui_story_5070_50701201_71_dialog_content = "Nunca esperé que tú, mi querida hermana menor, pudieras encontrar realmente la legendaria Llama Zhuyin.",
  ui_story_5070_50701201_72_dialog_content = "Y desde que creé esta bestia mecánica, una creación cumbre que incorpora las fortalezas de todas las escuelas, no he podido encontrar una fuente de energía adecuada.",
  ui_story_5070_50701201_73_dialog_content = "Puede parecer una coincidencia, ¡pero para mí, es el favor del destino!",
  ui_story_5070_50701201_74_dialog_content = "Suspiro...",
  ui_story_5070_50701201_75_dialog_content = "... ¿Qué quieres decir con eso?",
  ui_story_5070_50701201_76_dialog_content = "Nunca has cambiado.",
  ui_story_5070_50701201_77_dialog_content = "En este punto, ¿por qué sigues intentando actuar como el genio de nuestra secta y el maestro de la maquinaria?",
  ui_story_5070_50701201_78_dialog_content = "¿Aún no te has enfrentado a la realidad, hermana menor?",
  ui_story_5070_50701201_79_dialog_content = "¡Ni siquiera tú puedes dejar un rasguño en mi bestia mecánica, mi mayor creación!",
  ui_story_5070_50701201_80_dialog_content = "\"¿Tu\" bestia mecánica?",
  ui_story_5070_50701201_81_dialog_content = "Simplemente copiaste el diseño, robaste el núcleo y juntaste piezas poderosas.",
  ui_story_5070_50701201_82_dialog_content = "¿Hay algo original en esa obra \"tuya\"?",
  ui_story_5070_50701201_83_dialog_content = "¿Por qué suenas igual que esos viejos rígidos de la secta?",
  ui_story_5070_50701201_84_dialog_content = "El arte de la maquinaria es solo una habilidad técnica; siempre que la creación en sí sea lo suficientemente sólida, no hay necesidad de preocuparse por nada más.",
  ui_story_5070_50701201_85_dialog_content = "Incluso si son ellos, ante mi Stinger perfeccionado, ¡no tendrán más remedio que inclinarse en derrota!",
  ui_story_5070_50701201_86_dialog_content = "Por eso nuestros maestros dijeron que nunca entendiste el significado de los artilugios.",
  ui_story_5070_50701201_87_dialog_content = "Si te ven ahora, probablemente lamentarán el hecho de que no puedan echarte por segunda vez.",
  ui_story_5070_50701201_88_dialog_content = "...No debí haber perdido tanto tiempo intentando hacerte entrar en razón.",
  ui_story_5070_50701201_89_dialog_content = "Aplástala, Stinger. ¡Muéstrale el verdadero poder que debe tener una Bestia Mecánica!",
  ui_story_5070_50701201_90_dialog_content = "Finalmente hemos lidiado con los piratas en el Shadowind. ¿Todos están bien?",
  ui_story_5070_50701201_91_dialog_content = "Básicamente estamos bien, pero algunos de nuestros carpinteros de barcos están heridos y algunos de nuestros pasajeros están desaparecidos.",
  ui_story_5070_50701201_92_dialog_content = "Jiu cayó por la borda debido a sus heridas y aún no hay señales de ella...",
  ui_story_5070_50701201_93_dialog_content = "¡Su Alteza! ¿Está bien?",
  ui_story_5070_50701201_94_dialog_content = "Jiu! ¿Por qué te preocupas por mí? ¿Cuánto te has lastimado?",
  ui_story_5070_50701201_95_dialog_content = "Acabo de tragar accidentalmente unos cuantos tragos de agua.",
  ui_story_5070_50701201_96_dialog_content = "Pero fallé en mi deber como tu guardaespaldas al dejarte en este momento. Por favor, castígame.",
  ui_story_5070_50701201_97_dialog_content = "Basta. Podrías haber esquivado el rayo si no fuera por protegerme...",
  ui_story_5070_50701201_98_dialog_content = "¿Cómo puedo siquiera regañarte? Ven a examinar Jiu, Liqing...",
  ui_story_5070_50701201_99_dialog_content = "Gracias.",
  ui_story_5070_50701201_100_dialog_content = "Con Jiu de vuelta, solo queda la Ministra Armilla...",
  ui_story_5070_50701201_101_dialog_content = "Xuan Ji probablemente esté en ese barco de enfrente.",
  ui_story_5070_50701201_102_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50701201_103_dialog_content = "Ese brillo peculiar otra vez...",
  ui_story_5070_50701201_104_dialog_content = "Bien, veamos.",
  ui_story_5070_50701201_105_dialog_content = "¿Contra qué está peleando? ¿Por qué solo esquiva sin contraatacar?!",
  ui_story_5070_50701201_106_dialog_content = "¡No puedo soportar esto más! Zhong Xu, ayudémosla un poco.",
  ui_story_5070_50701201_107_dialog_content = "Si la salvo justo a tiempo, ¡ella estaría demasiado avergonzada para volver a llamarme pequeño!",
  ui_story_5070_50701201_108_dialog_content = "Quizás no sea necesario.",
  ui_story_5070_50701201_109_dialog_content = "De ninguna manera... ¿También te ofendió ella? ¿Realmente planeas dejar que muera?",
  ui_story_5070_50701201_110_dialog_content = "Lo que quiero decir es que la Ministra Armilla no necesita nuestra ayuda.",
  ui_story_5070_50701201_111_dialog_content = "Sí. No parecía estar corriendo por todas partes solo para esconderse.",
  ui_story_5070_50701201_112_dialog_content = "Creo que ella estaba usando intencionalmente los ataques del lado contrario para destrozar su entorno.",
  ui_story_5070_50701201_113_dialog_content = "¡Quiero destruir el refugio de esa Bestia Mecánica!",
  ui_story_5070_50701201_114_dialog_content = "Pero, ¿por qué haría eso?",
  ui_story_5070_50701201_115_dialog_content = "No sé... En realidad, tal vez sí lo sé.",
  ui_story_5070_50701201_116_dialog_content = "Entonces, incluso si refuerzas Shadowind con todos los materiales que puedas encontrar...",
  ui_story_5070_50701201_117_dialog_content = "No va a resistir la Llama Zhuyin a máxima potencia.",
  ui_story_5070_50701201_118_dialog_content = "Ignorar el gran agujero en la cubierta es una cosa, ¿pero agrandarlo a propósito?",
  ui_story_5070_50701201_119_dialog_content = "Casi está exponiendo el núcleo de Shadowind. Eso es demasiado extraño... Sol, ¿qué opinas al respecto?",
  ui_story_5070_50701201_120_dialog_content = "Por favor, mantén en secreto el experimento fallido y a alguien vigilando la Llama.",
  ui_story_5070_50701201_121_dialog_content = "Tal vez... Pero, ¿qué debemos hacer ahora?",
  ui_story_5070_50701201_122_dialog_content = "Solo espera.",
  ui_story_5070_50701201_123_dialog_content = "(...De ninguna manera.)",
  ui_story_5070_50701201_124_dialog_content = "(Si es lo que creo que es, Xuan Ji, ya no tienes derecho a llamarme imprudente.)",
  ui_story_5070_50701201_125_dialog_content = "(¡Serías el más temerario a bordo!)",
  ui_story_5070_50701201_126_dialog_content = "¿Qué estás mirando, PlayerName? ¿Hay algo dentro de ese enorme agujero en la cubierta?",
  ui_story_5070_50701201_127_dialog_content = "No ahora.",
  ui_story_5070_50701201_128_dialog_content = "Pero será inminentemente.",
  ui_story_5070_50701201_129_dialog_content = "¡Todos! ¡Échenme una mano!",
  ui_story_5070_50701201_130_dialog_content = "¡Necesitamos atraer a esas Bestias Mecánicas al Shadowind!",
  ui_story_5070_50701201_131_dialog_content = "Destello de relámpago—",
  ui_story_5070_50701201_132_dialog_content = "Te dije que era inútil, ¿no?",
  ui_story_5070_50701201_133_dialog_content = "Cada parte de Stinger está elaborada con los diseños de primera calidad que encontré en todo el mundo.",
  ui_story_5070_50701201_134_dialog_content = "¡Todos tus ataques son inútiles!",
  ui_story_5070_50701201_135_dialog_content = "No estoy seguro de eso.",
  ui_story_5070_50701201_136_dialog_content = "¡¿?!",
  ui_story_5070_50701201_137_dialog_content = "PlayerName? Si puedes enlazar mentalmente conmigo, debes haberlo hecho bien de tu lado.",
  ui_story_5070_50701201_138_dialog_content = "Jaja... Gracias, Zhong Xu. Pero podemos discutir esto más tarde.",
  ui_story_5070_50701201_139_dialog_content = "Escuché lo que decías hace un momento. Resulta que la explosión de ese día fue causada por este impostor Sol el Hábil.",
  ui_story_5070_50701201_140_dialog_content = "Golpeado por un rayo por robar. La gente de Longzhou diría que eso es una retribución divina.",
  ui_story_5070_50701201_141_dialog_content = "¿Ella realmente cree que es el destino? No quisiera ese tipo de rayo.",
  ui_story_5070_50701201_142_dialog_content = "¡Yo tampoco!",
  ui_story_5070_50701201_143_dialog_content = "Además, su bestia mecánica es demasiado fea. ¡Todo ese retorcimiento es simplemente repugnante!",
  ui_story_5070_50701201_144_dialog_content = "Dije que era un gran y feo desastre.",
  ui_story_5070_50701201_145_dialog_content = "... Nunca pensé que el Shadowind sería comparado con algo así.",
  ui_story_5070_50701201_146_dialog_content = "... ¡Eso es suficiente!",
  ui_story_5070_50701201_147_dialog_content = "¡Stinger! ¡Dirígete a Shadowind y acaba con todos estos ignorantes!",
  ui_story_5070_50701202_1_dialog_content = "Mi... bestia mecánica más poderosa... ¿Cómo pudo pasar esto...",
  ui_story_5070_50701202_2_dialog_content = "Tú—!",
  ui_story_5070_50701202_3_dialog_content = "¿Vas a seguir así? No recuerdo que fueras un buen luchador.",
  ui_story_5070_50701202_4_dialog_content = "Ja... Jaja, ¡jajaja!",
  ui_story_5070_50701202_5_dialog_content = "¡No te emociones demasiado aún! Hermana mayor, no deberías haber olvidado qué poderes tiene mi Aguijón, ¿verdad?",
  ui_story_5070_50701202_6_dialog_content = "¡Llama Zhuyin! Es el verdadero arte de la artesanía que proporciona energía infinita a las creaciones mecánicas.",
  ui_story_5070_50701202_7_dialog_content = "¡Levántate, Stinger! ¡La batalla aún no ha terminado!",
  ui_story_5070_50701202_8_dialog_content = "¡Cuidado, todos! ¡El grandote se está moviendo de nuevo!",
  ui_story_5070_50701202_9_dialog_content = "Entonces las cosas aún no han terminado. Su Alteza, por favor, retroceda.",
  ui_story_5070_50701202_10_dialog_content = "Eres tú el que celebra prematuramente.",
  ui_story_5070_50701202_11_dialog_content = "Esa mirada otra vez... ¡No me mires nunca más con esa superioridad! Yo—",
  ui_story_5070_50701202_12_dialog_content = "PlayerName, ¡intenta mantenerla quieta! ¡Solo necesito un poco de tiempo!",
  ui_story_5070_50701202_13_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50701202_14_dialog_content = "Puaj-!",
  ui_story_5070_50701202_15_dialog_content = "La haré marearse brevemente, ¡y ustedes empujen a la bestia adentro ahora!",
  ui_story_5070_50701202_16_dialog_content = "¿Empujarlo? ¿Empujarlo a dónde? ¿Al agujero en la cubierta?!",
  ui_story_5070_50701202_17_dialog_content = "No es solo un agujero.",
  ui_story_5070_50701202_18_dialog_content = "Lo hice especialmente para eso.",
  ui_story_5070_50701202_19_dialog_content = "¡Uno... Dos... Tres!",
  ui_story_5070_50701202_20_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5070_50701202_21_dialog_content = "¡Lo hicimos! Ese tipo era realmente pesado.",
  ui_story_5070_50701202_22_dialog_content = "Tomaré el control desde aquí.",
  ui_story_5070_50701202_23_dialog_content = "Con algunas modificaciones, podemos conectarlo al Shadowind.",
  ui_story_5070_50701202_24_dialog_content = "Ugh... ¡¿Q-qué vas a hacer...?!",
  ui_story_5070_50701202_25_dialog_content = "Estoy seguro de que viste mi borrador de cambios para el Shadowind en tu disfraz de Sol, ¿verdad?",
  ui_story_5070_50701202_26_dialog_content = "No bromees... Ni siquiera es posible...",
  ui_story_5070_50701202_27_dialog_content = "Para sostener un barco de gran tamaño como Shadowind con una estructura así...",
  ui_story_5070_50701202_28_dialog_content = "Requiere un núcleo con el mismo nivel de potencia que la Llama Zhuyin a máxima velocidad.",
  ui_story_5070_50701202_29_dialog_content = "Con los materiales del Shadowind solamente, ni siquiera puede resistir el impacto...",
  ui_story_5070_50701202_30_dialog_content = "Tienes razón, es un sueño irrealizable solo con eso.",
  ui_story_5070_50701202_31_dialog_content = "Pero para crear la bestia mecánica más poderosa...",
  ui_story_5070_50701202_32_dialog_content = "¿No utilizaste materiales que pudieran resistir la Llama Zhuyin a máxima potencia?",
  ui_story_5070_50701202_33_dialog_content = "Espera, ¿quieres decir... Estás loco?! Es absolutamente...",
  ui_story_5070_50701202_34_dialog_content = "Por eso dije que estás demasiado ocupado con los diseños como para entender la tecnología.",
  ui_story_5070_50701202_35_dialog_content = "Mientras haya materiales disponibles, la tecnología no tiene límites en lo que puede crear.",
  ui_story_5070_50701202_36_dialog_content = "¿De qué estás hablando?",
  ui_story_5070_50701202_37_dialog_content = "Quédate quieto, pequeño. Pronto lo descubrirás.",
  ui_story_5070_50701202_38_dialog_content = "Sumérgete con todos tus sentidos en esta experiencia única en la vida.",
  ui_story_5070_50701202_39_dialog_content = "Estoy a punto de usar la bestia como fuente de energía para regular la producción de la Llama Zhuyin.",
  ui_story_5070_50701202_X39_dialog_content = "Y haz que el Shadowind...",
  ui_story_5070_50701202_40_dialog_content = "¡Toma un vuelo corto!",
  ui_story_5070_50701202_41_dialog_content = "<color=#e8d9bb>Explosión de silbato</color>",
  ui_story_5070_50701202_42_dialog_content = "<color=#e8d9bb>Bajo el mando de Xuan Ji, aquellos que aún pueden moverse asumen temporalmente las funciones de los carpinteros de barcos.</color>",
  ui_story_5070_50701202_43_dialog_content = "<color=#e8d9bb>Con el sonido del silbato, todos los mecanismos modificados en Shadowind se activan al mismo tiempo.</color>",
  ui_story_5070_50701202_44_dialog_content = "<color=#e8d9bb>El barco se sacude, los engranajes en su interior chocan y se extienden... ¡Rayos de Lumina se despliegan a ambos lados de la nave como una multitud de alas!</color>",
  ui_story_5070_50701202_45_dialog_content = "¿Harías el honor, PlayerName?",
  ui_story_5070_50701202_46_dialog_content = "¡Potencia de fuerza!",
  ui_story_5070_50701202_47_dialog_content = "(¡Siente la Llama Zhuyin y estimula su poder al máximo! ¡Y luego...)",
  ui_story_5070_50701202_48_dialog_content = "(¡Shadowind, muévete!)",
  ui_story_5070_50701202_49_dialog_content = "De ninguna manera... ¡De ninguna maldita manera!",
  ui_story_5070_50701202_50_dialog_content = "¡Rayos... es solo un golpe momentáneo de suerte! Nosotros... ¡aún no ha terminado!",
  ui_story_5070_50701202_51_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5070_50701202_52_dialog_content = "¡Saltó al mar!",
  ui_story_5070_50701202_53_dialog_content = "No te preocupes por ella.",
  ui_story_5070_50701202_54_dialog_content = "Las alas solo pueden sostener el barco por un tiempo limitado. Tenemos que aprovechar esta oportunidad y salir de aquí.",
  ui_story_5070_50701202_55_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5070_50701202_56_dialog_content = "(El Shadowind solo permaneció en el aire brevemente, y ya podía escuchar el sonido de la maquinaria sobrecargada.)",
  ui_story_5070_50701202_57_dialog_content = "(Con un último empujón, la intensa luz comenzó a disiparse en el aire.)",
  ui_story_5070_50701202_58_dialog_content = "(Eso servirá.)",
  ui_story_5070_50701202_59_dialog_content = "El sol, una ligera brisa y olas tranquilas... ¡Salimos!",
  ui_story_5070_50701202_60_dialog_content = "<color=#e8d9bb>¡¡¡Estallido!!!</color>",
  ui_story_5070_50701202_61_dialog_content = "<color=#e8d9bb>El Shadowind cae pesadamente de nuevo en el mar.</color>",
  ui_story_5070_50701202_62_dialog_content = "<color=#e8d9bb>Pero esta vez, el entorno está tranquilo, sin más remolinos ni corrientes ocultas.</color>",
  ui_story_5070_50701202_63_dialog_content = "¡Lo hicimos!",
  ui_story_5070_50701202_64_dialog_content = "¡Eres increíble, Xuan Ji!",
  ui_story_5070_50701202_65_dialog_content = "Es un artilugio genial.",
  ui_story_5070_50701202_66_dialog_content = "Pero esta vez, dejaré de lado la humildad y aceptaré tu cumplido.",
  ui_story_5070_50701202_67_dialog_content = "Hablando de eso, aunque no haya durado mucho, el Shadowind de hecho surcó el cielo.",
  ui_story_5070_50701202_68_dialog_content = "Y esta vez, Xuan Ji se había convertido legítimamente en el navegante del Shadowind.",
  ui_story_5070_50701202_69_dialog_content = "Lo hice, ¿verdad?",
  ui_story_5070_50701202_70_dialog_content = "Nunca olvidaré esa sensación.",
  ui_story_5070_50701202_71_dialog_content = "(Después de cruzar el océano, Xuan Ji rápidamente utilizó el astrolabio y otros equipos para ayudar a Shadowind a retomar su rumbo.)",
  ui_story_5070_50701202_72_dialog_content = "(Al día siguiente, encontramos los restos del barco de Zhui Hu no muy lejos de allí.)",
  ui_story_5070_50701202_73_dialog_content = "Se hundió en el mar, al igual que el barco de Lin Guild que se hundió debido a sus intrigas. Aquí hay causa y efecto en juego.",
  ui_story_5070_50701202_74_dialog_content = "Pero personas como Zhui Hu y sus seguidores no morirán tan fácilmente. Tampoco se rendirán tan fácilmente.",
  ui_story_5070_50701202_75_dialog_content = "Nadie sabe qué otros planes idearán.",
  ui_story_5070_50701202_76_dialog_content = "De todos modos, encontraremos una forma de lidiar con ello. Siempre hay un contraataque para cualquier tipo de enemigo.",
  ui_story_5070_50701202_77_dialog_content = "Aun así, podemos improvisar en el momento.",
  ui_story_5070_50701202_78_dialog_content = "¿No fue Zhui Hu tu maestro alguna vez, Xuan Ji?",
  ui_story_5070_50701202_79_dialog_content = "Incluso si fue expulsado, al menos había sido discípulo de una gran secta.",
  ui_story_5070_50701202_80_dialog_content = "Tenía que ser mucho más fuerte que las personas normales para idear algo así.",
  ui_story_5070_50701202_81_dialog_content = "¿Cómo pudo ser contratado para actuar como pirata o contrabandista?",
  ui_story_5070_50701202_82_dialog_content = "Tengo una idea.",
  ui_story_5070_50701202_83_dialog_content = "Pero no sé si es bueno o malo seguir esa línea de pensamiento.",
  ui_story_5070_50701202_84_dialog_content = "Zhui Hu aprendió muchas técnicas, pero nunca se dio cuenta de lo que realmente es la tecnología de gadgets.",
  ui_story_5070_50701202_85_dialog_content = "Estamos hablando del resultado de siglos de práctica y determinación.",
  ui_story_5070_50701202_86_dialog_content = "Eso no puede ser comprendido a través de subterfugios y robos.",
  ui_story_5070_50701202_87_dialog_content = "Traje todo lo que pediste, Xuan Ji.",
  ui_story_5070_50701202_88_dialog_content = "Pero solo nos quedan estos pocos sobres para comunicarnos con mi tío abuelo en este barco.",
  ui_story_5070_50701202_89_dialog_content = "¿Cuál es el propósito que tienes para ellos?",
  ui_story_5070_50701202_90_dialog_content = "Bueno, lo averiguaré cuando los vea.",
  ui_story_5070_50701202_91_dialog_content = "Oh, ¿cómo está Jiu?",
  ui_story_5070_50701202_92_dialog_content = "Veo que todavía te importa.",
  ui_story_5070_50701202_93_dialog_content = "Liqing la examinó y debería recuperarse completamente en unos días.",
  ui_story_5070_50701202_94_dialog_content = "(El tono de la conversación volvió a su habitual ligereza y vivacidad.)",
  ui_story_5070_50701202_95_dialog_content = "(Vi a Xuan Ji guardar cuidadosamente esas cartas...)",
  ui_story_5070_50701202_X95_dialog_content = "(Aunque nunca respondió a la pregunta, \"¿Cuál es el propósito?\".)",
  ui_story_5070_50701301_1_dialog_content = "(Los últimos dos días a bordo del barco pasaron volando.)",
  ui_story_5070_50701301_2_dialog_content = "(Todos estaban física y mentalmente agotados por todas las crisis y batallas.)",
  ui_story_5070_50701301_3_dialog_content = "(Afortunadamente, justo cuando se completaron las reparaciones, Longzhou apareció a la vista.)",
  ui_story_5070_50701301_4_dialog_content = "Este viaje estuvo lleno de giros y vueltas, pero todo salió bien.",
  ui_story_5070_50701301_5_dialog_content = "El Shadowind ha regresado. Este viaje ha terminado oficialmente.",
  ui_story_5070_50701301_6_dialog_content = "En nombre de Shadowind, quiero agradecer a todos por ayudarnos en el camino.",
  ui_story_5070_50701301_7_dialog_content = "No pases por alto tus propios méritos en esto.",
  ui_story_5070_50701301_8_dialog_content = "Llegamos a salvo y restablecimos la ruta. Nosotros y el Shadowind hemos completado nuestras misiones.",
  ui_story_5070_50701301_9_dialog_content = "Princesa Dantang, alguien acaba de enviar un mensaje de que el enviado del Reino Ji está esperando en el puerto para escoltarla de regreso al palacio.",
  ui_story_5070_50701301_10_dialog_content = "Tengo toda la información, así que debo informar lo más pronto posible.",
  ui_story_5070_50701301_11_dialog_content = "Veo una serie de reuniones y banquetes en un futuro cercano.",
  ui_story_5070_50701301_12_dialog_content = "También tendrás que estar listo, PlayerName.",
  ui_story_5070_50701301_13_dialog_content = "¿Eh? ¿Yo?",
  ui_story_5070_50701301_14_dialog_content = "¡Oh sí! ¡Olvidé por completo que he venido a Longzhou como enviado de Astra!",
  ui_story_5070_50701301_15_dialog_content = "¿Q-Qué hago? De repente estoy nervioso.",
  ui_story_5070_50701301_16_dialog_content = "No te preocupes, simplemente considéralo como ver otro lado de Longzhou.",
  ui_story_5070_50701301_17_dialog_content = "Por fin estoy de vuelta. Por un momento pensé que pasaría mi vida en Astra...",
  ui_story_5070_50701301_18_dialog_content = "Ahora que lo pienso, siento que todo ha cambiado, aunque no ha pasado más de medio año desde que me alejé de Longzhou.",
  ui_story_5070_50701301_19_dialog_content = "Eso es suficiente. Ahora, ¡averigüemos qué haremos a continuación!",
  ui_story_5070_50701301_20_dialog_content = "¿Vamos a comer algo delicioso? ¿O a dormir bien por la noche?",
  ui_story_5070_50701301_21_dialog_content = "Regresa al Gremio Lin.",
  ui_story_5070_50701301_22_dialog_content = "Con la ayuda de la princesa Dantang y los demás, se puede demostrar que el Lin Guild fue condenado injustamente por el cargo de contrabando.",
  ui_story_5070_50701301_23_dialog_content = "Después de todo lo que ha pasado, debe haber muchos asuntos que necesitan tratamiento urgente.",
  ui_story_5070_50701301_24_dialog_content = "El maestro del gremio... ¡El maestro del gremio debe estar esperándome todavía!",
  ui_story_5070_50701301_25_dialog_content = "¡Oye! ¡Espera!",
  ui_story_5070_50701301_26_dialog_content = "No te preocupes.",
  ui_story_5070_50701301_27_dialog_content = "Informé todo en el momento en que aterrizamos y envié sirvientes para llevar las pruebas y el dinero a las Oficinas de Comercio Marítimo...",
  ui_story_5070_50701301_28_dialog_content = "El maestro del gremio ya debería estar liberado. Ahora es el momento para su reencuentro.",
  ui_story_5070_50701301_29_dialog_content = "Mira allá.",
  ui_story_5070_50701301_30_dialog_content = "... Es culpa de Xuan Ji. Hizo que la silla de ruedas de Zhong Xu fuera demasiado rápida.",
  ui_story_5070_50701301_31_dialog_content = "¡Hermano Zhong!",
  ui_story_5070_50701301_32_dialog_content = "¿Lin?",
  ui_story_5070_50701301_33_dialog_content = "Nunca esperé que aún saldrías a saludarme ahora que he perdido mis piernas.",
  ui_story_5070_50701301_34_dialog_content = "Tus palabras... No sé cómo responder a eso...",
  ui_story_5070_50701301_35_dialog_content = "Ni siquiera sé si debería expresar gratitud primero o disculparme contigo.",
  ui_story_5070_50701301_36_dialog_content = "No hay necesidad de tales palabras entre nosotros.",
  ui_story_5070_50701301_37_dialog_content = "Si realmente quieres hacer algo, da la bienvenida primero a Liqing y al Capitán Yuebai.",
  ui_story_5070_50701301_38_dialog_content = "¡Yo... Es suficiente para mí ver que estás bien!",
  ui_story_5070_50701301_39_dialog_content = "Oh, Jiu, por favor envía una carta por mí.",
  ui_story_5070_50701301_40_dialog_content = "Debo informar a mi familia de la misión completada y mi regreso seguro.",
  ui_story_5070_50701301_41_dialog_content = "Sí. Todos estarán felices por usted, Su Alteza.",
  ui_story_5070_50701301_42_dialog_content = "¿Algo malo, PlayerName?",
  ui_story_5070_50701301_43_dialog_content = "Muchas personas desembarcaron: Dantang, Jiu, Zhong Xu, Liqing, Xuan Ji y yo...",
  ui_story_5070_50701301_44_dialog_content = "¿Pero por qué siempre siento que estoy olvidando algo?",
  ui_story_5070_50701301_45_dialog_content = "Eh, olvídalo. Probablemente no es importante. ¡Vamos!",
  ui_story_5070_50701301_46_dialog_content = "Lady Xuan Ji, ¿está bien descargar estos bueyes de madera aquí?",
  ui_story_5070_50701301_47_dialog_content = "Seguro, gracias.",
  ui_story_5070_50701301_48_dialog_content = "No es gran cosa. Le debemos nuestro regreso seguro a usted, Lady Xuan Ji, y hemos aprendido bastante en el camino.",
  ui_story_5070_50701301_49_dialog_content = "Sería genial si pudiéramos navegar juntos de nuevo la próxima vez.",
  ui_story_5070_50701301_50_dialog_content = "Sí, espero que nos encontremos de nuevo.",
  ui_story_5070_50701301_X50_dialog_content = "¿Mmm? Su...",
  ui_story_5070_50701301_X51_dialog_content = "He estado fuera tanto tiempo que casi he olvidado cómo cada día se siente como primavera en la costa sur del Reino de Ji.",
  ui_story_5070_50701301_X52_dialog_content = "Nunca pensé que realmente podría regresar a Longzhou con lo que estaba buscando...",
  ui_story_5070_50701301_51_dialog_content = "...",
  ui_story_5070_50701301_52_dialog_content = "Está bien, ya has visto bastante.",
  ui_story_5070_50701301_53_dialog_content = "Entonces, ¿no tienes cosas más importantes que hacer ahora?",
  ui_story_5070_50701301_54_dialog_content = "Espera, ¿qué hay en este buey de madera...?",
  ui_story_5070_50701301_55_dialog_content = "¡Urgh!",
  ui_story_5070_50701301_56_dialog_content = "¿Está brillante afuera? Buenos días.",
  ui_story_5070_50701301_57_dialog_content = "¿Qué haces escondido ahí dentro?",
  ui_story_5070_50701301_58_dialog_content = "Es porque... Ugh, ¿me podrías dar una mano y sacarme primero? Gracias.",
  ui_story_5070_50701301_59_dialog_content = "Ay... Estoy tan adolorido de esconderme ahí.",
  ui_story_5070_50701301_60_dialog_content = "Quién iba a pensar que durante este viaje no solo nos encontraríamos con tormentas y Eclipsites, sino que también fuimos atacados por piratas.",
  ui_story_5070_50701301_61_dialog_content = "Afortunadamente, adiviné nuestra fortuna antes de zarpar.",
  ui_story_5070_50701301_62_dialog_content = "Me tomó días de investigación descifrar la adivinación del Caballo Yin y el Buey Yin. Probablemente corresponde a tu buey de madera.",
  ui_story_5070_50701301_63_dialog_content = "Así fue como encontré un lugar perfecto para esconderme. De lo contrario, este viaje lleno de desastres me habría costado la vida.",
  ui_story_5070_50701301_64_dialog_content = "Urgh...",
  ui_story_5070_50701301_65_dialog_content = "Eso me recuerda, te debo por usar este lugar.",
  ui_story_5070_50701301_66_dialog_content = "¿Qué tal una adivinación gratis?",
  ui_story_5070_50701301_67_dialog_content = "Está bien.",
  ui_story_5070_50701301_68_dialog_content = "Nosotros, los artesanos, valoramos mucho más nuestras creaciones que el destino.",
  ui_story_5070_50701301_69_dialog_content = "Incluso si presagias algo terrible, ¡eso no significa que no deba hacer lo que tenga que hacer!",
  ui_story_5070_50701301_70_dialog_content = "Bien. Buena suerte entonces.",
  ui_story_5070_50701301_71_dialog_content = "Adiós.",
  ui_story_5070_50701301_72_dialog_content = "(Vamos a ver... Mientras estaba en el buey de madera antes, dibujé...)",
  ui_story_5070_50701301_73_dialog_content = "(Tigre Yang y Dragón Yin? Interesante.)",
  ui_story_5070_50701301_74_dialog_content = "(Era un buey muerto y un caballo silencioso en el barco, así que me mantuve escondido y apenas logré escapar del peligro.)",
  ui_story_5070_50701301_X74_dialog_content = "(Ahora, es una señal de peligro.)",
  ui_story_5070_50701301_75_dialog_content = "(Xuan Ji siempre le dice a todos que se alejen del peligro, ¿pero ella está entrando en la guarida del tigre?)",
  ui_story_5070_50701301_76_dialog_content = "Envía una carta.",
  ui_story_5070_50701301_77_dialog_content = "Bueno verte de nuevo. Dos cartas, ambas para enviar al Reino Ye, ¿verdad?",
  ui_story_5070_50701301_78_dialog_content = "Quédese tranquilo. Serán entregados a tiempo.",
  ui_story_5070_50701301_79_dialog_content = "<color=#e8d9bb>No muy lejos del Poste</color>",
  ui_story_5070_50701301_80_dialog_content = "Ve a informar a nuestro señor; Frost Blade ha escoltado a la princesa de manera segura de vuelta a Longzhou.",
  ui_story_5070_50701301_81_dialog_content = "Cuíden a la gente en la oficina de correos; no dejen cabos sueltos para nuestro señor."
}
return config
